    parser.add_argument("--source-context-aux-loss-weight", type=float, default=0.0)
    parser.add_argument("--source-context-aux-classification-weight", type=float, default=0.0)
    parser.add_argument("--source-context-aux-consistency-weight", type=float, default=0.0)
    parser.add_argument("--source-context-aux-bbox-margin-ratio", type=float, default=0.04)
    parser.add_argument("--source-context-aux-attention-temperature", type=float, default=0.20)
