def _patch_objectness_loss_from_features(
    *,
    features: Dict[str, Tensor],
    positive_weight: float = 1.0,
) -> Tensor:
    objectness_logits = features.get("patch_objectness_logits")
    bbox_prior = features.get("patch_bbox_prior")
    if (
        not torch.is_tensor(objectness_logits)
        or objectness_logits.ndim != 2
        or not torch.is_tensor(bbox_prior)
        or bbox_prior.ndim != 2
        or tuple(objectness_logits.shape) != tuple(bbox_prior.shape)
    ):
        reference = next((value for value in features.values() if torch.is_tensor(value)), None)
        return reference.sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)

    key_padding_mask = features.get("memory_key_padding_mask")
    if torch.is_tensor(key_padding_mask) and tuple(key_padding_mask.shape) == tuple(objectness_logits.shape):
        valid = ~key_padding_mask.to(device=objectness_logits.device, dtype=torch.bool)
    else:
        valid = torch.ones_like(objectness_logits, dtype=torch.bool)
    if not bool(valid.any().detach().cpu().item()):
        return objectness_logits.sum() * 0.0

    targets = bbox_prior.to(device=objectness_logits.device, dtype=torch.float32).clamp(0.0, 1.0)
    logits = objectness_logits.float()
    pos_weight = logits.new_tensor(float(max(1e-6, positive_weight)))
    loss = F.binary_cross_entropy_with_logits(
        logits[valid],
        targets[valid],
        pos_weight=pos_weight,
    )
    return loss.to(dtype=objectness_logits.dtype)


def _patch_evidence_mil_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    pair: Union[str, Sequence[Tuple[int, int]]] = "0-1",
    top_k: int = 4,
    bbox_threshold: float = 0.05,
    positive_weight: float = 1.0,
) -> Tuple[Tensor, Dict[str, float]]:
    """Train-time MIL loss over dense patch logits for one confusing class pair."""

    reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
    stats = {
        "patch_evidence_mil_fraction": 0.0,
        "patch_evidence_mil_positive_score": 0.0,
        "patch_evidence_mil_negative_score": 0.0,
        "patch_evidence_mil_score_margin": 0.0,
        "patch_evidence_mil_bbox_fraction": 0.0,
    }
    patches = features.get("patches")
    if not torch.is_tensor(patches) or patches.ndim != 3:
        return reference.sum() * 0.0, stats

    module = getattr(model, "module", model)
    head = getattr(module, "head", None)
    if not callable(head):
        return patches.sum() * 0.0, stats

    parsed_pairs: List[Tuple[int, int]]
    if isinstance(pair, str):
        parsed_pairs = _parse_boundary_contrastive_pairs(pair, num_classes=0)
    else:
        parsed_pairs = [(int(left), int(right)) for left, right in pair]
    if len(parsed_pairs) != 1:
        raise ValueError("patch-evidence MIL hien chi ho tro mot pair moi lan.")
    left_class, right_class = parsed_pairs[0]
    if left_class < 0 or right_class < 0:
        raise ValueError("patch-evidence MIL khong ho tro pair dang rest.")

    batch_size, token_count, embed_dim = patches.shape
    flat_patches = patches.reshape(batch_size * token_count, embed_dim)
    local_logits = head(flat_patches)
    if not torch.is_tensor(local_logits) or local_logits.ndim != 2:
        return patches.sum() * 0.0, stats
    class_count = int(local_logits.size(-1))
    if left_class >= class_count or right_class >= class_count:
        return local_logits.sum() * 0.0, stats
    local_logits = local_logits.reshape(batch_size, token_count, class_count).float()

    key_padding_mask = features.get("memory_key_padding_mask")
    if torch.is_tensor(key_padding_mask) and key_padding_mask.shape[:2] == (batch_size, token_count):
        valid_mask = ~key_padding_mask.to(device=patches.device, dtype=torch.bool)
    else:
        valid_mask = torch.ones((batch_size, token_count), device=patches.device, dtype=torch.bool)
    empty_valid = ~valid_mask.any(dim=1)
    if bool(empty_valid.any().item()):
        valid_mask = valid_mask.clone()
        valid_mask[empty_valid] = True

    bbox_prior = features.get("patch_bbox_prior")
    if torch.is_tensor(bbox_prior) and bbox_prior.shape[:2] == (batch_size, token_count):
        bbox_weights = bbox_prior.to(device=patches.device, dtype=torch.float32).clamp(0.0, 1.0)
    else:
        bbox_weights = torch.ones((batch_size, token_count), device=patches.device, dtype=torch.float32)
    bbox_weights = bbox_weights * valid_mask.to(dtype=torch.float32)
    empty_bbox_weights = bbox_weights.sum(dim=1) <= 1e-6
    if bool(empty_bbox_weights.any().item()):
        bbox_weights = bbox_weights.clone()
        bbox_weights[empty_bbox_weights] = valid_mask[empty_bbox_weights].to(dtype=torch.float32)

    bbox_mask = (bbox_weights > float(max(0.0, bbox_threshold))) & valid_mask
    empty_bbox_mask = ~bbox_mask.any(dim=1)
    if bool(empty_bbox_mask.any().item()):
        bbox_mask = bbox_mask.clone()
        bbox_mask[empty_bbox_mask] = valid_mask[empty_bbox_mask]
    stats["patch_evidence_mil_bbox_fraction"] = float(
        bbox_mask.float().mean().detach().cpu().item()
    )

    margin = local_logits[:, :, right_class] - local_logits[:, :, left_class]
    masked_margin = margin.masked_fill(~bbox_mask, float("-inf"))
    k = max(1, min(int(top_k), int(token_count)))
    top_values = torch.topk(masked_margin, k=k, dim=1, largest=True, sorted=False).values
    finite = torch.isfinite(top_values)
    top_values = torch.where(finite, top_values, torch.zeros_like(top_values))
    score = top_values.sum(dim=1) / finite.to(dtype=top_values.dtype).sum(dim=1).clamp_min(1.0)

    target_indices = targets.to(device=patches.device, dtype=torch.long).view(-1)
    if int(target_indices.numel()) != batch_size:
        return local_logits.sum() * 0.0, stats
    pair_mask = (target_indices == int(left_class)) | (target_indices == int(right_class))
    if not bool(pair_mask.any().item()):
        return local_logits.sum() * 0.0, stats

    binary_targets = (target_indices[pair_mask] == int(right_class)).to(dtype=score.dtype)
    selected_scores = score[pair_mask]
    pos_weight = selected_scores.new_tensor(float(max(1e-6, positive_weight)))
    loss = F.binary_cross_entropy_with_logits(
        selected_scores.float(),
        binary_targets.float(),
        pos_weight=pos_weight,
    )
    stats["patch_evidence_mil_fraction"] = float(pair_mask.float().mean().detach().cpu().item())
    positive_mask = binary_targets > 0.5
    negative_mask = ~positive_mask
    if bool(positive_mask.any().item()):
        stats["patch_evidence_mil_positive_score"] = float(
            selected_scores[positive_mask].detach().float().mean().cpu().item()
        )
    if bool(negative_mask.any().item()):
        stats["patch_evidence_mil_negative_score"] = float(
            selected_scores[negative_mask].detach().float().mean().cpu().item()
        )
    stats["patch_evidence_mil_score_margin"] = (
        stats["patch_evidence_mil_positive_score"] - stats["patch_evidence_mil_negative_score"]
    )
    return loss.to(dtype=patches.dtype), stats


def _part_token_pairwise_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
) -> Tensor:
    pairwise_logits = features.get("part_token_pairwise_logits")
    pairs = getattr(model, "part_token_pairwise_pairs", [])
    if not torch.is_tensor(pairwise_logits) or pairwise_logits.ndim != 2 or not pairs:
        reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
        return reference.sum() * 0.0
    target_indices = targets.to(device=pairwise_logits.device, dtype=torch.long).view(-1)
    losses: List[Tensor] = []
    for pair_index, pair in enumerate(pairs):
        if pair_index >= int(pairwise_logits.size(1)):
            break
        left_class, right_class = [int(value) for value in pair]
        logits = pairwise_logits[:, pair_index].float()
        if left_class < 0:
            if right_class < 0:
                continue
            binary_targets = (target_indices == right_class).to(dtype=logits.dtype)
            losses.append(F.binary_cross_entropy_with_logits(logits, binary_targets))
            continue
        pair_mask = (target_indices == left_class) | (target_indices == right_class)
        if not bool(pair_mask.any().item()):
            continue
        binary_targets = (target_indices[pair_mask] == right_class).to(dtype=logits.dtype)
        losses.append(F.binary_cross_entropy_with_logits(logits[pair_mask], binary_targets))
    if not losses:
        return pairwise_logits.sum() * 0.0
    return torch.stack(losses).mean().to(dtype=pairwise_logits.dtype)


def _patch_evidence_router_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    positive_weight: float = 1.0,
) -> Tuple[Tensor, Dict[str, float]]:
    router_logits = features.get("patch_evidence_router_logits")
    pairs = getattr(model, "patch_evidence_router_pairs", [])
    stats = {
        "patch_evidence_router_fraction": 0.0,
        "patch_evidence_router_positive_logit": 0.0,
        "patch_evidence_router_negative_logit": 0.0,
        "patch_evidence_router_logit_margin": 0.0,
        "patch_evidence_router_probability": 0.0,
    }
    if not torch.is_tensor(router_logits) or router_logits.ndim != 2 or not pairs:
        reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
        return reference.sum() * 0.0, stats
    left_class, right_class = [int(value) for value in pairs[0]]
    if left_class < 0 or right_class < 0:
        return router_logits.sum() * 0.0, stats
    target_indices = targets.to(device=router_logits.device, dtype=torch.long).view(-1)
    if target_indices.numel() != int(router_logits.size(0)):
        return router_logits.sum() * 0.0, stats
    pair_mask = (target_indices == left_class) | (target_indices == right_class)
    if not bool(pair_mask.any().item()):
        return router_logits.sum() * 0.0, stats
    logits = router_logits[pair_mask, 0].float()
    binary_targets = (target_indices[pair_mask] == right_class).to(dtype=logits.dtype)
    pos_weight = logits.new_tensor(float(max(1e-6, positive_weight)))
    loss = F.binary_cross_entropy_with_logits(
        logits,
        binary_targets,
        pos_weight=pos_weight,
    )
    stats["patch_evidence_router_fraction"] = float(
        pair_mask.float().mean().detach().cpu().item()
    )
    probabilities = logits.detach().sigmoid()
    stats["patch_evidence_router_probability"] = float(
        probabilities.mean().detach().cpu().item()
    )
    positive_mask = binary_targets > 0.5
    negative_mask = ~positive_mask
    if bool(positive_mask.any().item()):
        stats["patch_evidence_router_positive_logit"] = float(
            logits[positive_mask].detach().mean().cpu().item()
        )
    if bool(negative_mask.any().item()):
        stats["patch_evidence_router_negative_logit"] = float(
            logits[negative_mask].detach().mean().cpu().item()
        )
    stats["patch_evidence_router_logit_margin"] = (
        stats["patch_evidence_router_positive_logit"]
        - stats["patch_evidence_router_negative_logit"]
    )
    return loss.to(dtype=router_logits.dtype), stats


def _patch_evidence_router_teacher_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    teacher_probabilities: Optional[Tensor],
    hard_labels: Optional[Tensor],
    targets,
    min_confidence: float = 0.60,
    min_pair_mass: float = 0.20,
    positive_weight: float = 1.0,
) -> Tuple[Tensor, Dict[str, float]]:
    router_logits = features.get("patch_evidence_router_logits")
    pairs = getattr(model, "patch_evidence_router_pairs", [])
    reference = next((value for value in features.values() if torch.is_tensor(value)), None)
    if reference is None:
        reference = teacher_probabilities if torch.is_tensor(teacher_probabilities) else None
    if reference is None:
        reference = hard_labels if torch.is_tensor(hard_labels) else None
    if reference is None:
        reference = torch.tensor(0.0)
    zero = reference.sum() * 0.0
    stats = {
        "patch_evidence_router_teacher_fraction": 0.0,
        "patch_evidence_router_teacher_pair_fraction": 0.0,
        "patch_evidence_router_teacher_pair_mass": 0.0,
        "patch_evidence_router_teacher_confidence": 0.0,
        "patch_evidence_router_teacher_probability": 0.0,
        "patch_evidence_router_teacher_target": 0.0,
        "patch_evidence_router_teacher_positive_fraction": 0.0,
    }
    if (
        teacher_probabilities is None
        or not torch.is_tensor(teacher_probabilities)
        or not torch.is_tensor(router_logits)
        or router_logits.ndim != 2
        or not pairs
    ):
        return zero, stats
    if teacher_probabilities.ndim != 2 or teacher_probabilities.size(0) != router_logits.size(0):
        return zero, stats

    left_class, right_class = [int(value) for value in pairs[0]]
    num_classes = int(teacher_probabilities.size(1))
    if (
        left_class < 0
        or right_class < 0
        or left_class >= num_classes
        or right_class >= num_classes
    ):
        return zero, stats
    if int(router_logits.size(1)) < 1:
        return zero, stats

    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=router_logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, teacher_probabilities)
    if target_indices is None or target_indices.numel() != int(router_logits.size(0)):
        return zero, stats

    teacher_probs = teacher_probabilities.to(
        device=router_logits.device,
        dtype=torch.float32,
    ).clamp(min=0.0)
    teacher_probs = teacher_probs / teacher_probs.sum(dim=1, keepdim=True).clamp(min=1e-12)
    teacher_pair_mass = (teacher_probs[:, left_class] + teacher_probs[:, right_class]).clamp(
        min=1e-12
    )
    teacher_target = (teacher_probs[:, right_class] / teacher_pair_mass).detach().clamp(
        min=1e-6,
        max=1.0 - 1e-6,
    )
    teacher_pair_confidence = torch.maximum(
        teacher_target,
        1.0 - teacher_target,
    )
    teacher_pair_prediction_is_right = teacher_target >= 0.5
    hard_pair_mask = (target_indices == left_class) | (target_indices == right_class)
    hard_binary_targets = (target_indices == right_class).to(dtype=torch.bool)
    teacher_hard_pair_agrees = teacher_pair_prediction_is_right == hard_binary_targets
    valid = (
        hard_pair_mask
        & teacher_hard_pair_agrees
        & (teacher_pair_mass >= float(min_pair_mass))
        & (teacher_pair_confidence >= float(min_confidence))
    )
    stats["patch_evidence_router_teacher_pair_fraction"] = float(
        hard_pair_mask.float().mean().detach().cpu().item()
    )
    if not bool(valid.any().item()):
        return zero, stats

    logits = router_logits[:, 0].float()
    per_sample = F.binary_cross_entropy_with_logits(
        logits[valid],
        teacher_target[valid],
        reduction="none",
    )
    weights = (
        teacher_pair_mass[valid].detach().clamp(min=1e-6)
        * teacher_pair_confidence[valid].detach().clamp(min=1e-6)
    )
    positive_mask = hard_binary_targets[valid]
    if bool(positive_mask.any().item()):
        weights = weights.clone()
        weights[positive_mask] = weights[positive_mask] * float(max(1e-6, positive_weight))
    loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
    selected_probabilities = logits[valid].detach().sigmoid()
    stats["patch_evidence_router_teacher_fraction"] = float(
        valid.float().mean().detach().cpu().item()
    )
    stats["patch_evidence_router_teacher_pair_mass"] = float(
        teacher_pair_mass[valid].detach().mean().cpu().item()
    )
    stats["patch_evidence_router_teacher_confidence"] = float(
        teacher_pair_confidence[valid].detach().mean().cpu().item()
    )
    stats["patch_evidence_router_teacher_probability"] = float(
        selected_probabilities.mean().detach().cpu().item()
    )
    stats["patch_evidence_router_teacher_target"] = float(
        teacher_target[valid].detach().mean().cpu().item()
    )
    stats["patch_evidence_router_teacher_positive_fraction"] = float(
        positive_mask.float().mean().detach().cpu().item()
    )
    return loss.to(dtype=router_logits.dtype), stats


def _local_zoom_auxiliary_loss_from_features(
    *,
    features: Dict[str, Tensor],
    targets: Tensor,
    criterion: nn.Module,
) -> Tensor:
    local_zoom_logits = features.get("local_zoom_logits")
    if not torch.is_tensor(local_zoom_logits) or local_zoom_logits.ndim != 2:
        reference = next((value for value in features.values() if torch.is_tensor(value)), None)
        return reference.sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)
    return criterion(local_zoom_logits, targets).to(dtype=local_zoom_logits.dtype)


def _high_frequency_texture_auxiliary_loss_from_features(
    *,
    features: Dict[str, Tensor],
    targets: Tensor,
    criterion: nn.Module,
) -> Tensor:
    high_frequency_logits = features.get("high_frequency_texture_logits")
    if not torch.is_tensor(high_frequency_logits) or high_frequency_logits.ndim != 2:
        reference = next((value for value in features.values() if torch.is_tensor(value)), None)
        return reference.sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)
    return criterion(high_frequency_logits, targets).to(dtype=high_frequency_logits.dtype)


def _high_frequency_texture_pairwise_loss_from_features(
    *,
    features: Dict[str, Tensor],
    targets: Tensor,
    pairs: str,
    num_classes: int,
) -> Tensor:
    high_frequency_logits = features.get("high_frequency_texture_logits")
    if not torch.is_tensor(high_frequency_logits) or high_frequency_logits.ndim != 2:
        reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
        return reference.sum() * 0.0
    parsed_pairs = _parse_boundary_contrastive_pairs(
        pairs,
        num_classes=int(num_classes),
    )
    target_indices = targets.to(
        device=high_frequency_logits.device,
        dtype=torch.long,
    ).view(-1)
    losses: List[Tensor] = []
    for left_class, right_class in parsed_pairs:
        if left_class < 0:
            if right_class < 0 or right_class >= int(high_frequency_logits.size(1)):
                continue
            logits = high_frequency_logits[:, right_class].float()
            binary_targets = (target_indices == right_class).to(dtype=logits.dtype)
            losses.append(F.binary_cross_entropy_with_logits(logits, binary_targets))
            continue
        if (
            left_class >= int(high_frequency_logits.size(1))
            or right_class >= int(high_frequency_logits.size(1))
        ):
            continue
        pair_mask = (target_indices == left_class) | (target_indices == right_class)
        if not bool(pair_mask.any().item()):
            continue
        margin_logits = (
            high_frequency_logits[pair_mask, right_class]
            - high_frequency_logits[pair_mask, left_class]
        ).float()
        binary_targets = (target_indices[pair_mask] == right_class).to(
            dtype=margin_logits.dtype
        )
        losses.append(F.binary_cross_entropy_with_logits(margin_logits, binary_targets))
    if not losses:
        return high_frequency_logits.sum() * 0.0
    return torch.stack(losses).mean().to(dtype=high_frequency_logits.dtype)


def _multi_granularity_auxiliary_loss_from_features(
    *,
    features: Dict[str, Tensor],
    targets: Tensor,
    criterion: nn.Module,
) -> Tensor:
    auxiliary_logits = features.get("multi_granularity_logits")
    if not isinstance(auxiliary_logits, dict) or not auxiliary_logits:
        reference = next((value for value in features.values() if torch.is_tensor(value)), None)
        return reference.sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)
    losses: List[Tensor] = []
    for logits in auxiliary_logits.values():
        if torch.is_tensor(logits) and logits.ndim == 2:
            losses.append(criterion(logits, targets).to(dtype=logits.dtype))
    if not losses:
        reference = next((value for value in auxiliary_logits.values() if torch.is_tensor(value)), None)
        return reference.sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)
    return torch.stack(losses).mean()


def _multi_granularity_refinement_loss_from_features(
    *,
    features: Dict[str, Tensor],
    teacher_logits: Tensor,
    temperature: float,
) -> Tuple[Tensor, Dict[str, object]]:
    auxiliary_logits = features.get("multi_granularity_logits")
    reference = teacher_logits if torch.is_tensor(teacher_logits) else None
    zero = (
        reference.sum() * 0.0
        if torch.is_tensor(reference)
        else torch.tensor(0.0)
    )
    if (
        not isinstance(auxiliary_logits, dict)
        or not auxiliary_logits
        or not torch.is_tensor(teacher_logits)
        or teacher_logits.ndim != 2
    ):
        return zero, {"count": 0, "used_layers": [], "teacher_entropy": 0.0}

    valid_layers: List[str] = []
    losses: List[Tensor] = []
    temp = float(max(float(temperature), 1e-6))
    teacher_probs = F.softmax(teacher_logits.detach().float() / temp, dim=1)
    teacher_entropy = (
        -(teacher_probs * teacher_probs.clamp(min=1e-12).log()).sum(dim=1).mean()
    )
    for layer_name, logits in auxiliary_logits.items():
        if (
            not torch.is_tensor(logits)
            or logits.ndim != 2
            or int(logits.numel()) == 0
            or int(logits.size(0)) != int(teacher_logits.size(0))
            or int(logits.size(1)) != int(teacher_logits.size(1))
        ):
            continue
        aux_log_probs = F.log_softmax(logits.float() / temp, dim=1)
        losses.append(
            F.kl_div(aux_log_probs, teacher_probs, reduction="batchmean") * (temp * temp)
        )
        valid_layers.append(str(layer_name))
    if not losses:
        return zero, {
            "count": 0,
            "used_layers": [],
            "teacher_entropy": float(teacher_entropy.detach().cpu().item()),
        }
    loss = torch.stack(losses).mean().to(dtype=teacher_logits.dtype)
    return loss, {
        "count": len(losses),
        "used_layers": valid_layers,
        "teacher_entropy": float(teacher_entropy.detach().cpu().item()),
    }


def _linear_head_weight_for_cam(model: nn.Module) -> Optional[Tensor]:
    base_model = getattr(model, "module", model)
    head = getattr(base_model, "head", None)
    if isinstance(head, nn.Linear):
        return head.weight
    weight = getattr(head, "weight", None)
    if torch.is_tensor(weight) and weight.ndim == 2:
        return weight
    return None


def _self_boosting_attention_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    classes: Union[str, Sequence[int], None],
    temperature: float,
) -> Tuple[Tensor, Dict[str, float]]:
    patches = features.get("patches")
    reference = patches if torch.is_tensor(patches) else targets
    zero = reference.sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)
    stats = {
        "self_boosting_attention_valid_fraction": 0.0,
        "self_boosting_attention_target_entropy": 0.0,
        "self_boosting_attention_target_peak": 0.0,
        "self_boosting_attention_projection_peak": 0.0,
        "self_boosting_attention_map_similarity": 0.0,
    }
    base_model = getattr(model, "module", model)
    projection = getattr(base_model, "self_boosting_attention_projection", None)
    head_weight = _linear_head_weight_for_cam(model)
    if (
        projection is None
        or not torch.is_tensor(head_weight)
        or not torch.is_tensor(patches)
        or patches.ndim != 3
        or targets.ndim != 1
        or int(patches.size(0)) != int(targets.numel())
    ):
        return zero, stats

    num_classes = int(head_weight.size(0))
    selected_classes = _parse_angular_margin_classes(classes, num_classes=num_classes)
    if selected_classes:
        class_mask = torch.zeros((num_classes,), device=targets.device, dtype=torch.bool)
        class_mask[torch.tensor(selected_classes, device=targets.device, dtype=torch.long)] = True
    else:
        class_mask = torch.ones((num_classes,), device=targets.device, dtype=torch.bool)
    target_indices = targets.to(device=patches.device, dtype=torch.long).view(-1)
    valid = (target_indices >= 0) & (target_indices < num_classes)
    valid = valid & class_mask.to(device=patches.device).gather(0, target_indices.clamp(0, num_classes - 1))
    if not bool(valid.any().item()):
        return zero, stats

    selected_patches = patches[valid]
    selected_targets = target_indices[valid]
    projection_scores = projection(selected_patches).squeeze(-1).float()
    class_vectors = head_weight.detach().to(device=patches.device, dtype=torch.float32).index_select(
        0,
        selected_targets,
    )
    target_scores = torch.einsum(
        "bnd,bd->bn",
        selected_patches.detach().float(),
        class_vectors,
    )
    key_padding_mask = features.get("memory_key_padding_mask")
    if torch.is_tensor(key_padding_mask):
        valid_patch_mask = ~key_padding_mask.to(device=patches.device, dtype=torch.bool)
        valid_patch_mask = valid_patch_mask[valid]
        if tuple(valid_patch_mask.shape) == tuple(target_scores.shape):
            projection_scores = projection_scores.masked_fill(~valid_patch_mask, -1.0e4)
            target_scores = target_scores.masked_fill(~valid_patch_mask, -1.0e4)

    temp = float(max(float(temperature), 1e-6))
    target_distribution = F.softmax(target_scores / temp, dim=1).detach()
    projection_log_distribution = F.log_softmax(projection_scores / temp, dim=1)
    loss = (
        F.kl_div(
            projection_log_distribution,
            target_distribution,
            reduction="batchmean",
        )
        * (temp * temp)
    ).to(dtype=patches.dtype)
    projection_distribution = projection_log_distribution.exp().detach()
    target_entropy = -(
        target_distribution * target_distribution.clamp(min=1e-12).log()
    ).sum(dim=1)
    map_similarity = F.cosine_similarity(
        projection_distribution.float(),
        target_distribution.float(),
        dim=1,
        eps=1e-8,
    )
    stats.update(
        {
            "self_boosting_attention_valid_fraction": float(
                valid.float().mean().detach().cpu().item()
            ),
            "self_boosting_attention_target_entropy": float(
                target_entropy.mean().detach().cpu().item()
            ),
            "self_boosting_attention_target_peak": float(
                target_distribution.max(dim=1).values.mean().detach().cpu().item()
            ),
            "self_boosting_attention_projection_peak": float(
                projection_distribution.max(dim=1).values.mean().detach().cpu().item()
            ),
            "self_boosting_attention_map_similarity": float(
                map_similarity.mean().detach().cpu().item()
            ),
        }
    )
    return loss, stats


def _multi_granularity_contrastive_loss_from_features(
    *,
    features: Dict[str, Tensor],
    targets: Tensor,
    teacher_probabilities: Optional[Tensor],
    criterion: nn.Module,
    pairs: str,
    num_classes: int,
    teacher_min_confidence: float = 0.0,
    require_agreement: bool = True,
    weight_mode: str = "filter",
    teacher_confidence_power: float = 1.0,
) -> Tuple[Tensor, Dict[str, object]]:
    auxiliary_features = features.get("multi_granularity_features")
    reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
    zero = reference.sum() * 0.0 if torch.is_tensor(reference) else targets.sum() * 0.0
    if not isinstance(auxiliary_features, dict) or not auxiliary_features or targets.ndim != 1:
        return zero, {
            "fraction": 0.0,
            "count": 0,
            "positive_pairs": 0,
            "used_layers": [],
            "reliability_mean": 0.0,
        }

    valid_embeddings = [
        embedding for embedding in auxiliary_features.values()
        if torch.is_tensor(embedding) and embedding.ndim == 2
    ]
    if not valid_embeddings:
        return zero, {
            "fraction": 0.0,
            "count": 0,
            "positive_pairs": 0,
            "used_layers": [],
            "reliability_mean": 0.0,
        }

    device = valid_embeddings[0].device
    target_indices = targets.to(device=device, dtype=torch.long).view(-1)
    if int(target_indices.numel()) != int(valid_embeddings[0].size(0)):
        return zero, {
            "fraction": 0.0,
            "count": 0,
            "positive_pairs": 0,
            "used_layers": [],
            "reliability_mean": 0.0,
        }

    parsed_pairs = _parse_boundary_contrastive_pairs(pairs, num_classes=int(num_classes))
    pair_valid = torch.zeros_like(target_indices, dtype=torch.bool)
    in_range = (target_indices >= 0) & (target_indices < int(num_classes))
    for left_class, right_class in parsed_pairs:
        if int(left_class) < 0 or int(right_class) < 0:
            pair_valid = pair_valid | in_range
        else:
            pair_valid = pair_valid | (target_indices == int(left_class)) | (
                target_indices == int(right_class)
            )

    teacher_valid = torch.ones_like(pair_valid, dtype=torch.bool)
    reliability = torch.ones_like(target_indices, dtype=torch.float32)
    if (
        teacher_probabilities is not None
        and torch.is_tensor(teacher_probabilities)
        and teacher_probabilities.ndim == 2
        and int(teacher_probabilities.size(0)) == int(target_indices.numel())
        and int(teacher_probabilities.size(1)) == int(num_classes)
    ):
        teacher_probs = teacher_probabilities.to(device=device, dtype=torch.float32).clamp(min=0.0)
        teacher_probs = teacher_probs / teacher_probs.sum(dim=1, keepdim=True).clamp(min=1e-12)
        teacher_confidence, teacher_predictions = teacher_probs.max(dim=1)
        top2 = torch.topk(teacher_probs, k=min(2, int(teacher_probs.size(1))), dim=1).values
        teacher_margin = (
            (top2[:, 0] - top2[:, 1]).clamp(min=0.0)
            if int(top2.size(1)) > 1
            else teacher_confidence
        )
        teacher_valid = teacher_confidence >= float(teacher_min_confidence)
        if bool(require_agreement):
            teacher_valid = teacher_valid & (teacher_predictions == target_indices)
        mode = str(weight_mode or "filter").strip().lower()
        if mode == "confidence_margin":
            reliability = (teacher_confidence * teacher_margin).clamp(min=0.0)
        elif mode == "confidence":
            reliability = teacher_confidence.clamp(min=0.0)
        else:
            reliability = torch.ones_like(teacher_confidence)
        if float(teacher_confidence_power) > 0.0:
            reliability = reliability.pow(float(teacher_confidence_power))
    elif bool(require_agreement) or float(teacher_min_confidence) > 0.0:
        teacher_valid = torch.zeros_like(pair_valid, dtype=torch.bool)

    selected = pair_valid & teacher_valid
    selected_count = int(selected.sum().detach().cpu().item())
    fraction = float(selected_count / max(1, int(target_indices.numel())))
    if selected_count < 2:
        return zero, {
            "fraction": fraction,
            "count": selected_count,
            "positive_pairs": 0,
            "used_layers": [],
            "reliability_mean": 0.0,
        }

    selected_targets = target_indices[selected]
    off_diagonal = ~torch.eye(selected_count, device=device, dtype=torch.bool)
    positive_pairs = int(
        ((selected_targets.unsqueeze(0) == selected_targets.unsqueeze(1)) & off_diagonal)
        .sum()
        .detach()
        .cpu()
        .item()
    )
    if positive_pairs <= 0:
        return zero, {
            "fraction": fraction,
            "count": selected_count,
            "positive_pairs": 0,
            "used_layers": [],
            "reliability_mean": 0.0,
        }

    mode = str(weight_mode or "filter").strip().lower()
    sample_weights = None
    selected_reliability = reliability[selected].detach().clamp(min=1e-6)
    if mode in {"confidence", "confidence_margin"}:
        sample_weights = selected_reliability

    layer_losses: List[Tensor] = []
    used_layers: List[str] = []
    for layer_key, embedding in auxiliary_features.items():
        if not torch.is_tensor(embedding) or embedding.ndim != 2:
            continue
        if int(embedding.size(0)) != int(target_indices.numel()):
            continue
        layer_losses.append(
            criterion(
                embedding[selected],
                selected_targets,
                sample_weights=sample_weights,
            ).to(dtype=embedding.dtype)
        )
        used_layers.append(str(layer_key))

    if not layer_losses:
        return zero, {
            "fraction": fraction,
            "count": selected_count,
            "positive_pairs": positive_pairs,
            "used_layers": used_layers,
            "reliability_mean": float(selected_reliability.mean().detach().cpu().item()),
        }
    return torch.stack(layer_losses).mean(), {
        "fraction": fraction,
        "count": selected_count,
        "positive_pairs": positive_pairs,
        "used_layers": used_layers,
        "reliability_mean": float(selected_reliability.mean().detach().cpu().item()),
    }


def _focus_class_auxiliary_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    positive_weight: float = 1.0,
) -> Tensor:
    focus_logits = features.get("focus_class_logits")
    if not torch.is_tensor(focus_logits) or focus_logits.ndim != 1:
        reference = next((value for value in features.values() if torch.is_tensor(value)), None)
        return reference.sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)
    target_indices = targets.to(device=focus_logits.device, dtype=torch.long).view(-1)
    if int(target_indices.numel()) != int(focus_logits.numel()):
        return focus_logits.sum() * 0.0
    focus_class_index = int(getattr(model, "focus_class_index", 1))
    binary_targets = (target_indices == focus_class_index).to(dtype=focus_logits.dtype)
    pos_weight = focus_logits.new_tensor(float(max(1e-6, positive_weight)))
    return F.binary_cross_entropy_with_logits(
        focus_logits.float(),
        binary_targets.float(),
        pos_weight=pos_weight.float(),
    ).to(dtype=focus_logits.dtype)


def _class_independent_loss_from_features(
    *,
    features: Dict[str, Tensor],
    targets: Tensor,
    positive_weight: float = 1.0,
) -> Tuple[Tensor, Dict[str, Tensor]]:
    ova_logits = features.get("class_independent_logits")
    reference = next((value for value in features.values() if torch.is_tensor(value)), None)
    if not torch.is_tensor(ova_logits) or ova_logits.ndim != 2:
        zero = reference.sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)
        stats = {
            "positive_probability": zero.detach(),
            "negative_probability": zero.detach(),
            "probability_margin": zero.detach(),
            "positive_count": zero.detach(),
        }
        return zero, stats

    target_indices = targets.to(device=ova_logits.device, dtype=torch.long).view(-1)
    if int(target_indices.numel()) != int(ova_logits.size(0)):
        zero = ova_logits.sum() * 0.0
        stats = {
            "positive_probability": zero.detach(),
            "negative_probability": zero.detach(),
            "probability_margin": zero.detach(),
            "positive_count": zero.detach(),
        }
        return zero, stats
    if torch.any((target_indices < 0) | (target_indices >= int(ova_logits.size(1)))):
        raise ValueError("class-independent targets nam ngoai khoang num_classes.")

    binary_targets = F.one_hot(
        target_indices,
        num_classes=int(ova_logits.size(1)),
    ).to(device=ova_logits.device, dtype=ova_logits.dtype)
    pos_weight = ova_logits.new_full(
        (int(ova_logits.size(1)),),
        float(max(1e-6, positive_weight)),
    )
    loss = F.binary_cross_entropy_with_logits(
        ova_logits.float(),
        binary_targets.float(),
        pos_weight=pos_weight.float(),
    ).to(dtype=ova_logits.dtype)
    with torch.no_grad():
        probabilities = ova_logits.float().sigmoid()
        positive_count = binary_targets.sum().clamp(min=1.0)
        negative_mask = 1.0 - binary_targets
        negative_count = negative_mask.sum().clamp(min=1.0)
        positive_probability = (
            probabilities * binary_targets.float()
        ).sum() / positive_count.float()
        negative_probability = (
            probabilities * negative_mask.float()
        ).sum() / negative_count.float()
        probability_margin = positive_probability - negative_probability
    stats = {
        "positive_probability": positive_probability.detach().to(dtype=ova_logits.dtype),
        "negative_probability": negative_probability.detach().to(dtype=ova_logits.dtype),
        "probability_margin": probability_margin.detach().to(dtype=ova_logits.dtype),
        "positive_count": positive_count.detach().to(dtype=ova_logits.dtype),
    }
    return loss, stats


def _focus_tversky_loss_from_logits(
    *,
    logits: Tensor,
    targets: Tensor,
    focus_class: int = 1,
    alpha: float = 0.70,
    beta: float = 0.30,
    gamma: float = 1.0,
    probability_power: float = 1.0,
    eps: float = 1e-6,
) -> Tuple[Tensor, Dict[str, Tensor]]:
    """Differentiable one-vs-rest Tversky loss for focus-class F1 pressure."""
    if not torch.is_tensor(logits) or logits.ndim != 2:
        raise ValueError("focus Tversky yeu cau logits shape [batch, num_classes].")
    if not torch.is_tensor(targets):
        raise ValueError("focus Tversky yeu cau target tensor.")
    target_indices = targets
    if target_indices.ndim == 2:
        if target_indices.size(1) != logits.size(1):
            raise ValueError("Soft targets cua focus Tversky khong khop num_classes.")
        target_indices = target_indices.argmax(dim=1)
    target_indices = target_indices.to(device=logits.device, dtype=torch.long).view(-1)
    if int(target_indices.numel()) != int(logits.size(0)):
        raise ValueError("focus Tversky target batch size khong khop logits.")
    focus_index = int(focus_class)
    if focus_index < 0 or focus_index >= int(logits.size(1)):
        raise ValueError("focus Tversky focus_class ngoai khoang num_classes.")

    probabilities = torch.softmax(logits.float(), dim=1)[:, focus_index]
    if float(probability_power) != 1.0:
        probabilities = probabilities.clamp(min=0.0, max=1.0).pow(float(probability_power))
    binary_targets = (target_indices == focus_index).to(dtype=probabilities.dtype)
    true_positive = (probabilities * binary_targets).sum()
    false_positive = (probabilities * (1.0 - binary_targets)).sum()
    false_negative = ((1.0 - probabilities) * binary_targets).sum()
    denominator = (
        true_positive
        + float(alpha) * false_positive
        + float(beta) * false_negative
        + float(eps)
    )
    index = (true_positive + float(eps)) / denominator.clamp(min=float(eps))
    loss = (1.0 - index).clamp(min=0.0, max=1.0).pow(float(gamma))
    stats = {
        "index": index.detach().to(dtype=logits.dtype),
        "tp": true_positive.detach().to(dtype=logits.dtype),
        "fp": false_positive.detach().to(dtype=logits.dtype),
        "fn": false_negative.detach().to(dtype=logits.dtype),
        "positive_count": binary_targets.sum().detach().to(dtype=logits.dtype),
        "mean_probability": probabilities.mean().detach().to(dtype=logits.dtype),
    }
    return loss.to(dtype=logits.dtype), stats


def _focus_auc_rank_loss_from_logits(
    *,
    logits: Tensor,
    targets: Tensor,
    focus_class: int = 1,
    negative_classes: Union[str, Sequence[int]] = "0,2,4",
    margin: float = 0.04,
    temperature: float = 0.12,
    hard_fraction: float = 0.50,
) -> Tuple[Tensor, Dict[str, Tensor]]:
    """Pairwise one-vs-rest ranking surrogate for a rare focus class."""
    if not torch.is_tensor(logits) or logits.ndim != 2:
        raise ValueError("focus AUC-rank yeu cau logits shape [batch, num_classes].")
    if not torch.is_tensor(targets):
        raise ValueError("focus AUC-rank yeu cau target tensor.")

    zero = logits.sum() * 0.0
    empty_stats = {
        "positive_count": zero.detach(),
        "negative_count": zero.detach(),
        "pair_count": zero.detach(),
        "selected_pair_fraction": zero.detach(),
        "positive_score": zero.detach(),
        "negative_score": zero.detach(),
        "score_gap": zero.detach(),
        "positive_probability": zero.detach(),
        "negative_probability": zero.detach(),
    }
    if logits.size(0) == 0:
        return zero, empty_stats

    target_indices = targets
    if target_indices.ndim == 2:
        if target_indices.size(1) != logits.size(1):
            raise ValueError("Soft targets cua focus AUC-rank khong khop num_classes.")
        target_indices = target_indices.argmax(dim=1)
    target_indices = target_indices.to(device=logits.device, dtype=torch.long).view(-1)
    if int(target_indices.numel()) != int(logits.size(0)):
        raise ValueError("focus AUC-rank target batch size khong khop logits.")

    num_classes = int(logits.size(1))
    focus = int(focus_class)
    if focus < 0 or focus >= num_classes:
        raise ValueError(f"focus AUC-rank class {focus} nam ngoai [0, {num_classes - 1}].")

    negatives = _parse_angular_margin_classes(
        negative_classes,
        num_classes=num_classes,
    )
    negatives = [class_index for class_index in negatives if int(class_index) != focus]
    if not negatives:
        return zero, empty_stats

    negative_tensor = torch.tensor(negatives, device=logits.device, dtype=torch.long)
    positive_mask = target_indices == focus
    negative_mask = (
        (target_indices >= 0)
        & (target_indices < num_classes)
        & torch.isin(target_indices, negative_tensor)
    )
    if not bool(positive_mask.any().item()) or not bool(negative_mask.any().item()):
        return zero, empty_stats

    candidate_tensor = torch.tensor([focus, *negatives], device=logits.device, dtype=torch.long)
    candidate_logits = logits.index_select(1, candidate_tensor).float()
    focus_binary_scores = (
        candidate_logits[:, 0]
        - torch.logsumexp(candidate_logits[:, 1:], dim=1)
    )
    positive_scores = focus_binary_scores[positive_mask]
    negative_scores = focus_binary_scores[negative_mask]
    pair_losses = F.softplus(
        (negative_scores[:, None] - positive_scores[None, :] + float(margin))
        / float(temperature)
    ) * float(temperature)
    flat_losses = pair_losses.flatten()
    selected_fraction = 1.0
    if float(hard_fraction) < 1.0 and int(flat_losses.numel()) > 1:
        selected_count = max(1, int(math.ceil(int(flat_losses.numel()) * float(hard_fraction))))
        selected_count = min(selected_count, int(flat_losses.numel()))
        flat_losses = torch.topk(flat_losses, k=selected_count, largest=True, sorted=False).values
        selected_fraction = float(selected_count) / float(pair_losses.numel())
    loss = flat_losses.mean().to(dtype=logits.dtype)

    with torch.no_grad():
        probabilities = torch.softmax(logits.float(), dim=1)[:, focus]
        positive_probability = probabilities[positive_mask].mean()
        negative_probability = probabilities[negative_mask].mean()
        positive_score = positive_scores.mean()
        negative_score = negative_scores.mean()
        score_gap = positive_score - negative_score
        stats = {
            "positive_count": positive_mask.sum().to(dtype=logits.dtype).detach(),
            "negative_count": negative_mask.sum().to(dtype=logits.dtype).detach(),
            "pair_count": logits.new_tensor(float(pair_losses.numel())).detach(),
            "selected_pair_fraction": logits.new_tensor(float(selected_fraction)).detach(),
            "positive_score": positive_score.to(dtype=logits.dtype).detach(),
            "negative_score": negative_score.to(dtype=logits.dtype).detach(),
            "score_gap": score_gap.to(dtype=logits.dtype).detach(),
            "positive_probability": positive_probability.to(dtype=logits.dtype).detach(),
            "negative_probability": negative_probability.to(dtype=logits.dtype).detach(),
        }
    return loss, stats


def _focus_partial_auc_loss_from_logits(
    *,
    logits: Tensor,
    targets: Tensor,
    focus_class: int = 1,
    negative_classes: Union[str, Sequence[int]] = "0,2,4",
    margin: float = 0.04,
    temperature: float = 0.12,
    negative_fraction: float = 0.25,
    positive_fraction: float = 0.30,
    positive_weight: float = 0.45,
    min_negative_probability: float = 0.05,
) -> Tuple[Tensor, Dict[str, Tensor]]:
    """Two-way pAUC-lite guard for a rare focus class.

    This only updates the highest-risk false-positive negatives and the
    lowest-margin positives in the batch, unlike plain all-pair AUC ranking.
    """
    if not torch.is_tensor(logits) or logits.ndim != 2:
        raise ValueError("focus partial-AUC yeu cau logits shape [batch, num_classes].")
    if not torch.is_tensor(targets):
        raise ValueError("focus partial-AUC yeu cau target tensor.")

    zero = logits.sum() * 0.0
    empty_stats = {
        "loss": zero.detach(),
        "negative_loss": zero.detach(),
        "positive_loss": zero.detach(),
        "positive_count": zero.detach(),
        "negative_count": zero.detach(),
        "selected_positive_count": zero.detach(),
        "selected_negative_count": zero.detach(),
        "selected_positive_fraction": zero.detach(),
        "selected_negative_fraction": zero.detach(),
        "positive_probability": zero.detach(),
        "negative_probability": zero.detach(),
        "positive_score": zero.detach(),
        "negative_score": zero.detach(),
        "score_gap": zero.detach(),
    }
    if logits.size(0) == 0:
        return zero, empty_stats

    target_indices = targets
    if target_indices.ndim == 2:
        if target_indices.size(1) != logits.size(1):
            raise ValueError("Soft targets cua focus partial-AUC khong khop num_classes.")
        target_indices = target_indices.argmax(dim=1)
    target_indices = target_indices.to(device=logits.device, dtype=torch.long).view(-1)
    if int(target_indices.numel()) != int(logits.size(0)):
        raise ValueError("focus partial-AUC target batch size khong khop logits.")

    num_classes = int(logits.size(1))
    focus = int(focus_class)
    if focus < 0 or focus >= num_classes:
        raise ValueError(f"focus partial-AUC class {focus} nam ngoai [0, {num_classes - 1}].")

    negatives = _parse_angular_margin_classes(
        negative_classes,
        num_classes=num_classes,
    )
    negatives = [class_index for class_index in negatives if int(class_index) != focus]
    if not negatives:
        return zero, empty_stats

    negative_tensor = torch.tensor(negatives, device=logits.device, dtype=torch.long)
    valid_targets = (target_indices >= 0) & (target_indices < num_classes)
    positive_mask = valid_targets & (target_indices == focus)
    negative_mask = valid_targets & torch.isin(target_indices, negative_tensor)
    if not bool(positive_mask.any().item()) and not bool(negative_mask.any().item()):
        return zero, empty_stats

    logits_float = logits.float()
    focus_logits = logits_float[:, focus]
    probabilities = torch.softmax(logits_float, dim=1)[:, focus]
    row_indices = torch.arange(logits.size(0), device=logits.device)

    negative_scores = logits_float.new_zeros((0,))
    negative_loss = zero
    selected_negative_count = 0
    selected_negative_fraction = 0.0
    if bool(negative_mask.any().item()):
        target_logits = logits_float[row_indices[negative_mask], target_indices[negative_mask]]
        negative_scores = focus_logits[negative_mask] - target_logits
        negative_probabilities = probabilities[negative_mask]
        eligible = negative_probabilities >= float(min_negative_probability)
        if not bool(eligible.any().item()):
            eligible = torch.ones_like(negative_probabilities, dtype=torch.bool)
        eligible_scores = negative_scores[eligible]
        if int(eligible_scores.numel()) > 0:
            negative_fraction_value = min(max(float(negative_fraction), 1e-6), 1.0)
            selected_negative_count = max(
                1,
                int(math.ceil(int(eligible_scores.numel()) * negative_fraction_value)),
            )
            selected_negative_count = min(selected_negative_count, int(eligible_scores.numel()))
            selected_negative_scores = torch.topk(
                eligible_scores,
                k=selected_negative_count,
                largest=True,
                sorted=False,
            ).values
            selected_negative_fraction = float(selected_negative_count) / float(
                max(1, int(negative_scores.numel()))
            )
            negative_loss = (
                F.softplus(
                    (selected_negative_scores + float(margin)) / float(temperature)
                )
                * float(temperature)
            ).mean().to(dtype=logits.dtype)

    positive_scores = logits_float.new_zeros((0,))
    positive_loss = zero
    selected_positive_count = 0
    selected_positive_fraction = 0.0
    if bool(positive_mask.any().item()):
        rival_logits = logits_float.index_select(1, negative_tensor).max(dim=1).values
        positive_scores = rival_logits[positive_mask] - focus_logits[positive_mask]
        positive_fraction_value = min(max(float(positive_fraction), 1e-6), 1.0)
        selected_positive_count = max(
            1,
            int(math.ceil(int(positive_scores.numel()) * positive_fraction_value)),
        )
        selected_positive_count = min(selected_positive_count, int(positive_scores.numel()))
        selected_positive_scores = torch.topk(
            positive_scores,
            k=selected_positive_count,
            largest=True,
            sorted=False,
        ).values
        selected_positive_fraction = float(selected_positive_count) / float(
            max(1, int(positive_scores.numel()))
        )
        positive_loss = (
            F.softplus(
                (selected_positive_scores + float(margin)) / float(temperature)
            )
            * float(temperature)
        ).mean().to(dtype=logits.dtype)

    loss = negative_loss + max(float(positive_weight), 0.0) * positive_loss

    with torch.no_grad():
        positive_probability = (
            probabilities[positive_mask].mean()
            if bool(positive_mask.any().item())
            else logits_float.new_tensor(0.0)
        )
        negative_probability = (
            probabilities[negative_mask].mean()
            if bool(negative_mask.any().item())
            else logits_float.new_tensor(0.0)
        )
        positive_score = (
            (-positive_scores).mean()
            if int(positive_scores.numel()) > 0
            else logits_float.new_tensor(0.0)
        )
        negative_score = (
            negative_scores.mean()
            if int(negative_scores.numel()) > 0
            else logits_float.new_tensor(0.0)
        )
        stats = {
            "loss": loss.detach().to(dtype=logits.dtype),
            "negative_loss": negative_loss.detach().to(dtype=logits.dtype),
            "positive_loss": positive_loss.detach().to(dtype=logits.dtype),
            "positive_count": positive_mask.sum().to(dtype=logits.dtype).detach(),
            "negative_count": negative_mask.sum().to(dtype=logits.dtype).detach(),
            "selected_positive_count": logits.new_tensor(float(selected_positive_count)).detach(),
            "selected_negative_count": logits.new_tensor(float(selected_negative_count)).detach(),
            "selected_positive_fraction": logits.new_tensor(float(selected_positive_fraction)).detach(),
            "selected_negative_fraction": logits.new_tensor(float(selected_negative_fraction)).detach(),
            "positive_probability": positive_probability.to(dtype=logits.dtype).detach(),
            "negative_probability": negative_probability.to(dtype=logits.dtype).detach(),
            "positive_score": positive_score.to(dtype=logits.dtype).detach(),
            "negative_score": negative_score.to(dtype=logits.dtype).detach(),
            "score_gap": (positive_score - negative_score).to(dtype=logits.dtype).detach(),
        }
    return loss.to(dtype=logits.dtype), stats


def _denormalize_classification_images(images: Tensor) -> Tensor:
    mean = torch.tensor(IMAGENET_MEAN, device=images.device, dtype=images.dtype).view(1, 3, 1, 1)
    std = torch.tensor(IMAGENET_STD, device=images.device, dtype=images.dtype).view(1, 3, 1, 1)
    return (images * std + mean).clamp(0.0, 1.0)


def _normalize_classification_images(images: Tensor) -> Tensor:
    mean = torch.tensor(IMAGENET_MEAN, device=images.device, dtype=images.dtype).view(1, 3, 1, 1)
    std = torch.tensor(IMAGENET_STD, device=images.device, dtype=images.dtype).view(1, 3, 1, 1)
    return (images.clamp(0.0, 1.0) - mean) / std.clamp(min=1e-6)


def _odd_kernel_size(value: int, minimum: int = 3) -> int:
    kernel = max(int(minimum), int(value))
    if kernel % 2 == 0:
        kernel += 1
    return kernel


def _background_counterfactual_images(
    images: Tensor,
    *,
    mode: str,
    margin: float,
    blur_kernel: int,
) -> Tensor:
    normalized_mode = str(mode or "desaturate_blur").strip().lower().replace("-", "_")
    if normalized_mode not in {"gray", "blur", "mean", "desaturate_blur"}:
        raise ValueError(
            "background_counterfactual_mode chi ho tro gray, blur, mean, desaturate_blur."
        )
    with torch.no_grad():
        foreground = _pseudo_foreground_mask_from_normalized_images(
            images.detach(),
            margin=margin,
        ).to(device=images.device, dtype=images.dtype)
        kernel = _odd_kernel_size(int(blur_kernel), minimum=3)
        padding = kernel // 2
        soft_mask = F.avg_pool2d(foreground, kernel_size=kernel, stride=1, padding=padding).clamp(0.0, 1.0)
        rgb = _denormalize_classification_images(images.detach())
        luminance = (
            0.299 * rgb[:, 0:1]
            + 0.587 * rgb[:, 1:2]
            + 0.114 * rgb[:, 2:3]
        )
        if normalized_mode == "gray":
            background = luminance.expand_as(rgb)
        elif normalized_mode == "blur":
            background = F.avg_pool2d(rgb, kernel_size=kernel, stride=1, padding=padding)
        elif normalized_mode == "mean":
            background = rgb.flatten(2).mean(dim=2).view(rgb.size(0), rgb.size(1), 1, 1).expand_as(rgb)
        else:
            gray = luminance.expand_as(rgb)
            background = F.avg_pool2d(gray, kernel_size=kernel, stride=1, padding=padding)
        counterfactual_rgb = (soft_mask * rgb + (1.0 - soft_mask) * background).clamp(0.0, 1.0)
        return _normalize_classification_images(counterfactual_rgb).to(dtype=images.dtype)


def _background_counterfactual_consistency_loss(
    *,
    model: nn.Module,
    images: Tensor,
    logits: Tensor,
    probability: float,
    mode: str,
    margin: float,
    blur_kernel: int,
    temperature: float,
    amp: bool,
    device: torch.device,
) -> Tuple[Tensor, float]:
    probability = max(0.0, min(1.0, float(probability)))
    if probability <= 0.0 or images.size(0) <= 0:
        return logits.sum() * 0.0, 0.0
    selected = torch.rand(images.size(0), device=images.device) < probability
    if not bool(selected.any().item()):
        return logits.sum() * 0.0, 0.0
    selected_indices = selected.nonzero(as_tuple=False).flatten()
    selected_images = images.index_select(0, selected_indices)
    counterfactual_images = _background_counterfactual_images(
        selected_images,
        mode=mode,
        margin=margin,
        blur_kernel=blur_kernel,
    )
    with autocast_context(device, amp):
        _, counterfactual_outputs = _forward_model_outputs(
            model,
            counterfactual_images,
            image_valid_mask=None,
        )
        counterfactual_logits, _ = extract_bbox_from_model_output(counterfactual_outputs)
    temperature = max(0.05, float(temperature))
    source_logits = logits.index_select(0, selected_indices).detach()
    target_probabilities = F.softmax(source_logits.float() / temperature, dim=1)
    log_probabilities = F.log_softmax(counterfactual_logits.float() / temperature, dim=1)
    loss = F.kl_div(
        log_probabilities,
        target_probabilities,
        reduction="batchmean",
    ) * (temperature ** 2)
    return loss.to(dtype=logits.dtype), float(selected_indices.numel()) / float(images.size(0))


def _background_focus_suppression_loss(
    *,
    model: nn.Module,
    images: Tensor,
    logits: Tensor,
    hard_labels: Optional[Tensor],
    targets,
    bbox_metadata: Optional[Tensor],
    probability: float,
    focus_class: int,
    negative_classes: Union[str, Sequence[int]],
    margin: float,
    min_probability: float,
    probability_power: float,
    mode: str,
    counterfactual_margin: float,
    blur_kernel: int,
    amp: bool,
    device: torch.device,
) -> Tuple[Tensor, float, Tensor, Tensor]:
    zero = logits.sum() * 0.0
    if logits.ndim != 2 or logits.size(0) == 0:
        return zero, 0.0, zero.detach(), zero.detach()

    num_classes = int(logits.size(1))
    focus = int(focus_class)
    if focus < 0 or focus >= num_classes:
        raise ValueError(
            f"background focus suppression class {focus} nam ngoai [0, {num_classes - 1}]."
        )
    negatives = _parse_angular_margin_classes(
        negative_classes,
        num_classes=num_classes,
    )
    negatives = [class_index for class_index in negatives if int(class_index) != focus]
    if not negatives:
        return zero, 0.0, zero.detach(), zero.detach()

    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, logits)
    if target_indices is None or target_indices.numel() != logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    probabilities = torch.softmax(logits.float(), dim=1).to(dtype=logits.dtype)
    focus_probabilities = probabilities[:, focus].clamp(min=0.0, max=1.0)
    negative_tensor = torch.tensor(negatives, device=logits.device, dtype=torch.long)
    valid = (
        (target_indices >= 0)
        & (target_indices < num_classes)
        & torch.isin(target_indices, negative_tensor)
    )
    if float(min_probability) > 0.0:
        valid = valid & (focus_probabilities >= float(min_probability))

    probability = max(0.0, min(1.0, float(probability)))
    if probability < 1.0:
        valid = valid & (torch.rand(logits.size(0), device=logits.device) < probability)
    if not bool(valid.any().item()):
        return zero, 0.0, focus_probabilities.detach().mean(), zero.detach()

    selected_indices = valid.nonzero(as_tuple=False).flatten()
    selected_images = images.index_select(0, selected_indices)
    counterfactual_images = _background_counterfactual_images(
        selected_images,
        mode=mode,
        margin=counterfactual_margin,
        blur_kernel=blur_kernel,
    )
    selected_bbox_metadata = None
    if torch.is_tensor(bbox_metadata) and bbox_metadata.size(0) == images.size(0):
        selected_bbox_metadata = bbox_metadata.index_select(
            0,
            selected_indices.to(device=bbox_metadata.device),
        )
    with autocast_context(device, amp):
        _, counterfactual_outputs = _forward_model_outputs(
            model,
            counterfactual_images,
            image_valid_mask=None,
            bbox_metadata=selected_bbox_metadata,
        )
        counterfactual_logits, _ = extract_bbox_from_model_output(counterfactual_outputs)

    source_focus = focus_probabilities.index_select(0, selected_indices).float()
    counterfactual_focus = (
        torch.softmax(counterfactual_logits.float(), dim=1)[:, focus]
        .detach()
        .clamp(min=0.0, max=1.0)
    )
    delta = source_focus - counterfactual_focus
    per_sample = F.relu(delta - float(margin))
    weights = source_focus.detach().pow(float(probability_power)).clamp(min=1e-6)
    loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
    fraction = float(valid.float().mean().detach().cpu().item())
    return (
        loss.to(dtype=logits.dtype),
        fraction,
        focus_probabilities.detach().mean(),
        delta.detach().mean().to(dtype=logits.dtype),
    )


def _source_context_focus_suppression_loss(
    *,
    logits: Tensor,
    source_logits: Tensor,
    hard_labels: Optional[Tensor],
    targets,
    probability: float,
    focus_class: int,
    negative_classes: Union[str, Sequence[int]],
    margin: float,
    min_probability: float,
    probability_power: float,
) -> Tuple[Tensor, float, Tensor, Tensor]:
    zero = logits.sum() * 0.0
    if logits.ndim != 2 or source_logits.ndim != 2 or logits.shape != source_logits.shape:
        return zero, 0.0, zero.detach(), zero.detach()
    if logits.size(0) == 0:
        return zero, 0.0, zero.detach(), zero.detach()

    num_classes = int(logits.size(1))
    focus = int(focus_class)
    if focus < 0 or focus >= num_classes:
        raise ValueError(
            f"source-context focus suppression class {focus} nam ngoai [0, {num_classes - 1}]."
        )
    negatives = _parse_angular_margin_classes(
        negative_classes,
        num_classes=num_classes,
    )
    negatives = [class_index for class_index in negatives if int(class_index) != focus]
    if not negatives:
        return zero, 0.0, zero.detach(), zero.detach()

    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, logits)
    if target_indices is None or target_indices.numel() != logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    primary_focus = torch.softmax(logits.float(), dim=1)[:, focus].clamp(0.0, 1.0)
    source_focus = torch.softmax(source_logits.float(), dim=1)[:, focus].clamp(0.0, 1.0)
    negative_tensor = torch.tensor(negatives, device=logits.device, dtype=torch.long)
    valid = (
        (target_indices >= 0)
        & (target_indices < num_classes)
        & torch.isin(target_indices, negative_tensor)
    )
    if float(min_probability) > 0.0:
        valid = valid & (
            torch.maximum(primary_focus.detach(), source_focus.detach()) >= float(min_probability)
        )

    probability = max(0.0, min(1.0, float(probability)))
    if probability < 1.0:
        valid = valid & (torch.rand(logits.size(0), device=logits.device) < probability)
    if not bool(valid.any().item()):
        return zero, 0.0, source_focus.detach().mean().to(dtype=logits.dtype), zero.detach()

    selected = valid.nonzero(as_tuple=False).flatten()
    delta = source_focus.index_select(0, selected) - primary_focus.detach().index_select(0, selected)
    per_sample = F.relu(delta - float(margin))
    weights = source_focus.detach().index_select(0, selected).pow(float(probability_power))
    weights = weights.clamp(min=1e-6)
    loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
    fraction = float(valid.float().mean().detach().cpu().item())
    return (
        loss.to(dtype=logits.dtype),
        fraction,
        source_focus.detach().mean().to(dtype=logits.dtype),
        delta.detach().mean().to(dtype=logits.dtype),
    )


def _surface_counterfactual_images(
    images: Tensor,
    *,
    mode: str,
    strength: float,
    blur_kernel: int,
    margin: float = 0.08,
) -> Tensor:
    normalized_mode = str(mode or "foreground_luma").strip().lower().replace("-", "_")
    if normalized_mode not in {
        "rgb_unsharp",
        "luma_residual",
        "foreground_unsharp",
        "foreground_luma",
    }:
        raise ValueError(
            "surface_counterfactual_mode chi ho tro rgb_unsharp, luma_residual, "
            "foreground_unsharp, foreground_luma."
        )
    with torch.no_grad():
        rgb = _denormalize_classification_images(images.detach())
        kernel = _odd_kernel_size(int(blur_kernel), minimum=3)
        padding = kernel // 2
        blurred = F.avg_pool2d(rgb, kernel_size=kernel, stride=1, padding=padding)
        residual = rgb - blurred
        luminance_residual = (
            0.299 * residual[:, 0:1]
            + 0.587 * residual[:, 1:2]
            + 0.114 * residual[:, 2:3]
        ).expand_as(rgb)
        if normalized_mode in {"luma_residual", "foreground_luma"}:
            detail = luminance_residual
        else:
            detail = residual
        if normalized_mode.startswith("foreground"):
            foreground = _pseudo_foreground_mask_from_normalized_images(
                images.detach(),
                margin=margin,
            ).to(device=images.device, dtype=images.dtype)
            soft_mask = F.avg_pool2d(
                foreground,
                kernel_size=kernel,
                stride=1,
                padding=padding,
            ).clamp(0.0, 1.0)
            detail = detail * soft_mask
        amplified = (rgb + float(strength) * detail).clamp(0.0, 1.0)
        return _normalize_classification_images(amplified).to(dtype=images.dtype)


def _surface_counterfactual_consistency_loss(
    *,
    model: nn.Module,
    images: Tensor,
    logits: Tensor,
    image_valid_mask: Optional[Tensor],
    bbox_metadata: Optional[Tensor],
    bbox_token_prior: Optional[Tensor],
    probability: float,
    mode: str,
    strength: float,
    blur_kernel: int,
    temperature: float,
    amp: bool,
    device: torch.device,
) -> Tuple[Tensor, float]:
    probability = max(0.0, min(1.0, float(probability)))
    if probability <= 0.0 or images.size(0) <= 0 or float(strength) <= 0.0:
        return logits.sum() * 0.0, 0.0
    selected = torch.rand(images.size(0), device=images.device) < probability
    if not bool(selected.any().item()):
        return logits.sum() * 0.0, 0.0
    selected_indices = selected.nonzero(as_tuple=False).flatten()
    selected_images = images.index_select(0, selected_indices)
    counterfactual_images = _surface_counterfactual_images(
        selected_images,
        mode=mode,
        strength=strength,
        blur_kernel=blur_kernel,
    )
    selected_mask = _select_batch_tensor_metadata(
        image_valid_mask,
        selected_indices,
        images.size(0),
    )
    selected_bbox_metadata = _select_batch_tensor_metadata(
        bbox_metadata,
        selected_indices,
        images.size(0),
    )
    selected_bbox_token_prior = _select_batch_tensor_metadata(
        bbox_token_prior,
        selected_indices,
        images.size(0),
    )
    with autocast_context(device, amp):
        _, counterfactual_outputs = _forward_model_outputs(
            model,
            counterfactual_images,
            image_valid_mask=selected_mask,
            bbox_metadata=selected_bbox_metadata,
            bbox_token_prior=selected_bbox_token_prior,
        )
        counterfactual_logits, _ = extract_bbox_from_model_output(counterfactual_outputs)
    temperature = max(0.05, float(temperature))
    source_logits = logits.index_select(0, selected_indices).detach()
    target_probabilities = F.softmax(source_logits.float() / temperature, dim=1)
    log_probabilities = F.log_softmax(counterfactual_logits.float() / temperature, dim=1)
    loss = F.kl_div(
        log_probabilities,
        target_probabilities,
        reduction="batchmean",
    ) * (temperature ** 2)
    return loss.to(dtype=logits.dtype), float(selected_indices.numel()) / float(images.size(0))


def _bbox_foreground_dropout_images(
    images: Tensor,
    crop_bboxes: Optional[Tensor],
    *,
    probability: float,
    min_area_ratio: float,
    max_area_ratio: float,
    mode: str = "random",
    fill: str,
) -> Tuple[Tensor, Tensor, float]:
    probability = max(0.0, min(1.0, float(probability)))
    if probability <= 0.0 or images.ndim != 4 or images.size(0) <= 0:
        empty = torch.zeros((0,), device=images.device, dtype=torch.long)
        return images, empty, 0.0
    if crop_bboxes is None or not torch.is_tensor(crop_bboxes):
        empty = torch.zeros((0,), device=images.device, dtype=torch.long)
        return images, empty, 0.0
    if crop_bboxes.ndim == 3:
        crop_bboxes = crop_bboxes[:, 0]
    if crop_bboxes.ndim != 2 or int(crop_bboxes.size(1)) < 4:
        empty = torch.zeros((0,), device=images.device, dtype=torch.long)
        return images, empty, 0.0

    bboxes = crop_bboxes[:, :4].to(device=images.device, dtype=torch.float32).clamp(0.0, 1.0)
    valid = (bboxes[:, 2] > 0.03) & (bboxes[:, 3] > 0.03)
    selected = (torch.rand(images.size(0), device=images.device) < probability) & valid
    if not bool(selected.any().item()):
        empty = torch.zeros((0,), device=images.device, dtype=torch.long)
        return images, empty, 0.0

    selected_indices = selected.nonzero(as_tuple=False).flatten()
    min_ratio = max(0.0, float(min_area_ratio))
    max_ratio = min(max(min_ratio, float(max_area_ratio)), 0.80)
    dropout_mode = str(mode or "random").strip().lower().replace("-", "_")
    if dropout_mode not in {"random", "interior", "boundary_band"}:
        dropout_mode = "random"
    fill_mode = str(fill or "mean").strip().lower().replace("-", "_")
    if fill_mode not in {"mean", "gray", "zero", "noise"}:
        fill_mode = "mean"

    with torch.no_grad():
        rgb = _denormalize_classification_images(images.detach()).clone()
        _, _, height, width = rgb.shape
        for index_tensor in selected_indices:
            sample_index = int(index_tensor.item())
            x_center, y_center, box_width, box_height = bboxes[sample_index].tolist()
            x1 = int(math.floor((float(x_center) - float(box_width) * 0.5) * width))
            y1 = int(math.floor((float(y_center) - float(box_height) * 0.5) * height))
            x2 = int(math.ceil((float(x_center) + float(box_width) * 0.5) * width))
            y2 = int(math.ceil((float(y_center) + float(box_height) * 0.5) * height))
            x1 = max(0, min(width - 1, x1))
            y1 = max(0, min(height - 1, y1))
            x2 = max(x1 + 1, min(width, x2))
            y2 = max(y1 + 1, min(height, y2))
            bbox_width = max(1, x2 - x1)
            bbox_height = max(1, y2 - y1)
            area_ratio = float(
                torch.empty((), device=images.device).uniform_(min_ratio, max_ratio).item()
            )
            erase_area = max(1.0, float(bbox_width * bbox_height) * area_ratio)
            if dropout_mode == "boundary_band":
                side = int(torch.randint(0, 4, (1,), device=images.device).item())
                if side in {0, 1}:
                    erase_height = bbox_height
                    erase_width = max(1, min(bbox_width, int(round(erase_area / max(1, bbox_height)))))
                    left = x1 if side == 0 else x2 - erase_width
                    top = y1
                else:
                    erase_width = bbox_width
                    erase_height = max(1, min(bbox_height, int(round(erase_area / max(1, bbox_width)))))
                    left = x1
                    top = y1 if side == 2 else y2 - erase_height
            else:
                aspect_low, aspect_high = (0.80, 1.25) if dropout_mode == "interior" else (0.67, 1.50)
                aspect = float(
                    torch.empty((), device=images.device).uniform_(aspect_low, aspect_high).item()
                )
                erase_width = max(1, min(bbox_width, int(round(math.sqrt(erase_area * aspect)))))
                erase_height = max(1, min(bbox_height, int(round(math.sqrt(erase_area / aspect)))))
                if dropout_mode == "interior":
                    left = x1 + max(0, (bbox_width - erase_width) // 2)
                    top = y1 + max(0, (bbox_height - erase_height) // 2)
                else:
                    left = x1
                    top = y1
                    if bbox_width > erase_width:
                        left += int(
                            torch.randint(
                                0,
                                bbox_width - erase_width + 1,
                                (1,),
                                device=images.device,
                            ).item()
                        )
                    if bbox_height > erase_height:
                        top += int(
                            torch.randint(
                                0,
                                bbox_height - erase_height + 1,
                                (1,),
                                device=images.device,
                            ).item()
                        )
            right = min(width, left + erase_width)
            bottom = min(height, top + erase_height)
            patch = rgb[sample_index : sample_index + 1, :, y1:y2, x1:x2]
            if fill_mode == "zero":
                fill_value = patch.new_zeros((1, 3, 1, 1))
            elif fill_mode == "gray":
                luminance = 0.299 * patch[:, 0:1] + 0.587 * patch[:, 1:2] + 0.114 * patch[:, 2:3]
                fill_value = luminance.mean(dim=(2, 3), keepdim=True).expand(1, 3, 1, 1)
            elif fill_mode == "noise":
                mean = patch.mean(dim=(2, 3), keepdim=True)
                noise = torch.randn(
                    (1, 3, bottom - top, right - left),
                    device=rgb.device,
                    dtype=rgb.dtype,
                ) * 0.08
                rgb[sample_index : sample_index + 1, :, top:bottom, left:right] = (
                    mean + noise
                ).clamp(0.0, 1.0)
                continue
            else:
                fill_value = patch.mean(dim=(2, 3), keepdim=True)
            rgb[sample_index : sample_index + 1, :, top:bottom, left:right] = fill_value
        dropped = _normalize_classification_images(rgb).to(device=images.device, dtype=images.dtype)
    return dropped, selected_indices, float(selected_indices.numel()) / float(images.size(0))


def _bbox_foreground_dropout_losses(
    *,
    model: nn.Module,
    criterion: nn.Module,
    images: Tensor,
    logits: Tensor,
    targets: Tensor,
    crop_bboxes: Optional[Tensor],
    bbox_metadata: Optional[Tensor],
    bbox_token_prior: Optional[Tensor],
    probability: float,
    min_area_ratio: float,
    max_area_ratio: float,
    mode: str,
    fill: str,
    temperature: float,
    amp: bool,
    device: torch.device,
) -> Tuple[Tensor, Tensor, float]:
    zero = logits.sum() * 0.0
    if images.size(0) <= 0 or not torch.is_tensor(targets):
        return zero, zero, 0.0
    dropped_images, selected_indices, fraction = _bbox_foreground_dropout_images(
        images,
        crop_bboxes,
        probability=probability,
        min_area_ratio=min_area_ratio,
        max_area_ratio=max_area_ratio,
        mode=mode,
        fill=fill,
    )
    if selected_indices.numel() == 0:
        return zero, zero, 0.0

    selected_images = dropped_images.index_select(0, selected_indices)
    selected_targets = targets.index_select(0, selected_indices.to(device=targets.device))
    selected_bbox_metadata = None
    if torch.is_tensor(bbox_metadata) and bbox_metadata.size(0) == images.size(0):
        selected_bbox_metadata = bbox_metadata.index_select(
            0,
            selected_indices.to(device=bbox_metadata.device),
        )
    selected_bbox_token_prior = None
    if torch.is_tensor(bbox_token_prior) and bbox_token_prior.size(0) == images.size(0):
        selected_bbox_token_prior = bbox_token_prior.index_select(
            0,
            selected_indices.to(device=bbox_token_prior.device),
        )
    with autocast_context(device, amp):
        _, dropped_outputs = _forward_model_outputs(
            model,
            selected_images,
            image_valid_mask=None,
            bbox_metadata=selected_bbox_metadata,
            bbox_token_prior=selected_bbox_token_prior,
        )
        dropped_logits, _ = extract_bbox_from_model_output(dropped_outputs)
        supervised_loss = criterion(dropped_logits, selected_targets)
    temperature = max(0.05, float(temperature))
    source_logits = logits.index_select(0, selected_indices.to(device=logits.device)).detach()
    target_probabilities = F.softmax(source_logits.float() / temperature, dim=1)
    log_probabilities = F.log_softmax(dropped_logits.float() / temperature, dim=1)
    consistency_loss = F.kl_div(
        log_probabilities,
        target_probabilities,
        reduction="batchmean",
    ) * (temperature ** 2)
    return supervised_loss.to(dtype=logits.dtype), consistency_loss.to(dtype=logits.dtype), float(fraction)


def _bbox_object_erasure_images(
    images: Tensor,
    crop_bboxes: Optional[Tensor],
    *,
    probability: float,
    margin_ratio: float,
    fill: str,
    blur_kernel: int = 15,
) -> Tuple[Tensor, Tensor, float]:
    probability = max(0.0, min(1.0, float(probability)))
    if probability <= 0.0 or images.ndim != 4 or images.size(0) <= 0:
        empty = torch.zeros((0,), device=images.device, dtype=torch.long)
        return images, empty, 0.0
    if crop_bboxes is None or not torch.is_tensor(crop_bboxes):
        empty = torch.zeros((0,), device=images.device, dtype=torch.long)
        return images, empty, 0.0
    if crop_bboxes.ndim == 3:
        crop_bboxes = crop_bboxes[:, 0]
    if crop_bboxes.ndim != 2 or int(crop_bboxes.size(1)) < 4:
        empty = torch.zeros((0,), device=images.device, dtype=torch.long)
        return images, empty, 0.0

    bboxes = crop_bboxes[:, :4].to(device=images.device, dtype=torch.float32).clamp(0.0, 1.0)
    valid = (bboxes[:, 2] > 0.03) & (bboxes[:, 3] > 0.03)
    selected = (torch.rand(images.size(0), device=images.device) < probability) & valid
    if not bool(selected.any().item()):
        empty = torch.zeros((0,), device=images.device, dtype=torch.long)
        return images, empty, 0.0

    selected_indices = selected.nonzero(as_tuple=False).flatten()
    margin = max(0.0, float(margin_ratio))
    fill_mode = str(fill or "mean").strip().lower().replace("-", "_")
    if fill_mode not in {"mean", "gray", "zero", "noise", "blur"}:
        fill_mode = "mean"

    with torch.no_grad():
        rgb = _denormalize_classification_images(images.detach()).clone()
        _, _, height, width = rgb.shape
        blurred_rgb = None
        if fill_mode == "blur":
            kernel = _odd_kernel_size(int(blur_kernel), minimum=3)
            blurred_rgb = F.avg_pool2d(rgb, kernel_size=kernel, stride=1, padding=kernel // 2)
        for index_tensor in selected_indices:
            sample_index = int(index_tensor.item())
            x_center, y_center, box_width, box_height = bboxes[sample_index].tolist()
            half_width = float(box_width) * (0.5 + margin)
            half_height = float(box_height) * (0.5 + margin)
            x1 = int(math.floor((float(x_center) - half_width) * width))
            y1 = int(math.floor((float(y_center) - half_height) * height))
            x2 = int(math.ceil((float(x_center) + half_width) * width))
            y2 = int(math.ceil((float(y_center) + half_height) * height))
            x1 = max(0, min(width - 1, x1))
            y1 = max(0, min(height - 1, y1))
            x2 = max(x1 + 1, min(width, x2))
            y2 = max(y1 + 1, min(height, y2))
            patch = rgb[sample_index : sample_index + 1, :, y1:y2, x1:x2]
            if fill_mode == "zero":
                fill_value = patch.new_zeros((1, 3, 1, 1))
                rgb[sample_index : sample_index + 1, :, y1:y2, x1:x2] = fill_value
            elif fill_mode == "gray":
                luminance = 0.299 * patch[:, 0:1] + 0.587 * patch[:, 1:2] + 0.114 * patch[:, 2:3]
                fill_value = luminance.mean(dim=(2, 3), keepdim=True).expand(1, 3, 1, 1)
                rgb[sample_index : sample_index + 1, :, y1:y2, x1:x2] = fill_value
            elif fill_mode == "noise":
                mean = patch.mean(dim=(2, 3), keepdim=True)
                noise = torch.randn_like(patch) * 0.08
                rgb[sample_index : sample_index + 1, :, y1:y2, x1:x2] = (mean + noise).clamp(0.0, 1.0)
            elif fill_mode == "blur" and blurred_rgb is not None:
                rgb[sample_index : sample_index + 1, :, y1:y2, x1:x2] = blurred_rgb[
                    sample_index : sample_index + 1,
                    :,
                    y1:y2,
                    x1:x2,
                ]
            else:
                fill_value = patch.mean(dim=(2, 3), keepdim=True)
                rgb[sample_index : sample_index + 1, :, y1:y2, x1:x2] = fill_value
        erased = _normalize_classification_images(rgb).to(device=images.device, dtype=images.dtype)
    return erased, selected_indices, float(selected_indices.numel()) / float(images.size(0))


def _bbox_object_erasure_negative_loss(
    *,
    model: nn.Module,
    images: Tensor,
    logits: Tensor,
    crop_bboxes: Optional[Tensor],
    bbox_metadata: Optional[Tensor],
    bbox_token_prior: Optional[Tensor],
    probability: float,
    margin_ratio: float,
    fill: str,
    blur_kernel: int,
    temperature: float,
    amp: bool,
    device: torch.device,
) -> Tuple[Tensor, float, float]:
    zero = logits.sum() * 0.0
    erased_images, selected_indices, fraction = _bbox_object_erasure_images(
        images,
        crop_bboxes,
        probability=probability,
        margin_ratio=margin_ratio,
        fill=fill,
        blur_kernel=blur_kernel,
    )
    if selected_indices.numel() == 0:
        return zero, 0.0, 0.0

    selected_images = erased_images.index_select(0, selected_indices)
    selected_bbox_metadata = None
    if torch.is_tensor(bbox_metadata) and bbox_metadata.size(0) == images.size(0):
        selected_bbox_metadata = bbox_metadata.index_select(
            0,
            selected_indices.to(device=bbox_metadata.device),
        )
    selected_bbox_token_prior = None
    if torch.is_tensor(bbox_token_prior) and bbox_token_prior.size(0) == images.size(0):
        selected_bbox_token_prior = bbox_token_prior.index_select(
            0,
            selected_indices.to(device=bbox_token_prior.device),
        )
    with autocast_context(device, amp):
        _, erased_outputs = _forward_model_outputs(
            model,
            selected_images,
            image_valid_mask=None,
            bbox_metadata=selected_bbox_metadata,
            bbox_token_prior=selected_bbox_token_prior,
        )
        erased_logits, _ = extract_bbox_from_model_output(erased_outputs)

    temperature = max(0.05, float(temperature))
    log_probabilities = F.log_softmax(erased_logits.float() / temperature, dim=1)
    uniform = torch.full_like(log_probabilities, 1.0 / float(log_probabilities.size(1)))
    loss = F.kl_div(log_probabilities, uniform, reduction="batchmean") * (temperature ** 2)
    max_probability = (
        F.softmax(erased_logits.float(), dim=1).max(dim=1).values.mean().detach().cpu().item()
    )
    return loss.to(dtype=logits.dtype), float(fraction), float(max_probability)


def _surface_amplified_boundary_margin_loss(
    logits: Tensor,
    targets: Tensor,
    *,
    pairs: str,
    margin: float,
    num_classes: int,
) -> Tuple[Tensor, int]:
    if logits.ndim != 2 or targets.ndim != 1 or logits.size(0) != targets.numel():
        raise ValueError("surface amplified margin can logits [B,C] va targets [B].")
    parsed_pairs = _parse_boundary_contrastive_pairs(pairs, num_classes)
    target_indices = targets.to(device=logits.device, dtype=torch.long).view(-1)
    valid_targets = (target_indices >= 0) & (target_indices < int(logits.size(1)))
    if not bool(valid_targets.any().item()):
        return logits.sum() * 0.0, 0

    negative_mask = torch.zeros_like(logits, dtype=torch.bool)
    row_indices = torch.arange(logits.size(0), device=logits.device)
    for left_class, right_class in parsed_pairs:
        if int(left_class) < 0:
            special_class = int(right_class)
            if special_class < 0 or special_class >= int(logits.size(1)):
                continue
            special_rows = target_indices == special_class
            rest_rows = valid_targets & ~special_rows
            if bool(special_rows.any().item()):
                negative_mask[special_rows] = True
                negative_mask[special_rows, special_class] = False
            if bool(rest_rows.any().item()):
                negative_mask[rest_rows, special_class] = True
            continue

        left = int(left_class)
        right = int(right_class)
        if left < 0 or right < 0 or left >= int(logits.size(1)) or right >= int(logits.size(1)):
            continue
        left_rows = target_indices == left
        right_rows = target_indices == right
        if bool(left_rows.any().item()):
            negative_mask[left_rows, right] = True
        if bool(right_rows.any().item()):
            negative_mask[right_rows, left] = True

    valid = valid_targets & negative_mask.any(dim=1)
    if not bool(valid.any().item()):
        return logits.sum() * 0.0, 0
    masked_negatives = logits.float().masked_fill(~negative_mask, -1.0e4)
    hardest_negative = masked_negatives.max(dim=1).values
    target_logits = logits.float()[row_indices, target_indices.clamp(0, int(logits.size(1)) - 1)]
    per_sample = F.relu(float(max(0.0, margin)) + hardest_negative - target_logits)
    return per_sample[valid].mean().to(dtype=logits.dtype), int(valid.sum().detach().cpu().item())


def _surface_amplified_supervised_losses(
    *,
    model: nn.Module,
    criterion: nn.Module,
    images: Tensor,
    targets: Tensor,
    image_valid_mask: Optional[Tensor],
    bbox_metadata: Optional[Tensor],
    bbox_token_prior: Optional[Tensor],
    probability: float,
    mode: str,
    strength: float,
    blur_kernel: int,
    boundary_pairs: str,
    boundary_margin: float,
    amp: bool,
    device: torch.device,
    num_classes: int,
) -> Tuple[Tensor, Tensor, float, int]:
    probability = max(0.0, min(1.0, float(probability)))
    if probability <= 0.0 or images.size(0) <= 0 or float(strength) <= 0.0:
        zero = images.sum() * 0.0
        return zero, zero, 0.0, 0
    if not torch.is_tensor(targets) or targets.ndim != 1:
        zero = images.sum() * 0.0
        return zero, zero, 0.0, 0
    selected = torch.rand(images.size(0), device=images.device) < probability
    if not bool(selected.any().item()):
        zero = images.sum() * 0.0
        return zero, zero, 0.0, 0
    selected_indices = selected.nonzero(as_tuple=False).flatten()
    selected_images = images.index_select(0, selected_indices)
    selected_targets = targets.to(device=images.device, dtype=torch.long).index_select(
        0,
        selected_indices,
    )
    amplified_images = _surface_counterfactual_images(
        selected_images,
        mode=mode,
        strength=strength,
        blur_kernel=blur_kernel,
    )
    selected_mask = _select_batch_tensor_metadata(
        image_valid_mask,
        selected_indices,
        images.size(0),
    )
    selected_bbox_metadata = _select_batch_tensor_metadata(
        bbox_metadata,
        selected_indices,
        images.size(0),
    )
    selected_bbox_token_prior = _select_batch_tensor_metadata(
        bbox_token_prior,
        selected_indices,
        images.size(0),
    )
    with autocast_context(device, amp):
        _, amplified_outputs = _forward_model_outputs(
            model,
            amplified_images,
            image_valid_mask=selected_mask,
            bbox_metadata=selected_bbox_metadata,
            bbox_token_prior=selected_bbox_token_prior,
        )
        amplified_logits, _ = extract_bbox_from_model_output(amplified_outputs)
        supervised_loss = criterion(amplified_logits, selected_targets)
        boundary_margin_loss, boundary_terms = _surface_amplified_boundary_margin_loss(
            amplified_logits,
            selected_targets,
            pairs=boundary_pairs,
            margin=boundary_margin,
            num_classes=int(num_classes),
        )
    fraction = float(selected_indices.numel()) / float(images.size(0))
    return (
        supervised_loss.to(dtype=amplified_logits.dtype),
        boundary_margin_loss.to(dtype=amplified_logits.dtype),
        fraction,
        int(boundary_terms),
    )


def _paired_view_training_losses(
    *,
    model: nn.Module,
    criterion: nn.Module,
    features: Optional[Dict[str, Tensor]],
    logits: Tensor,
    targets: Tensor,
    paired_images: Optional[Tensor],
    paired_labels: Optional[Tensor],
    paired_bboxes: Optional[Tensor],
    paired_masks: Optional[Tensor],
    supervised_weight: float,
    consistency_weight: float,
    feature_weight: float,
    temperature: float,
    feature_source: str,
    amp: bool,
    device: torch.device,
) -> Tuple[Tensor, Tensor, Tensor, float]:
    zero = logits.sum() * 0.0
    if (
        not torch.is_tensor(paired_images)
        or paired_images.ndim != 4
        or paired_images.size(0) != logits.size(0)
        or not torch.is_tensor(targets)
    ):
        return zero, zero, zero, 0.0
    if (
        float(supervised_weight) <= 0.0
        and float(consistency_weight) <= 0.0
        and float(feature_weight) <= 0.0
    ):
        return zero, zero, zero, 0.0

    paired_targets = targets
    if torch.is_tensor(paired_labels) and paired_labels.numel() == targets.numel():
        paired_targets = paired_labels.to(device=targets.device, dtype=torch.long).view_as(targets)
    paired_bbox_metadata = None
    if torch.is_tensor(paired_bboxes) and paired_bboxes.size(0) == paired_images.size(0):
        paired_bbox_metadata = paired_bboxes.to(device=device, dtype=torch.float32)
    paired_valid_mask = None
    if torch.is_tensor(paired_masks) and paired_masks.size(0) == paired_images.size(0):
        paired_valid_mask = paired_masks.to(device=device, dtype=torch.bool)

    with autocast_context(device, amp):
        paired_features, paired_outputs = _forward_model_outputs(
            model,
            paired_images,
            image_valid_mask=paired_valid_mask,
            bbox_metadata=paired_bbox_metadata,
            bbox_token_prior=paired_bbox_metadata,
        )
        paired_logits, _ = extract_bbox_from_model_output(paired_outputs)
        supervised_loss = criterion(paired_logits, paired_targets)

    temperature = max(0.05, float(temperature))
    consistency_loss = F.kl_div(
        F.log_softmax(paired_logits.float() / temperature, dim=1),
        F.softmax(logits.detach().float() / temperature, dim=1),
        reduction="batchmean",
    ) * (temperature ** 2)

    feature_loss = zero
    if (
        paired_features is not None
        and features is not None
        and float(feature_weight) > 0.0
    ):
        source = str(feature_source or "head").strip().lower()
        if source == "patch_tokens":
            patch_token_loss = _paired_view_patch_token_alignment_loss(
                primary_features=features,
                paired_features=paired_features,
                temperature=temperature,
            )
            if torch.is_tensor(patch_token_loss):
                feature_loss = patch_token_loss.to(dtype=logits.dtype)
        else:
            primary_embedding = _embedding_from_features_source(
                model=model,
                features=features,
                source=source,
            )
            paired_embedding = _embedding_from_features_source(
                model=model,
                features=paired_features,
                source=source,
            )
            if (
                torch.is_tensor(primary_embedding)
                and torch.is_tensor(paired_embedding)
                and primary_embedding.ndim == 2
                and paired_embedding.ndim == 2
                and primary_embedding.shape == paired_embedding.shape
            ):
                primary_norm = F.normalize(primary_embedding.float(), dim=1, eps=1e-6)
                paired_norm = F.normalize(paired_embedding.float(), dim=1, eps=1e-6)
                feature_loss = (1.0 - (primary_norm * paired_norm).sum(dim=1)).mean()
                feature_loss = feature_loss.to(dtype=logits.dtype)

    return (
        supervised_loss.to(dtype=logits.dtype),
        consistency_loss.to(dtype=logits.dtype),
        feature_loss.to(dtype=logits.dtype),
        1.0,
    )


def _paired_view_fusion_training_losses(
    *,
    model: nn.Module,
    criterion: nn.Module,
    features: Optional[Dict[str, Tensor]],
    logits: Tensor,
    targets: Tensor,
    paired_images: Optional[Tensor],
    paired_labels: Optional[Tensor],
    paired_bboxes: Optional[Tensor],
    paired_masks: Optional[Tensor],
    supervised_weight: float,
    consistency_weight: float,
    temperature: float,
    amp: bool,
    device: torch.device,
) -> Tuple[Tensor, Tensor, float, float, float]:
    zero = logits.sum() * 0.0
    if (
        getattr(model, "paired_view_fusion_head", None) is None
        or features is None
        or not torch.is_tensor(paired_images)
        or paired_images.ndim != 4
        or paired_images.size(0) != logits.size(0)
        or not torch.is_tensor(targets)
    ):
        return zero, zero, 0.0, 0.0, 0.0
    if float(supervised_weight) <= 0.0 and float(consistency_weight) <= 0.0:
        return zero, zero, 0.0, 0.0, 0.0

    paired_targets = targets
    if torch.is_tensor(paired_labels) and paired_labels.numel() == targets.numel():
        paired_targets = paired_labels.to(device=targets.device, dtype=torch.long).view_as(targets)
    paired_bbox_metadata = None
    if torch.is_tensor(paired_bboxes) and paired_bboxes.size(0) == paired_images.size(0):
        paired_bbox_metadata = paired_bboxes.to(device=device, dtype=torch.float32)
    paired_valid_mask = None
    if torch.is_tensor(paired_masks) and paired_masks.size(0) == paired_images.size(0):
        paired_valid_mask = paired_masks.to(device=device, dtype=torch.bool)

    with autocast_context(device, amp):
        paired_features, paired_outputs = _forward_model_outputs(
            model,
            paired_images,
            image_valid_mask=paired_valid_mask,
            bbox_metadata=paired_bbox_metadata,
            bbox_token_prior=paired_bbox_metadata,
        )
        paired_logits, _ = extract_bbox_from_model_output(paired_outputs)
        fusion_output = paired_view_fused_logits_from_features(
            model,
            features,
            paired_features,
            logits,
            paired_logits,
            return_trace=True,
        )
        if fusion_output is None:
            return zero, zero, 0.0, 0.0, 0.0
        fused_logits, fusion_trace = fusion_output
        supervised_loss = criterion(fused_logits, paired_targets)

    temperature = max(0.05, float(temperature))
    target_probs = (
        0.5 * torch.softmax(logits.detach().float() / temperature, dim=1)
        + 0.5 * torch.softmax(paired_logits.detach().float() / temperature, dim=1)
    )
    consistency_loss = F.kl_div(
        F.log_softmax(fused_logits.float() / temperature, dim=1),
        target_probs,
        reduction="batchmean",
    ) * (temperature ** 2)
    adjustment = fusion_trace.get("adjustment") if isinstance(fusion_trace, dict) else None
    gate = fusion_trace.get("gate") if isinstance(fusion_trace, dict) else None
    adjustment_abs = (
        float(adjustment.detach().float().abs().mean().cpu().item())
        if torch.is_tensor(adjustment)
        else 0.0
    )
    gate_mean = (
        float(gate.detach().float().mean().cpu().item())
        if torch.is_tensor(gate)
        else 0.0
    )
    return (
        supervised_loss.to(dtype=logits.dtype),
        consistency_loss.to(dtype=logits.dtype),
        1.0,
        adjustment_abs,
        gate_mean,
    )


def _normalize_attention_scores(scores: Tensor) -> Tensor:
    flattened = scores.flatten(1)
    minimum = flattened.amin(dim=1, keepdim=True)
    maximum = flattened.amax(dim=1, keepdim=True)
    normalized = (flattened - minimum) / (maximum - minimum).clamp(min=1e-6)
    return normalized.view_as(scores)


def _attention_guided_score_map(
    *,
    images: Tensor,
    features: Dict[str, Tensor],
    foreground_weight: float,
    score_source: str = "learned_attention",
) -> Tensor:
    patches = features.get("patches")
    grid_size = features.get("grid_size")
    if (
        not torch.is_tensor(patches)
        or patches.ndim != 3
        or not isinstance(grid_size, tuple)
        or len(grid_size) != 2
    ):
        return _pseudo_foreground_mask_from_normalized_images(images.detach())

    grid_h, grid_w = int(grid_size[0]), int(grid_size[1])
    original_patch_count = grid_h * grid_w
    if original_patch_count <= 0:
        return _pseudo_foreground_mask_from_normalized_images(images.detach())

    learned_scores = features.get("fine_grained_attention")
    if not torch.is_tensor(learned_scores) or learned_scores.shape[:2] != patches.shape[:2]:
        learned_scores = patches.detach().float().norm(dim=-1)
    else:
        learned_scores = learned_scores.detach().float()
    learned_scores = _normalize_attention_scores(learned_scores)

    patch_indices = features.get("patch_indices")
    if (
        torch.is_tensor(patch_indices)
        and patch_indices.ndim == 2
        and patch_indices.shape == learned_scores.shape
    ):
        spatial_scores = learned_scores.new_zeros(
            (learned_scores.size(0), original_patch_count)
        )
        spatial_scores.scatter_(
            1,
            patch_indices.detach().to(device=learned_scores.device, dtype=torch.long),
            learned_scores,
        )
    elif learned_scores.size(1) == original_patch_count:
        spatial_scores = learned_scores
    else:
        return _pseudo_foreground_mask_from_normalized_images(images.detach())

    foreground_prior = features.get("foreground_prior")
    if (
        torch.is_tensor(foreground_prior)
        and foreground_prior.ndim == 2
        and foreground_prior.shape == spatial_scores.shape
        and bool((foreground_prior.detach().abs().sum() > 0).item())
    ):
        foreground_scores = foreground_prior.detach().float()
    else:
        pseudo_foreground = _pseudo_foreground_mask_from_normalized_images(images.detach())
        foreground_scores = F.interpolate(
            pseudo_foreground,
            size=(grid_h, grid_w),
            mode="area",
        ).flatten(1)

    normalized_learned = _normalize_attention_scores(spatial_scores)
    normalized_foreground = _normalize_attention_scores(foreground_scores)
    detail_map = features.get("detail_map")
    if (
        torch.is_tensor(detail_map)
        and detail_map.ndim == 4
        and detail_map.size(0) == images.size(0)
        and detail_map.size(1) == 1
    ):
        detail_scores = F.adaptive_avg_pool2d(
            detail_map.detach().float(),
            output_size=(grid_h, grid_w),
        ).flatten(1)
        normalized_detail = _normalize_attention_scores(detail_scores)
    else:
        normalized_detail = normalized_learned

    foreground_weight = float(min(1.0, max(0.0, foreground_weight)))
    score_source = str(score_source).strip().lower()
    if score_source == "learned_attention":
        combined = (
            (1.0 - foreground_weight) * normalized_learned
            + foreground_weight * normalized_foreground
        )
    else:
        foreground_gate = (
            (1.0 - foreground_weight)
            + foreground_weight * normalized_foreground
        )
        surface_detail = normalized_detail * foreground_gate
        if score_source == "surface_detail":
            combined = surface_detail
        elif score_source == "hybrid":
            learned_with_prior = (
                (1.0 - foreground_weight) * normalized_learned
                + foreground_weight * normalized_foreground
            )
            combined = 0.35 * learned_with_prior + 0.65 * surface_detail
        else:
            raise ValueError(
                "attention view score source chi ho tro "
                "learned_attention, surface_detail, hybrid."
            )
    combined = combined.view(images.size(0), 1, grid_h, grid_w)
    combined = F.interpolate(
        combined,
        size=images.shape[-2:],
        mode="bilinear",
        align_corners=False,
    )
    return _normalize_attention_scores(combined).clamp(0.0, 1.0)


def _attention_crop_single(
    image: Tensor,
    score_map: Tensor,
    *,
    threshold: float,
    padding_ratio: float,
    min_area_ratio: float,
) -> Tensor:
    height, width = int(image.size(-2)), int(image.size(-1))
    score = score_map.squeeze()
    cutoff = float(threshold) * float(score.max().item())
    mask = score >= cutoff
    nonzero = torch.nonzero(mask, as_tuple=False)
    if nonzero.numel() == 0:
        flat_index = int(score.argmax().item())
        center_y, center_x = divmod(flat_index, width)
        y1 = y2 = center_y
        x1 = x2 = center_x
    else:
        y1 = int(nonzero[:, 0].min().item())
        y2 = int(nonzero[:, 0].max().item())
        x1 = int(nonzero[:, 1].min().item())
        x2 = int(nonzero[:, 1].max().item())

    pad_y = int(round(float(padding_ratio) * height))
    pad_x = int(round(float(padding_ratio) * width))
    y1, y2 = max(0, y1 - pad_y), min(height - 1, y2 + pad_y)
    x1, x2 = max(0, x1 - pad_x), min(width - 1, x2 + pad_x)

    min_scale = math.sqrt(float(min(1.0, max(1e-4, min_area_ratio))))
    min_height = max(1, int(math.ceil(height * min_scale)))
    min_width = max(1, int(math.ceil(width * min_scale)))
    center_y = (y1 + y2) // 2
    center_x = (x1 + x2) // 2
    if y2 - y1 + 1 < min_height:
        y1 = center_y - min_height // 2
        y2 = y1 + min_height - 1
    if x2 - x1 + 1 < min_width:
        x1 = center_x - min_width // 2
        x2 = x1 + min_width - 1
    if y1 < 0:
        y2 -= y1
        y1 = 0
    if x1 < 0:
        x2 -= x1
        x1 = 0
    if y2 >= height:
        y1 -= y2 - height + 1
        y2 = height - 1
    if x2 >= width:
        x1 -= x2 - width + 1
        x2 = width - 1
    y1, x1 = max(0, y1), max(0, x1)

    crop = image[:, y1 : y2 + 1, x1 : x2 + 1].unsqueeze(0)
    return F.interpolate(
        crop,
        size=(height, width),
        mode="bilinear",
        align_corners=False,
    ).squeeze(0)


def _bounded_attention_drop_mask(
    score_map: Tensor,
    *,
    threshold: float,
    dilation_kernel: int,
    min_area_ratio: float,
    max_area_ratio: float,
) -> Tensor:
    if score_map.ndim != 4 or score_map.size(1) != 1:
        raise ValueError("score_map cho attention drop phai co shape [B, 1, H, W].")

    batch_size = int(score_map.size(0))
    flat_scores = score_map.detach().float().flatten(1)
    pixel_count = int(flat_scores.size(1))
    if batch_size == 0 or pixel_count == 0:
        return torch.zeros_like(score_map)

    min_count = max(1, int(math.ceil(pixel_count * float(min_area_ratio))))
    max_count = max(min_count, int(math.floor(pixel_count * float(max_area_ratio))))
    max_count = min(pixel_count, max_count)
    cutoffs = (
        float(threshold)
        * flat_scores.amax(dim=1, keepdim=True)
    )
    masks = (flat_scores >= cutoffs).view_as(score_map)

    dilation_kernel = max(1, int(dilation_kernel))
    if dilation_kernel > 1:
        masks = F.max_pool2d(
            masks.to(dtype=score_map.dtype),
            kernel_size=dilation_kernel,
            stride=1,
            padding=dilation_kernel // 2,
        ) > 0

    bounded_masks: List[Tensor] = []
    for sample_index in range(batch_size):
        sample_mask = masks[sample_index].flatten()
        selected_count = int(sample_mask.sum().item())
        if selected_count < min_count or selected_count > max_count:
            target_count = min_count if selected_count < min_count else max_count
            top_indices = torch.topk(
                flat_scores[sample_index],
                k=target_count,
                largest=True,
                sorted=False,
            ).indices
            sample_mask = torch.zeros_like(sample_mask, dtype=torch.bool)
            sample_mask.scatter_(0, top_indices, True)
        bounded_masks.append(sample_mask.view(1, score_map.size(-2), score_map.size(-1)))

    return torch.stack(bounded_masks, dim=0).to(dtype=score_map.dtype)


def _build_attention_guided_views(
    *,
    images: Tensor,
    features: Dict[str, Tensor],
    crop_probability: float,
    drop_probability: float,
    crop_threshold: float,
    drop_threshold: float,
    crop_padding_ratio: float,
    crop_min_area_ratio: float,
    foreground_weight: float,
    drop_blur_kernel: int,
    score_source: str = "learned_attention",
    drop_dilation_kernel: int = 5,
    drop_min_area_ratio: float = 0.06,
    drop_max_area_ratio: float = 0.16,
) -> Tuple[Optional[Tensor], Tensor, Dict[str, float]]:
    batch_size = int(images.size(0))
    empty_indices = torch.zeros((0,), device=images.device, dtype=torch.long)
    if batch_size == 0 or crop_probability + drop_probability <= 0.0:
        return None, empty_indices, {
            "attention_view_fraction": 0.0,
            "attention_crop_fraction": 0.0,
            "attention_drop_fraction": 0.0,
            "attention_drop_area_fraction": 0.0,
        }

    with torch.no_grad():
        score_maps = _attention_guided_score_map(
            images=images,
            features=features,
            foreground_weight=foreground_weight,
            score_source=score_source,
        )
        draws = torch.rand((batch_size,), device=images.device)
        crop_mask = draws < float(crop_probability)
        drop_mask = (
            (draws >= float(crop_probability))
            & (draws < float(crop_probability + drop_probability))
        )
        selected = crop_mask | drop_mask
        selected_indices = torch.nonzero(selected, as_tuple=False).flatten()
        if selected_indices.numel() == 0:
            return None, empty_indices, {
                "attention_view_fraction": 0.0,
                "attention_crop_fraction": 0.0,
                "attention_drop_fraction": 0.0,
                "attention_drop_area_fraction": 0.0,
            }

        blur_kernel = max(1, int(drop_blur_kernel))
        blurred = F.avg_pool2d(
            images,
            kernel_size=blur_kernel,
            stride=1,
            padding=blur_kernel // 2,
        )
        views: List[Tensor] = []
        drop_area_fractions: List[float] = []
        for sample_index in selected_indices.tolist():
            if bool(crop_mask[sample_index].item()):
                view = _attention_crop_single(
                    images[sample_index],
                    score_maps[sample_index],
                    threshold=crop_threshold,
                    padding_ratio=crop_padding_ratio,
                    min_area_ratio=crop_min_area_ratio,
                )
            else:
                score = score_maps[sample_index : sample_index + 1]
                salient = _bounded_attention_drop_mask(
                    score,
                    threshold=drop_threshold,
                    dilation_kernel=drop_dilation_kernel,
                    min_area_ratio=drop_min_area_ratio,
                    max_area_ratio=drop_max_area_ratio,
                ).to(dtype=images.dtype)
                drop_area_fractions.append(float(salient.float().mean().item()))
                view = (
                    images[sample_index : sample_index + 1] * (1.0 - salient)
                    + blurred[sample_index : sample_index + 1] * salient
                ).squeeze(0)
            views.append(view)

        return torch.stack(views, dim=0), selected_indices, {
            "attention_view_fraction": float(selected.float().mean().item()),
            "attention_crop_fraction": float(crop_mask.float().mean().item()),
            "attention_drop_fraction": float(drop_mask.float().mean().item()),
            "attention_drop_area_fraction": (
                float(sum(drop_area_fractions) / len(drop_area_fractions))
                if drop_area_fractions
                else 0.0
            ),
        }


def _register_diversity_loss_from_features(features: Dict[str, Tensor]) -> Tensor:
    registers = features.get("registers")
    if not torch.is_tensor(registers) or registers.ndim != 3 or registers.size(1) < 2:
        reference = next(
            (value for value in features.values() if torch.is_tensor(value)),
            None,
        )
        if reference is None:
            return torch.tensor(0.0)
        return reference.sum() * 0.0

    normalized = F.normalize(registers.float(), dim=-1, eps=1e-6)
    similarity = torch.matmul(normalized, normalized.transpose(1, 2))
    register_count = int(registers.size(1))
    off_diagonal = ~torch.eye(
        register_count,
        device=registers.device,
        dtype=torch.bool,
    ).unsqueeze(0)
    loss = similarity.square().masked_select(off_diagonal.expand_as(similarity)).mean()
    return loss.to(dtype=registers.dtype)


def _pairwise_margin_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
) -> Tensor:
    pairwise_logits = features.get("pairwise_margin_logits")
    pairs = getattr(model, "pairwise_margin_pairs", [])
    if not torch.is_tensor(pairwise_logits) or pairwise_logits.ndim != 2 or not pairs:
        reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
        return reference.sum() * 0.0
    target_indices = targets.to(device=pairwise_logits.device, dtype=torch.long).view(-1)
    losses: List[Tensor] = []
    for pair_index, pair in enumerate(pairs):
        if pair_index >= int(pairwise_logits.size(1)):
            break
        left_class, right_class = [int(value) for value in pair]
        logits = pairwise_logits[:, pair_index].float()
        if left_class < 0:
            if right_class < 0:
                continue
            binary_targets = (target_indices == right_class).to(dtype=logits.dtype)
            losses.append(F.binary_cross_entropy_with_logits(logits, binary_targets))
            continue
        pair_mask = (target_indices == left_class) | (target_indices == right_class)
        if not bool(pair_mask.any().item()):
            continue
        binary_targets = (target_indices[pair_mask] == right_class).to(dtype=logits.dtype)
        losses.append(F.binary_cross_entropy_with_logits(logits[pair_mask], binary_targets))
    if not losses:
        return pairwise_logits.sum() * 0.0
    return torch.stack(losses).mean().to(dtype=pairwise_logits.dtype)


def _topk_reassessment_auxiliary_loss_from_features(
    *,
    features: Dict[str, Tensor],
    targets: Tensor,
    route_min_weight: float = 0.05,
) -> Tuple[Tensor, float]:
    base_logits = features.get("topk_reassessment_base_logits")
    adjustment = features.get("topk_reassessment_adjustment")
    route_weights = features.get("topk_reassessment_route_weights")
    reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
    if (
        not torch.is_tensor(base_logits)
        or not torch.is_tensor(adjustment)
        or not torch.is_tensor(route_weights)
        or base_logits.ndim != 2
        or adjustment.ndim != 2
        or base_logits.shape != adjustment.shape
    ):
        return reference.sum() * 0.0, 0.0

    target_indices = targets.to(device=base_logits.device, dtype=torch.long).view(-1)
    if int(target_indices.numel()) != int(base_logits.size(0)):
        return base_logits.sum() * 0.0, 0.0

    weights = route_weights.to(device=base_logits.device, dtype=torch.float32).view(-1)
    if int(weights.numel()) != int(base_logits.size(0)):
        return base_logits.sum() * 0.0, 0.0
    weights = weights.clamp(min=0.0)
    selected = weights > float(max(0.0, route_min_weight))
    if not bool(selected.any().item()):
        return adjustment.sum() * 0.0, 0.0

    reassessed_logits = base_logits.detach().float() + adjustment.float()
    per_sample = F.cross_entropy(reassessed_logits, target_indices, reduction="none")
    selected_weights = weights[selected]
    loss = (per_sample[selected] * selected_weights).sum() / selected_weights.sum().clamp(min=1e-12)
    fraction = float(selected.float().mean().detach().cpu().item())
    return loss.to(dtype=adjustment.dtype), fraction


def _ordinal_maturity_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
) -> Tensor:
    maturity_score = features.get("ordinal_maturity_score")
    maturity_classes = [
        int(value)
        for value in getattr(model, "ordinal_maturity_classes", [])
    ]
    if (
        not torch.is_tensor(maturity_score)
        or maturity_score.ndim != 2
        or maturity_score.size(1) != 1
        or len(maturity_classes) < 2
    ):
        reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
        return reference.sum() * 0.0

    target_indices = targets.to(device=maturity_score.device, dtype=torch.long).view(-1)
    valid = torch.zeros_like(target_indices, dtype=torch.bool)
    target_scores = torch.zeros_like(target_indices, dtype=torch.float32)
    centered_ranks = torch.arange(
        len(maturity_classes),
        device=maturity_score.device,
        dtype=torch.float32,
    )
    centered_ranks = centered_ranks - centered_ranks.mean()
    for rank, class_index in enumerate(maturity_classes):
        class_mask = target_indices == int(class_index)
        valid = valid | class_mask
        target_scores[class_mask] = centered_ranks[rank]
    if not bool(valid.any().item()):
        return maturity_score.sum() * 0.0

    predicted = maturity_score[:, 0].float()[valid]
    expected = target_scores[valid]
    return F.smooth_l1_loss(predicted, expected).to(dtype=maturity_score.dtype)


def _parse_cumulative_ordinal_threshold_weights(
    value: Union[str, Sequence[float], None],
    *,
    threshold_count: int,
    device: torch.device,
) -> Tensor:
    if isinstance(value, str):
        raw_values = [part.strip() for part in value.replace(";", ",").split(",") if part.strip()]
    elif value is None:
        raw_values = []
    else:
        raw_values = [str(item).strip() for item in value]
    weights: List[float] = []
    for raw_value in raw_values:
        try:
            weights.append(float(raw_value))
        except ValueError as exc:
            raise ValueError(
                f"cumulative ordinal threshold weight khong hop le: {raw_value!r}"
            ) from exc
    if not weights:
        weights = [1.0 for _ in range(max(0, int(threshold_count)))]
    while len(weights) < int(threshold_count):
        weights.append(float(weights[-1]))
    weights = weights[: int(threshold_count)]
    weights = [max(0.0, float(weight)) for weight in weights]
    if sum(weights) <= 0.0:
        weights = [1.0 for _ in range(max(0, int(threshold_count)))]
    return torch.tensor(weights, device=device, dtype=torch.float32)


def _cumulative_ordinal_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    threshold_weights: Union[str, Sequence[float], None] = "1.4,1.4,1.0",
) -> Tensor:
    threshold_logits = features.get("cumulative_ordinal_logits")
    ordered_classes = [
        int(value)
        for value in getattr(model, "cumulative_ordinal_classes", [])
    ]
    if (
        not torch.is_tensor(threshold_logits)
        or threshold_logits.ndim != 2
        or len(ordered_classes) < 2
        or int(threshold_logits.size(1)) != len(ordered_classes) - 1
    ):
        reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
        return reference.sum() * 0.0

    target_indices = targets.to(device=threshold_logits.device, dtype=torch.long).view(-1)
    rank_by_class = {
        int(class_index): int(rank)
        for rank, class_index in enumerate(ordered_classes)
    }
    ranks = torch.full_like(target_indices, fill_value=-1, dtype=torch.long)
    for class_index, rank in rank_by_class.items():
        ranks[target_indices == int(class_index)] = int(rank)
    valid_ordered = ranks >= 0
    if not bool(valid_ordered.any().item()):
        return threshold_logits.sum() * 0.0

    weights = _parse_cumulative_ordinal_threshold_weights(
        threshold_weights,
        threshold_count=int(threshold_logits.size(1)),
        device=threshold_logits.device,
    )
    losses: List[Tensor] = []
    used_weights: List[Tensor] = []
    for threshold_index in range(int(threshold_logits.size(1))):
        # CORN-style conditional ordinal loss: threshold k is trained only
        # for samples that have reached rank >= k.
        valid = valid_ordered & (ranks >= int(threshold_index))
        if not bool(valid.any().item()):
            continue
        target = (ranks[valid] > int(threshold_index)).to(dtype=torch.float32)
        loss = F.binary_cross_entropy_with_logits(
            threshold_logits[valid, threshold_index].float(),
            target,
        )
        weight = weights[threshold_index].clamp(min=0.0)
        losses.append(loss * weight)
        used_weights.append(weight)
    if not losses:
        return threshold_logits.sum() * 0.0
    normalizer = torch.stack(used_weights).sum().clamp(min=1e-8)
    return (torch.stack(losses).sum() / normalizer).to(dtype=threshold_logits.dtype)


def _parse_angular_margin_classes(
    classes: Union[str, Sequence[int], None],
    *,
    num_classes: int,
) -> List[int]:
    if classes is None:
        return list(range(max(0, int(num_classes))))
    if isinstance(classes, str):
        value = classes.strip().lower()
        if value in {"", "all", "*"}:
            return list(range(max(0, int(num_classes))))
        raw_values = [part.strip() for part in value.split(",") if part.strip()]
    else:
        raw_values = [str(value).strip() for value in classes]

    parsed: List[int] = []
    seen = set()
    for raw_value in raw_values:
        class_index = int(raw_value)
        if class_index < 0 or class_index >= int(num_classes):
            raise ValueError(
                f"angular margin class index {class_index} nam ngoai [0, {int(num_classes) - 1}]."
            )
        if class_index not in seen:
            parsed.append(class_index)
            seen.add(class_index)
    return parsed


def _quantized_label_cpu_loss_from_logits(
    logits: Tensor,
    targets,
    *,
    classes: Union[str, Sequence[int], None] = "all",
    min_prior: float = 0.02,
    max_prior: float = 0.60,
    negative_weight: float = 1.0,
    non_negative_beta: float = 0.0,
) -> Tuple[Tensor, Dict[str, float]]:
    """Class-wise positive-unlabeled risk for ambiguous hard labels.

    A hard label is treated as an observed positive for its class; other samples
    are unlabeled rather than strict negatives. The class score is a one-vs-rest
    logit margin inside the selected class subset.
    """

    zero = logits.sum() * 0.0
    stats = {
        "class_count": 0.0,
        "prior_mean": 0.0,
        "positive_fraction": 0.0,
        "negative_risk": 0.0,
    }
    if not torch.is_tensor(logits) or logits.ndim != 2 or logits.size(0) == 0:
        return zero, stats

    num_classes = int(logits.size(1))
    selected_classes = _parse_angular_margin_classes(classes, num_classes=num_classes)
    if len(selected_classes) < 2:
        return zero, stats

    target_probabilities = _classification_targets_to_probabilities(
        targets,
        labels=None,
        num_classes=num_classes,
        device=logits.device,
        dtype=torch.float32,
    )
    if target_probabilities is None:
        return zero, stats
    target_probabilities = target_probabilities.to(device=logits.device, dtype=torch.float32)
    if target_probabilities.ndim != 2 or target_probabilities.size(0) != logits.size(0):
        return zero, stats

    selected = torch.tensor(selected_classes, device=logits.device, dtype=torch.long)
    selected_logits = logits.float().index_select(1, selected)
    batch_size = float(max(1, int(logits.size(0))))
    min_prior_value = float(max(0.0, min(float(min_prior), 1.0)))
    max_prior_value = float(max(min_prior_value, min(float(max_prior), 1.0)))
    beta = float(max(0.0, non_negative_beta))
    unlabeled_weight = float(max(0.0, negative_weight))

    losses: List[Tensor] = []
    priors: List[Tensor] = []
    positive_fractions: List[Tensor] = []
    negative_risks: List[Tensor] = []
    for local_index, class_index in enumerate(selected_classes):
        positive_weights = target_probabilities[:, int(class_index)].clamp(min=0.0)
        positive_sum = positive_weights.sum()
        if float(positive_sum.detach().cpu().item()) <= 1e-8:
            continue

        if int(selected_logits.size(1)) == 1:
            score = selected_logits[:, local_index]
        else:
            other_mask = torch.ones(
                int(selected_logits.size(1)),
                device=logits.device,
                dtype=torch.bool,
            )
            other_mask[local_index] = False
            score = selected_logits[:, local_index] - torch.logsumexp(
                selected_logits[:, other_mask],
                dim=1,
            )

        prior = (positive_sum / batch_size).clamp(
            min=min_prior_value,
            max=max_prior_value,
        )
        positive_loss = (F.softplus(-score) * positive_weights).sum() / positive_sum.clamp(min=1e-8)
        positive_negative_loss = (
            F.softplus(score) * positive_weights
        ).sum() / positive_sum.clamp(min=1e-8)
        unlabeled_negative_loss = F.softplus(score).mean()
        negative_risk = unlabeled_negative_loss - prior * positive_negative_loss
        negative_component = torch.clamp(negative_risk, min=beta)
        losses.append(prior * positive_loss + unlabeled_weight * negative_component)
        priors.append(prior.detach())
        positive_fractions.append((positive_sum / batch_size).detach())
        negative_risks.append(negative_risk.detach())

    if not losses:
        return zero, stats

    stats = {
        "class_count": float(len(losses)),
        "prior_mean": float(torch.stack(priors).mean().cpu().item()) if priors else 0.0,
        "positive_fraction": (
            float(torch.stack(positive_fractions).mean().cpu().item())
            if positive_fractions
            else 0.0
        ),
        "negative_risk": (
            float(torch.stack(negative_risks).mean().cpu().item())
            if negative_risks
            else 0.0
        ),
    }
    return torch.stack(losses).mean().to(dtype=logits.dtype), stats


def _classification_head_weight(model: nn.Module) -> Optional[Tensor]:
    module = getattr(model, "module", model)
    for head_name in ("head", "classification_head"):
        head = getattr(module, head_name, None)
        weight = getattr(head, "weight", None)
        if torch.is_tensor(weight) and weight.ndim == 2:
            return weight
    return None


def _classification_logits_from_head_input(model: nn.Module, head_input: Tensor) -> Optional[Tensor]:
    module = getattr(model, "module", model)
    for head_name in ("head", "classification_head"):
        head = getattr(module, head_name, None)
        if callable(head):
            return head(head_input)
    weight = _classification_head_weight(model)
    if weight is None:
        return None
    bias = None
    for head_name in ("head", "classification_head"):
        head = getattr(module, head_name, None)
        value = getattr(head, "bias", None)
        if torch.is_tensor(value):
            bias = value
            break
    return F.linear(head_input, weight, bias)


def _confusion_pair_mixup_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    alpha: float = 0.40,
    pairs: Union[str, Sequence[Tuple[int, int]]] = "0-1,1-2,1-4,2-3",
    max_pairs: int = 64,
    num_classes: int,
) -> Tuple[Tensor, float, float, float]:
    reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
    try:
        head_input = extract_head_input_from_features(model, features)
    except KeyError:
        return reference.sum() * 0.0, 0.0, 0.0, 0.0
    if not torch.is_tensor(head_input) or head_input.ndim != 2 or head_input.size(0) < 2:
        return reference.sum() * 0.0, 0.0, 0.0, 0.0

    target_indices = targets.to(device=head_input.device, dtype=torch.long).view(-1)
    if target_indices.numel() != head_input.size(0):
        return head_input.sum() * 0.0, 0.0, 0.0, 0.0

    if isinstance(pairs, str):
        parsed_pairs = _parse_boundary_contrastive_pairs(pairs, num_classes=num_classes)
    else:
        parsed_pairs = [(int(left), int(right)) for left, right in pairs]
    if not parsed_pairs:
        return head_input.sum() * 0.0, 0.0, 0.0, 0.0

    left_indices: List[Tensor] = []
    right_indices: List[Tensor] = []
    for left_class, right_class in parsed_pairs:
        if left_class < 0 or right_class < 0:
            continue
        if left_class >= int(num_classes) or right_class >= int(num_classes):
            continue
        left_pool = torch.nonzero(target_indices == int(left_class), as_tuple=False).flatten()
        right_pool = torch.nonzero(target_indices == int(right_class), as_tuple=False).flatten()
        pair_count = min(int(left_pool.numel()), int(right_pool.numel()))
        if pair_count <= 0:
            continue
        if int(max_pairs) > 0:
            remaining = int(max_pairs) - sum(int(item.numel()) for item in left_indices)
            if remaining <= 0:
                break
            pair_count = min(pair_count, remaining)
        left_perm = torch.randperm(int(left_pool.numel()), device=head_input.device)[:pair_count]
        right_perm = torch.randperm(int(right_pool.numel()), device=head_input.device)[:pair_count]
        left_indices.append(left_pool.index_select(0, left_perm))
        right_indices.append(right_pool.index_select(0, right_perm))

    if not left_indices:
        return head_input.sum() * 0.0, 0.0, 0.0, 0.0

    first = torch.cat(left_indices, dim=0)
    second = torch.cat(right_indices, dim=0)
    mixed_count = int(first.numel())
    if mixed_count <= 0:
        return head_input.sum() * 0.0, 0.0, 0.0, 0.0

    beta = torch.distributions.Beta(
        torch.tensor(float(alpha), device=head_input.device, dtype=torch.float32),
        torch.tensor(float(alpha), device=head_input.device, dtype=torch.float32),
    )
    lam = beta.sample((mixed_count,)).to(device=head_input.device, dtype=head_input.dtype)
    # Keep one endpoint dominant; this behaves as boundary smoothing instead of
    # creating many ambiguous midpoint labels in a noisy fine-grained split.
    lam = torch.maximum(lam, 1.0 - lam).clamp(0.5, 1.0)
    mixed_head_input = (
        lam.unsqueeze(1) * head_input.index_select(0, first)
        + (1.0 - lam).unsqueeze(1) * head_input.index_select(0, second)
    )
    mixed_logits = _classification_logits_from_head_input(model, mixed_head_input)
    if not torch.is_tensor(mixed_logits) or mixed_logits.ndim != 2:
        return head_input.sum() * 0.0, 0.0, 0.0, 0.0

    target_first = F.one_hot(target_indices.index_select(0, first), num_classes=num_classes).to(
        device=mixed_logits.device,
        dtype=mixed_logits.dtype,
    )
    target_second = F.one_hot(target_indices.index_select(0, second), num_classes=num_classes).to(
        device=mixed_logits.device,
        dtype=mixed_logits.dtype,
    )
    soft_targets = lam.to(device=mixed_logits.device, dtype=mixed_logits.dtype).unsqueeze(1) * target_first
    soft_targets = soft_targets + (
        1.0 - lam.to(device=mixed_logits.device, dtype=mixed_logits.dtype).unsqueeze(1)
    ) * target_second
    loss = -(soft_targets * F.log_softmax(mixed_logits.float(), dim=1)).sum(dim=1).mean()
    fraction = float(mixed_count) / float(max(1, int(head_input.size(0))))
    lambda_mean = float(lam.detach().float().mean().cpu().item())
    return loss.to(dtype=head_input.dtype), float(fraction), float(mixed_count), lambda_mean


def _classification_targets_to_probabilities(
    targets,
    *,
    labels: Optional[Tensor],
    num_classes: int,
    device: torch.device,
    dtype: torch.dtype,
) -> Optional[Tensor]:
    if torch.is_tensor(targets) and targets.ndim == 2 and targets.size(1) == int(num_classes):
        probabilities = targets.to(device=device, dtype=dtype)
        return probabilities / probabilities.sum(dim=1, keepdim=True).clamp(min=1e-12)
    hard_targets = None
    if torch.is_tensor(labels):
        hard_targets = labels.to(device=device, dtype=torch.long).view(-1)
    elif torch.is_tensor(targets) and targets.ndim == 1:
        hard_targets = targets.to(device=device, dtype=torch.long).view(-1)
    if hard_targets is None:
        return None
    return F.one_hot(hard_targets, num_classes=int(num_classes)).to(device=device, dtype=dtype)


def _normalized_bbox_to_pixels(
    bbox: Tensor,
    *,
    height: int,
    width: int,
    margin_ratio: float,
) -> Tuple[int, int, int, int]:
    values = bbox[:4].detach().float().cpu().tolist()
    center_x, center_y, box_width, box_height = [float(value) for value in values]
    margin = float(max(0.0, margin_ratio))
    box_width = max(1e-4, min(1.0, box_width + 2.0 * margin))
    box_height = max(1e-4, min(1.0, box_height + 2.0 * margin))
    x1 = int(math.floor((center_x - box_width * 0.5) * width))
    y1 = int(math.floor((center_y - box_height * 0.5) * height))
    x2 = int(math.ceil((center_x + box_width * 0.5) * width))
    y2 = int(math.ceil((center_y + box_height * 0.5) * height))
    x1 = max(0, min(width - 1, x1))
    y1 = max(0, min(height - 1, y1))
    x2 = max(x1 + 1, min(width, x2))
    y2 = max(y1 + 1, min(height, y2))
    return x1, y1, x2, y2


def _foreground_snapmix_batch(
    *,
    images: Tensor,
    targets,
    labels: Optional[Tensor],
    bboxes: Optional[Tensor],
    num_classes: int,
    probability: float,
    alpha: float,
    pairs: Union[str, Sequence[Tuple[int, int]]],
    min_area_ratio: float,
    max_area_ratio: float,
    bbox_margin_ratio: float,
) -> Tuple[Optional[Tensor], Optional[Tensor], Optional[Tensor], Dict[str, float]]:
    stats = {
        "fraction": 0.0,
        "count": 0.0,
        "source_weight": 0.0,
        "target_removed": 0.0,
    }
    if (
        images.ndim != 4
        or images.size(0) < 2
        or int(num_classes) <= 1
        or float(probability) <= 0.0
        or float(alpha) <= 0.0
        or not torch.is_tensor(labels)
        or not torch.is_tensor(bboxes)
    ):
        return None, None, None, stats
    batch_size, _, height, width = images.shape
    if bboxes.ndim == 3:
        bboxes = bboxes[:, 0]
    if bboxes.ndim != 2 or bboxes.size(0) != batch_size or bboxes.size(1) < 4:
        return None, None, None, stats

    target_probabilities = _classification_targets_to_probabilities(
        targets,
        labels=labels,
        num_classes=int(num_classes),
        device=images.device,
        dtype=images.dtype,
    )
    if target_probabilities is None or target_probabilities.size(0) != batch_size:
        return None, None, None, stats

    hard_labels = labels.to(device=images.device, dtype=torch.long).view(-1)
    if hard_labels.numel() != batch_size:
        return None, None, None, stats
    if isinstance(pairs, str):
        parsed_pairs = _parse_boundary_contrastive_pairs(pairs, num_classes=int(num_classes))
    else:
        parsed_pairs = [(int(left), int(right)) for left, right in pairs]
    allowed = torch.zeros(
        (int(num_classes), int(num_classes)),
        device=images.device,
        dtype=torch.bool,
    )
    for left, right in parsed_pairs:
        if left < 0 or right < 0 or left >= int(num_classes) or right >= int(num_classes):
            continue
        allowed[left, right] = True
        allowed[right, left] = True
    if not bool(allowed.any().item()):
        return None, None, None, stats

    selected_mask = torch.rand(batch_size, device=images.device) < float(probability)
    shuffled = torch.randperm(batch_size, device=images.device)
    pair_mask = allowed[hard_labels, hard_labels.index_select(0, shuffled)]
    not_self = shuffled != torch.arange(batch_size, device=images.device)
    selected_indices = torch.nonzero(selected_mask & pair_mask & not_self, as_tuple=False).flatten()
    if selected_indices.numel() == 0:
        return None, None, None, stats

    selected_indices_cpu = selected_indices.detach().cpu().tolist()
    source_indices = shuffled.index_select(0, selected_indices)
    source_indices_cpu = source_indices.detach().cpu().tolist()
    mixed_images = images.index_select(0, selected_indices).clone()
    mixed_targets = target_probabilities.index_select(0, selected_indices).clone()
    beta = torch.distributions.Beta(
        torch.tensor(float(alpha), device=images.device, dtype=torch.float32),
        torch.tensor(float(alpha), device=images.device, dtype=torch.float32),
    )
    min_ratio = float(max(1e-4, min(0.95, min_area_ratio)))
    max_ratio = float(max(min_ratio, min(0.95, max_area_ratio)))
    source_weights: List[float] = []
    target_removed_values: List[float] = []
    kept_rows: List[int] = []

    for out_row, (target_index, source_index) in enumerate(zip(selected_indices_cpu, source_indices_cpu)):
        target_box = _normalized_bbox_to_pixels(
            bboxes[target_index],
            height=height,
            width=width,
            margin_ratio=bbox_margin_ratio,
        )
        source_box = _normalized_bbox_to_pixels(
            bboxes[source_index],
            height=height,
            width=width,
            margin_ratio=bbox_margin_ratio,
        )
        tx1, ty1, tx2, ty2 = target_box
        sx1, sy1, sx2, sy2 = source_box
        target_w = max(1, tx2 - tx1)
        target_h = max(1, ty2 - ty1)
        source_w = max(1, sx2 - sx1)
        source_h = max(1, sy2 - sy1)
        object_area = float(max(1, target_w * target_h))
        sampled = float(beta.sample().detach().cpu().item())
        area_ratio = min_ratio + (max_ratio - min_ratio) * sampled
        patch_area = max(1.0, object_area * area_ratio)
        aspect = float(source_w) / float(max(1, source_h))
        patch_h = int(round(math.sqrt(patch_area / max(1e-6, aspect))))
        patch_w = int(round(patch_h * aspect))
        patch_w = max(2, min(patch_w, target_w, source_w))
        patch_h = max(2, min(patch_h, target_h, source_h))
        if patch_w <= 1 or patch_h <= 1:
            continue

        source_max_x = max(sx1, sx2 - patch_w)
        source_max_y = max(sy1, sy2 - patch_h)
        target_max_x = max(tx1, tx2 - patch_w)
        target_max_y = max(ty1, ty2 - patch_h)
        source_x1 = int(torch.randint(sx1, source_max_x + 1, (1,), device=images.device).item())
        source_y1 = int(torch.randint(sy1, source_max_y + 1, (1,), device=images.device).item())
        target_x1 = int(torch.randint(tx1, target_max_x + 1, (1,), device=images.device).item())
        target_y1 = int(torch.randint(ty1, target_max_y + 1, (1,), device=images.device).item())
        source_x2 = min(width, source_x1 + patch_w)
        source_y2 = min(height, source_y1 + patch_h)
        target_x2 = min(width, target_x1 + patch_w)
        target_y2 = min(height, target_y1 + patch_h)
        actual_w = min(source_x2 - source_x1, target_x2 - target_x1)
        actual_h = min(source_y2 - source_y1, target_y2 - target_y1)
        if actual_w <= 1 or actual_h <= 1:
            continue
        source_x2 = source_x1 + actual_w
        source_y2 = source_y1 + actual_h
        target_x2 = target_x1 + actual_w
        target_y2 = target_y1 + actual_h

        mixed_images[out_row, :, target_y1:target_y2, target_x1:target_x2] = images[
            source_index,
            :,
            source_y1:source_y2,
            source_x1:source_x2,
        ]
        replaced_area = float(actual_w * actual_h)
        target_removed = min(0.95, replaced_area / float(max(1, target_w * target_h)))
        source_semantic = min(0.95, replaced_area / float(max(1, source_w * source_h)))
        target_weight = max(1e-4, 1.0 - target_removed)
        source_weight = max(1e-4, source_semantic)
        normalizer = target_weight + source_weight
        source_weight_normalized = source_weight / normalizer
        target_weight_normalized = target_weight / normalizer
        mixed_targets[out_row] = (
            target_weight_normalized * target_probabilities[target_index]
            + source_weight_normalized * target_probabilities[source_index]
        )
        source_weights.append(float(source_weight_normalized))
        target_removed_values.append(float(target_removed))
        kept_rows.append(out_row)

    if not kept_rows:
        return None, None, None, stats
    kept = torch.tensor(kept_rows, device=images.device, dtype=torch.long)
    mixed_images = mixed_images.index_select(0, kept)
    mixed_targets = mixed_targets.index_select(0, kept)
    selected_indices = selected_indices.index_select(0, kept)
    stats.update(
        {
            "fraction": float(len(kept_rows)) / float(batch_size),
            "count": float(len(kept_rows)),
            "source_weight": float(np.mean(source_weights)) if source_weights else 0.0,
            "target_removed": float(np.mean(target_removed_values)) if target_removed_values else 0.0,
        }
    )
    return mixed_images, mixed_targets, selected_indices, stats


def _foreground_snapmix_auxiliary_loss(
    *,
    model: nn.Module,
    criterion: nn.Module,
    images: Tensor,
    targets,
    labels: Optional[Tensor],
    crop_bboxes: Optional[Tensor],
    bbox_metadata: Optional[Tensor],
    bbox_token_prior: Optional[Tensor],
    image_valid_mask: Optional[Tensor],
    num_classes: int,
    probability: float,
    alpha: float,
    pairs: Union[str, Sequence[Tuple[int, int]]],
    min_area_ratio: float,
    max_area_ratio: float,
    bbox_margin_ratio: float,
) -> Tuple[Tensor, Dict[str, float]]:
    reference = images
    source_bboxes = crop_bboxes if torch.is_tensor(crop_bboxes) else bbox_metadata
    mixed_images, mixed_targets, selected_indices, stats = _foreground_snapmix_batch(
        images=images,
        targets=targets,
        labels=labels,
        bboxes=source_bboxes,
        num_classes=int(num_classes),
        probability=probability,
        alpha=alpha,
        pairs=pairs,
        min_area_ratio=min_area_ratio,
        max_area_ratio=max_area_ratio,
        bbox_margin_ratio=bbox_margin_ratio,
    )
    if (
        mixed_images is None
        or mixed_targets is None
        or selected_indices is None
        or mixed_images.size(0) == 0
    ):
        return reference.sum() * 0.0, stats

    selected_bbox_metadata = None
    if torch.is_tensor(bbox_metadata) and bbox_metadata.size(0) == images.size(0):
        selected_bbox_metadata = bbox_metadata.index_select(0, selected_indices.to(device=bbox_metadata.device))
    selected_bbox_token_prior = None
    if torch.is_tensor(bbox_token_prior) and bbox_token_prior.size(0) == images.size(0):
        selected_bbox_token_prior = bbox_token_prior.index_select(
            0,
            selected_indices.to(device=bbox_token_prior.device),
        )
    selected_mask = None
    if torch.is_tensor(image_valid_mask) and image_valid_mask.size(0) == images.size(0):
        selected_mask = image_valid_mask.index_select(
            0,
            selected_indices.to(device=image_valid_mask.device),
        )
    _, mixed_outputs = _forward_model_outputs(
        model,
        mixed_images,
        image_valid_mask=selected_mask,
        bbox_metadata=selected_bbox_metadata,
        bbox_token_prior=selected_bbox_token_prior,
    )
    mixed_logits, _ = extract_bbox_from_model_output(mixed_outputs)
    if not torch.is_tensor(mixed_logits) or mixed_logits.ndim != 2:
        return reference.sum() * 0.0, stats
    loss = criterion(mixed_logits, mixed_targets.to(device=mixed_logits.device, dtype=mixed_logits.dtype))
    return loss.to(dtype=mixed_logits.dtype), stats


def _foreground_counterexample_mix_batch(
    *,
    images: Tensor,
    targets,
    labels: Optional[Tensor],
    bboxes: Optional[Tensor],
    num_classes: int,
    probability: float,
    source_class: int,
    target_classes: Union[str, Sequence[int], None],
    alpha: float,
    min_area_ratio: float,
    max_area_ratio: float,
    bbox_margin_ratio: float,
) -> Tuple[Optional[Tensor], Optional[Tensor], Optional[Tensor], Dict[str, float]]:
    stats = {
        "fraction": 0.0,
        "count": 0.0,
        "source_area": 0.0,
        "target_removed": 0.0,
        "source_class": float(max(0, int(source_class))),
    }
    if (
        images.ndim != 4
        or images.size(0) < 2
        or int(num_classes) <= 1
        or float(probability) <= 0.0
        or float(alpha) <= 0.0
        or not torch.is_tensor(labels)
        or not torch.is_tensor(bboxes)
    ):
        return None, None, None, stats

    batch_size, _, height, width = images.shape
    source_class = int(source_class)
    if source_class < 0 or source_class >= int(num_classes):
        return None, None, None, stats
    if bboxes.ndim == 3:
        bboxes = bboxes[:, 0]
    if bboxes.ndim != 2 or bboxes.size(0) != batch_size or bboxes.size(1) < 4:
        return None, None, None, stats

    target_probabilities = _classification_targets_to_probabilities(
        targets,
        labels=labels,
        num_classes=int(num_classes),
        device=images.device,
        dtype=images.dtype,
    )
    if target_probabilities is None or target_probabilities.size(0) != batch_size:
        return None, None, None, stats

    hard_labels = labels.to(device=images.device, dtype=torch.long).view(-1)
    if hard_labels.numel() != batch_size:
        return None, None, None, stats
    parsed_target_classes = _parse_angular_margin_classes(
        target_classes,
        num_classes=int(num_classes),
    )
    parsed_target_classes = [
        int(class_index)
        for class_index in parsed_target_classes
        if int(class_index) != source_class
    ]
    if not parsed_target_classes:
        return None, None, None, stats

    target_class_tensor = torch.tensor(
        parsed_target_classes,
        device=images.device,
        dtype=torch.long,
    )
    target_mask = (hard_labels.unsqueeze(1) == target_class_tensor.unsqueeze(0)).any(dim=1)
    source_indices = torch.nonzero(hard_labels == source_class, as_tuple=False).flatten()
    if source_indices.numel() == 0:
        return None, None, None, stats

    selected_mask = target_mask & (torch.rand(batch_size, device=images.device) < float(probability))
    selected_indices = torch.nonzero(selected_mask, as_tuple=False).flatten()
    if selected_indices.numel() == 0:
        return None, None, None, stats

    random_source_rows = torch.randint(
        0,
        int(source_indices.numel()),
        (int(selected_indices.numel()),),
        device=images.device,
    )
    paired_source_indices = source_indices.index_select(0, random_source_rows)
    selected_indices_cpu = selected_indices.detach().cpu().tolist()
    source_indices_cpu = paired_source_indices.detach().cpu().tolist()
    mixed_images = images.index_select(0, selected_indices).clone()
    mixed_targets = target_probabilities.index_select(0, selected_indices).clone()
    beta = torch.distributions.Beta(
        torch.tensor(float(alpha), device=images.device, dtype=torch.float32),
        torch.tensor(float(alpha), device=images.device, dtype=torch.float32),
    )
    min_ratio = float(max(1e-4, min(0.95, min_area_ratio)))
    max_ratio = float(max(min_ratio, min(0.95, max_area_ratio)))
    source_area_values: List[float] = []
    target_removed_values: List[float] = []
    kept_rows: List[int] = []

    for out_row, (target_index, source_index) in enumerate(
        zip(selected_indices_cpu, source_indices_cpu)
    ):
        target_box = _normalized_bbox_to_pixels(
            bboxes[target_index],
            height=height,
            width=width,
            margin_ratio=bbox_margin_ratio,
        )
        source_box = _normalized_bbox_to_pixels(
            bboxes[source_index],
            height=height,
            width=width,
            margin_ratio=bbox_margin_ratio,
        )
        tx1, ty1, tx2, ty2 = target_box
        sx1, sy1, sx2, sy2 = source_box
        target_w = max(1, tx2 - tx1)
        target_h = max(1, ty2 - ty1)
        source_w = max(1, sx2 - sx1)
        source_h = max(1, sy2 - sy1)
        object_area = float(max(1, target_w * target_h))
        sampled = float(beta.sample().detach().cpu().item())
        area_ratio = min_ratio + (max_ratio - min_ratio) * sampled
        patch_area = max(1.0, object_area * area_ratio)
        aspect = float(source_w) / float(max(1, source_h))
        patch_h = int(round(math.sqrt(patch_area / max(1e-6, aspect))))
        patch_w = int(round(patch_h * aspect))
        patch_w = max(2, min(patch_w, target_w, source_w))
        patch_h = max(2, min(patch_h, target_h, source_h))
        if patch_w <= 1 or patch_h <= 1:
            continue

        source_max_x = max(sx1, sx2 - patch_w)
        source_max_y = max(sy1, sy2 - patch_h)
        target_max_x = max(tx1, tx2 - patch_w)
        target_max_y = max(ty1, ty2 - patch_h)
        source_x1 = int(torch.randint(sx1, source_max_x + 1, (1,), device=images.device).item())
        source_y1 = int(torch.randint(sy1, source_max_y + 1, (1,), device=images.device).item())
        target_x1 = int(torch.randint(tx1, target_max_x + 1, (1,), device=images.device).item())
        target_y1 = int(torch.randint(ty1, target_max_y + 1, (1,), device=images.device).item())
        source_x2 = min(width, source_x1 + patch_w)
        source_y2 = min(height, source_y1 + patch_h)
        target_x2 = min(width, target_x1 + patch_w)
        target_y2 = min(height, target_y1 + patch_h)
        actual_w = min(source_x2 - source_x1, target_x2 - target_x1)
        actual_h = min(source_y2 - source_y1, target_y2 - target_y1)
        if actual_w <= 1 or actual_h <= 1:
            continue
        source_x2 = source_x1 + actual_w
        source_y2 = source_y1 + actual_h
        target_x2 = target_x1 + actual_w
        target_y2 = target_y1 + actual_h

        mixed_images[out_row, :, target_y1:target_y2, target_x1:target_x2] = images[
            source_index,
            :,
            source_y1:source_y2,
            source_x1:source_x2,
        ]
        replaced_area = float(actual_w * actual_h)
        target_removed_values.append(
            min(0.95, replaced_area / float(max(1, target_w * target_h)))
        )
        source_area_values.append(
            min(0.95, replaced_area / float(max(1, source_w * source_h)))
        )
        kept_rows.append(out_row)

    if not kept_rows:
        return None, None, None, stats
    kept = torch.tensor(kept_rows, device=images.device, dtype=torch.long)
    mixed_images = mixed_images.index_select(0, kept)
    mixed_targets = mixed_targets.index_select(0, kept)
    selected_indices = selected_indices.index_select(0, kept)
    stats.update(
        {
            "fraction": float(len(kept_rows)) / float(batch_size),
            "count": float(len(kept_rows)),
            "source_area": float(np.mean(source_area_values)) if source_area_values else 0.0,
            "target_removed": float(np.mean(target_removed_values)) if target_removed_values else 0.0,
            "source_class": float(source_class),
        }
    )
    return mixed_images, mixed_targets, selected_indices, stats


def _foreground_counterexample_mix_auxiliary_loss(
    *,
    model: nn.Module,
    criterion: nn.Module,
    images: Tensor,
    targets,
    labels: Optional[Tensor],
    crop_bboxes: Optional[Tensor],
    bbox_metadata: Optional[Tensor],
    bbox_token_prior: Optional[Tensor],
    image_valid_mask: Optional[Tensor],
    num_classes: int,
    probability: float,
    source_class: int,
    target_classes: Union[str, Sequence[int], None],
    alpha: float,
    min_area_ratio: float,
    max_area_ratio: float,
    bbox_margin_ratio: float,
) -> Tuple[Tensor, Dict[str, float]]:
    reference = images
    source_bboxes = crop_bboxes if torch.is_tensor(crop_bboxes) else bbox_metadata
    mixed_images, mixed_targets, selected_indices, stats = (
        _foreground_counterexample_mix_batch(
            images=images,
            targets=targets,
            labels=labels,
            bboxes=source_bboxes,
            num_classes=int(num_classes),
            probability=probability,
            source_class=source_class,
            target_classes=target_classes,
            alpha=alpha,
            min_area_ratio=min_area_ratio,
            max_area_ratio=max_area_ratio,
            bbox_margin_ratio=bbox_margin_ratio,
        )
    )
    if (
        mixed_images is None
        or mixed_targets is None
        or selected_indices is None
        or mixed_images.size(0) == 0
    ):
        return reference.sum() * 0.0, stats

    selected_bbox_metadata = None
    if torch.is_tensor(bbox_metadata) and bbox_metadata.size(0) == images.size(0):
        selected_bbox_metadata = bbox_metadata.index_select(
            0,
            selected_indices.to(device=bbox_metadata.device),
        )
    selected_bbox_token_prior = None
    if torch.is_tensor(bbox_token_prior) and bbox_token_prior.size(0) == images.size(0):
        selected_bbox_token_prior = bbox_token_prior.index_select(
            0,
            selected_indices.to(device=bbox_token_prior.device),
        )
    selected_mask = None
    if torch.is_tensor(image_valid_mask) and image_valid_mask.size(0) == images.size(0):
        selected_mask = image_valid_mask.index_select(
            0,
            selected_indices.to(device=image_valid_mask.device),
        )
    _, mixed_outputs = _forward_model_outputs(
        model,
        mixed_images,
        image_valid_mask=selected_mask,
        bbox_metadata=selected_bbox_metadata,
        bbox_token_prior=selected_bbox_token_prior,
    )
    mixed_logits, _ = extract_bbox_from_model_output(mixed_outputs)
    if not torch.is_tensor(mixed_logits) or mixed_logits.ndim != 2:
        return reference.sum() * 0.0, stats
    loss = criterion(
        mixed_logits,
        mixed_targets.to(device=mixed_logits.device, dtype=mixed_logits.dtype),
    )
    return loss.to(dtype=mixed_logits.dtype), stats


def _dcl_region_shuffle_batch(
    *,
    images: Tensor,
    targets,
    labels: Optional[Tensor],
    bboxes: Optional[Tensor],
    num_classes: int,
    probability: float,
    grid_size: int,
    bbox_margin_ratio: float,
    classes: Union[str, Sequence[int], None],
) -> Tuple[Optional[Tensor], Optional[Tensor], Optional[Tensor], Dict[str, float]]:
    stats = {
        "fraction": 0.0,
        "count": 0.0,
        "bbox_area_fraction": 0.0,
        "grid_size": float(max(0, int(grid_size))),
    }
    if (
        images.ndim != 4
        or images.size(0) <= 0
        or int(num_classes) <= 1
        or float(probability) <= 0.0
        or int(grid_size) < 2
        or not torch.is_tensor(labels)
    ):
        return None, None, None, stats

    batch_size, _, height, width = images.shape
    hard_labels = labels.to(device=images.device, dtype=torch.long).view(-1)
    if hard_labels.numel() != batch_size:
        return None, None, None, stats
    target_probabilities = _classification_targets_to_probabilities(
        targets,
        labels=labels,
        num_classes=int(num_classes),
        device=images.device,
        dtype=images.dtype,
    )
    if target_probabilities is None or target_probabilities.size(0) != batch_size:
        return None, None, None, stats

    selected = torch.rand(batch_size, device=images.device) < float(probability)
    selected_classes = _parse_angular_margin_classes(classes, num_classes=int(num_classes))
    if selected_classes:
        class_mask = torch.zeros(int(num_classes), device=images.device, dtype=torch.bool)
        class_mask[
            torch.tensor(selected_classes, device=images.device, dtype=torch.long)
        ] = True
        selected = selected & class_mask.index_select(
            0,
            hard_labels.clamp(min=0, max=max(0, int(num_classes) - 1)),
        )
    selected_indices = torch.nonzero(selected, as_tuple=False).flatten()
    if selected_indices.numel() == 0:
        return None, None, None, stats

    source_bboxes = bboxes
    if torch.is_tensor(source_bboxes) and source_bboxes.ndim == 3:
        source_bboxes = source_bboxes[:, 0]
    if torch.is_tensor(source_bboxes) and (
        source_bboxes.ndim != 2
        or source_bboxes.size(0) != batch_size
        or source_bboxes.size(1) < 4
    ):
        source_bboxes = None

    shuffled_images = images.index_select(0, selected_indices).clone()
    kept_rows: List[int] = []
    bbox_area_fractions: List[float] = []
    selected_indices_cpu = selected_indices.detach().cpu().tolist()
    grid = int(grid_size)
    for out_row, sample_index in enumerate(selected_indices_cpu):
        if torch.is_tensor(source_bboxes):
            x1, y1, x2, y2 = _normalized_bbox_to_pixels(
                source_bboxes[sample_index],
                height=height,
                width=width,
                margin_ratio=float(bbox_margin_ratio),
            )
        else:
            x1, y1, x2, y2 = 0, 0, int(width), int(height)
        region_w = max(0, x2 - x1)
        region_h = max(0, y2 - y1)
        cell_w = region_w // grid
        cell_h = region_h // grid
        if cell_w <= 1 or cell_h <= 1:
            continue
        usable_w = cell_w * grid
        usable_h = cell_h * grid
        region = shuffled_images[out_row, :, y1 : y1 + usable_h, x1 : x1 + usable_w].clone()
        if region.numel() == 0:
            continue
        cells: List[Tensor] = []
        for row in range(grid):
            for col in range(grid):
                cells.append(
                    region[
                        :,
                        row * cell_h : (row + 1) * cell_h,
                        col * cell_w : (col + 1) * cell_w,
                    ].clone()
                )
        perm = torch.randperm(grid * grid, device=images.device).detach().cpu().tolist()
        identity = list(range(grid * grid))
        if perm == identity:
            perm = perm[1:] + perm[:1]
        for dest, src in enumerate(perm):
            dest_row = dest // grid
            dest_col = dest % grid
            shuffled_images[
                out_row,
                :,
                y1 + dest_row * cell_h : y1 + (dest_row + 1) * cell_h,
                x1 + dest_col * cell_w : x1 + (dest_col + 1) * cell_w,
            ] = cells[int(src)]
        kept_rows.append(out_row)
        bbox_area_fractions.append(float(usable_w * usable_h) / float(max(1, height * width)))

    if not kept_rows:
        return None, None, None, stats
    kept = torch.tensor(kept_rows, device=images.device, dtype=torch.long)
    selected_indices = selected_indices.index_select(0, kept)
    shuffled_images = shuffled_images.index_select(0, kept)
    shuffled_targets = target_probabilities.index_select(0, selected_indices)
    stats.update(
        {
            "fraction": float(selected_indices.numel()) / float(batch_size),
            "count": float(selected_indices.numel()),
            "bbox_area_fraction": float(np.mean(bbox_area_fractions)) if bbox_area_fractions else 0.0,
            "grid_size": float(grid),
        }
    )
    return shuffled_images, shuffled_targets, selected_indices, stats


def _dcl_region_shuffle_auxiliary_loss(
    *,
    model: nn.Module,
    criterion: nn.Module,
    images: Tensor,
    targets,
    labels: Optional[Tensor],
    crop_bboxes: Optional[Tensor],
    bbox_metadata: Optional[Tensor],
    bbox_token_prior: Optional[Tensor],
    image_valid_mask: Optional[Tensor],
    num_classes: int,
    probability: float,
    grid_size: int,
    bbox_margin_ratio: float,
    classes: Union[str, Sequence[int], None],
) -> Tuple[Tensor, Dict[str, float]]:
    reference = images
    source_bboxes = crop_bboxes if torch.is_tensor(crop_bboxes) else bbox_metadata
    shuffled_images, shuffled_targets, selected_indices, stats = _dcl_region_shuffle_batch(
        images=images,
        targets=targets,
        labels=labels,
        bboxes=source_bboxes,
        num_classes=int(num_classes),
        probability=probability,
        grid_size=int(grid_size),
        bbox_margin_ratio=float(bbox_margin_ratio),
        classes=classes,
    )
    if (
        shuffled_images is None
        or shuffled_targets is None
        or selected_indices is None
        or shuffled_images.size(0) == 0
    ):
        return reference.sum() * 0.0, stats

    selected_bbox_metadata = None
    if torch.is_tensor(bbox_metadata) and bbox_metadata.size(0) == images.size(0):
        selected_bbox_metadata = bbox_metadata.index_select(
            0,
            selected_indices.to(device=bbox_metadata.device),
        )
    selected_bbox_token_prior = None
    if torch.is_tensor(bbox_token_prior) and bbox_token_prior.size(0) == images.size(0):
        selected_bbox_token_prior = bbox_token_prior.index_select(
            0,
            selected_indices.to(device=bbox_token_prior.device),
        )
    selected_mask = None
    if torch.is_tensor(image_valid_mask) and image_valid_mask.size(0) == images.size(0):
        selected_mask = image_valid_mask.index_select(
            0,
            selected_indices.to(device=image_valid_mask.device),
        )
    _, shuffled_outputs = _forward_model_outputs(
        model,
        shuffled_images,
        image_valid_mask=selected_mask,
        bbox_metadata=selected_bbox_metadata,
        bbox_token_prior=selected_bbox_token_prior,
    )
    shuffled_logits, _ = extract_bbox_from_model_output(shuffled_outputs)
    if not torch.is_tensor(shuffled_logits) or shuffled_logits.ndim != 2:
        return reference.sum() * 0.0, stats
    loss = criterion(
        shuffled_logits,
        shuffled_targets.to(device=shuffled_logits.device, dtype=shuffled_logits.dtype),
    )
    return loss.to(dtype=shuffled_logits.dtype), stats


def _bbox_token_label_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    min_prior: float = 0.45,
    prior_power: float = 1.0,
    classes: Union[str, Sequence[int], None] = "0,1,2,4",
    focus_class: int = 1,
    focus_weight: float = 1.25,
    detach_classifier: bool = True,
) -> Tuple[Tensor, Dict[str, float]]:
    reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
    stats = {
        "bbox_token_label_fraction": 0.0,
        "bbox_token_label_sample_fraction": 0.0,
        "bbox_token_label_focus_fraction": 0.0,
        "bbox_token_label_mean_prior": 0.0,
        "bbox_token_label_accuracy": 0.0,
        "bbox_token_label_target_margin": 0.0,
    }
    patches = features.get("patches")
    bbox_prior = features.get("patch_bbox_prior")
    if (
        not torch.is_tensor(patches)
        or patches.ndim != 3
        or not torch.is_tensor(bbox_prior)
        or bbox_prior.ndim != 2
        or tuple(bbox_prior.shape) != tuple(patches.shape[:2])
    ):
        return reference.sum() * 0.0, stats

    module = getattr(model, "module", model)
    head = getattr(module, "head", None)
    if head is None or not callable(head):
        return patches.sum() * 0.0, stats
    batch_size, token_count, feature_dim = patches.shape
    flat_patches = patches.reshape(batch_size * token_count, feature_dim)
    if (
        bool(detach_classifier)
        and isinstance(head, nn.Linear)
        and int(head.weight.size(1)) == int(feature_dim)
    ):
        flat_logits = F.linear(
            flat_patches,
            head.weight.detach(),
            head.bias.detach() if torch.is_tensor(head.bias) else None,
        )
    else:
        flat_logits = head(flat_patches)
    if not torch.is_tensor(flat_logits) or flat_logits.ndim != 2:
        return patches.sum() * 0.0, stats
    num_classes = int(flat_logits.size(1))
    patch_logits = flat_logits.reshape(batch_size, token_count, num_classes)
    target_indices = targets.to(device=patch_logits.device, dtype=torch.long).view(-1)
    if target_indices.numel() != batch_size:
        return patch_logits.sum() * 0.0, stats

    valid_samples = (target_indices >= 0) & (target_indices < num_classes)
    selected_classes = _parse_angular_margin_classes(classes, num_classes=num_classes)
    if selected_classes:
        selected = torch.zeros(num_classes, device=patch_logits.device, dtype=torch.bool)
        selected[torch.tensor(selected_classes, device=patch_logits.device, dtype=torch.long)] = True
        valid_samples = valid_samples & selected.index_select(
            0,
            target_indices.clamp(min=0, max=max(0, num_classes - 1)),
        )
    if not bool(valid_samples.any().item()):
        return patch_logits.sum() * 0.0, stats

    bbox_values = bbox_prior.to(device=patch_logits.device, dtype=torch.float32).clamp(0.0, 1.0)
    token_mask = (bbox_values >= float(min_prior)) & valid_samples[:, None]
    key_padding_mask = features.get("memory_key_padding_mask")
    if torch.is_tensor(key_padding_mask) and tuple(key_padding_mask.shape) == tuple(token_mask.shape):
        token_mask = token_mask & (~key_padding_mask.to(device=patch_logits.device, dtype=torch.bool))
    if not bool(token_mask.any().item()):
        return patch_logits.sum() * 0.0, stats

    expanded_targets = target_indices[:, None].expand(batch_size, token_count)
    selected_logits = patch_logits[token_mask].float()
    selected_targets = expanded_targets[token_mask]
    per_token = F.cross_entropy(
        selected_logits,
        selected_targets,
        reduction="none",
    )
    weights = bbox_values.pow(float(max(0.0, prior_power))).clamp(min=1e-6)
    if 0 <= int(focus_class) < num_classes and float(focus_weight) > 0.0:
        focus_multiplier = torch.ones(batch_size, device=patch_logits.device, dtype=weights.dtype)
        focus_multiplier[target_indices == int(focus_class)] = float(focus_weight)
        weights = weights * focus_multiplier[:, None]
    selected_weights = weights[token_mask]
    loss = (per_token * selected_weights).sum() / selected_weights.sum().clamp(min=1e-12)

    with torch.no_grad():
        predictions = selected_logits.argmax(dim=1)
        one_hot = F.one_hot(selected_targets, num_classes=num_classes).to(dtype=torch.bool)
        target_scores = selected_logits.gather(1, selected_targets[:, None]).squeeze(1)
        negative_scores = selected_logits.masked_fill(one_hot, -1.0e4).max(dim=1).values
        selected_token_count = float(token_mask.sum().detach().cpu().item())
        total_token_count = float(max(1, batch_size * token_count))
        selected_sample_count = float(token_mask.any(dim=1).sum().detach().cpu().item())
        stats = {
            "bbox_token_label_fraction": selected_token_count / total_token_count,
            "bbox_token_label_sample_fraction": selected_sample_count / float(max(1, batch_size)),
            "bbox_token_label_focus_fraction": float(
                ((selected_targets == int(focus_class)).float().mean().detach().cpu().item())
                if selected_targets.numel() > 0
                else 0.0
            ),
            "bbox_token_label_mean_prior": float(
                bbox_values[token_mask].detach().float().mean().cpu().item()
            ),
            "bbox_token_label_accuracy": float(
                (predictions == selected_targets).float().mean().detach().cpu().item()
            ),
            "bbox_token_label_target_margin": float(
                (target_scores - negative_scores).detach().float().mean().cpu().item()
            ),
        }
    return loss.to(dtype=patches.dtype), stats


def _angular_margin_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    margin: float = 0.12,
    scale: float = 16.0,
    classes: Union[str, Sequence[int], None] = "0,1,2,3",
) -> Tensor:
    reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
    head_weight = _classification_head_weight(model)
    try:
        head_input = extract_head_input_from_features(model, features)
    except KeyError:
        return reference.sum() * 0.0
    if (
        head_weight is None
        or not torch.is_tensor(head_input)
        or head_input.ndim != 2
        or head_weight.ndim != 2
        or head_input.size(1) != head_weight.size(1)
    ):
        return reference.sum() * 0.0

    num_classes = int(head_weight.size(0))
    target_indices = targets.to(device=head_input.device, dtype=torch.long).view(-1)
    valid = (target_indices >= 0) & (target_indices < num_classes)
    selected_classes = _parse_angular_margin_classes(classes, num_classes=num_classes)
    if selected_classes:
        selected = torch.zeros(num_classes, device=head_input.device, dtype=torch.bool)
        selected[torch.tensor(selected_classes, device=head_input.device, dtype=torch.long)] = True
        valid = valid & selected.index_select(0, target_indices.clamp(0, max(0, num_classes - 1)))
    if not bool(valid.any().item()):
        return head_input.sum() * 0.0

    normalized_features = F.normalize(head_input.float(), dim=1, eps=1e-6)
    normalized_weight = F.normalize(head_weight.float(), dim=1, eps=1e-6)
    cosine_logits = F.linear(normalized_features, normalized_weight).clamp(-1.0 + 1e-6, 1.0 - 1e-6)
    cosine_logits = cosine_logits[valid].clone()
    valid_targets = target_indices[valid]
    rows = torch.arange(valid_targets.numel(), device=head_input.device)
    cosine_logits[rows, valid_targets] = cosine_logits[rows, valid_targets] - float(margin)
    angular_loss = F.cross_entropy(cosine_logits * float(scale), valid_targets)
    return angular_loss.to(dtype=head_input.dtype)


def _subcenter_proxy_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    targets: Tensor,
    margin: float = 0.08,
    scale: float = 12.0,
    classes: Union[str, Sequence[int], None] = "0,1,2,4",
) -> Tuple[Tensor, Dict[str, float]]:
    reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
    stats = {
        "valid_fraction": 0.0,
        "positive_similarity": 0.0,
        "negative_similarity": 0.0,
        "positive_negative_margin": 0.0,
        "selected_subcenter_count": 0.0,
    }
    try:
        head_input = extract_head_input_from_features(model, features)
    except KeyError:
        return reference.sum() * 0.0, stats
    module = getattr(model, "module", model)
    proxy_fn = getattr(module, "subcenter_proxy_logits_from_head_input", None)
    if not callable(proxy_fn):
        return reference.sum() * 0.0, stats
    proxy_output = proxy_fn(head_input)
    if proxy_output is None:
        return head_input.sum() * 0.0, stats
    proxy_logits, all_scores = proxy_output
    if (
        not torch.is_tensor(proxy_logits)
        or proxy_logits.ndim != 2
        or not torch.is_tensor(all_scores)
        or all_scores.ndim != 3
    ):
        return head_input.sum() * 0.0, stats

    num_classes = int(proxy_logits.size(1))
    target_indices = targets.to(device=proxy_logits.device, dtype=torch.long).view(-1)
    valid = (target_indices >= 0) & (target_indices < num_classes)
    selected_classes = _parse_angular_margin_classes(classes, num_classes=num_classes)
    if selected_classes:
        selected = torch.zeros(num_classes, device=proxy_logits.device, dtype=torch.bool)
        selected[torch.tensor(selected_classes, device=proxy_logits.device, dtype=torch.long)] = True
        valid = valid & selected.index_select(0, target_indices.clamp(0, max(0, num_classes - 1)))
    if not bool(valid.any().item()):
        return head_input.sum() * 0.0, stats

    valid_logits = proxy_logits[valid].clone()
    valid_targets = target_indices[valid]
    rows = torch.arange(valid_targets.numel(), device=valid_logits.device)
    target_scores = valid_logits[rows, valid_targets]
    masked_negative = valid_logits.masked_fill(
        F.one_hot(valid_targets, num_classes=num_classes).to(dtype=torch.bool),
        -1.0e4,
    )
    negative_scores = masked_negative.max(dim=1).values
    valid_logits[rows, valid_targets] = target_scores - float(margin)
    loss = F.cross_entropy(valid_logits * float(scale), valid_targets)

    selected_all_scores = all_scores[valid]
    selected_target_scores = selected_all_scores[
        rows,
        valid_targets,
    ]
    selected_subcenters = selected_target_scores.argmax(dim=1)
    stats = {
        "valid_fraction": float(valid.float().mean().detach().cpu().item()),
        "positive_similarity": float(target_scores.detach().float().mean().cpu().item()),
        "negative_similarity": float(negative_scores.detach().float().mean().cpu().item()),
        "positive_negative_margin": float(
            (target_scores - negative_scores).detach().float().mean().cpu().item()
        ),
        "selected_subcenter_count": float(
            torch.unique(selected_subcenters.detach()).numel()
        ),
    }
    return loss.to(dtype=head_input.dtype), stats


def _deep_abstention_loss(
    *,
    logits: Tensor,
    abstention_logits: Tensor,
    targets: Tensor,
    penalty: float,
    sample_weights: Optional[Tensor] = None,
) -> Tuple[Tensor, Dict[str, float]]:
    if logits.ndim != 2 or abstention_logits.ndim != 1:
        raise ValueError("Deep abstention expects class logits [B,C] and abstention logits [B].")
    if logits.size(0) != abstention_logits.size(0):
        raise ValueError("Deep abstention class/abstention batch sizes differ.")
    target_indices = targets.to(device=logits.device, dtype=torch.long).view(-1)
    if target_indices.numel() != logits.size(0):
        raise ValueError("Deep abstention target batch size differs from logits.")
    if float(penalty) < 0.0:
        raise ValueError("Deep abstention penalty must be non-negative.")

    joint_logits = torch.cat(
        (logits.float(), abstention_logits.float().unsqueeze(1)),
        dim=1,
    )
    joint_log_probabilities = F.log_softmax(joint_logits, dim=1)
    log_non_abstention = torch.logsumexp(joint_log_probabilities[:, :-1], dim=1)
    rows = torch.arange(target_indices.numel(), device=logits.device)
    conditional_target_log_probability = (
        joint_log_probabilities[rows, target_indices] - log_non_abstention
    )
    abstention_probability = joint_log_probabilities[:, -1].exp()
    per_sample = (
        (1.0 - abstention_probability) * (-conditional_target_log_probability)
        + float(penalty) * (-log_non_abstention)
    )
    if sample_weights is not None:
        weights = sample_weights.to(device=logits.device, dtype=per_sample.dtype).view(-1)
        if weights.numel() != per_sample.numel():
            raise ValueError("Deep abstention sample weights have the wrong batch size.")
        loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-6)
    else:
        loss = per_sample.mean()
    predictions = logits.detach().argmax(dim=1)
    stats = {
        "abstention_probability": float(
            abstention_probability.detach().mean().cpu().item()
        ),
        "abstention_probability_max": float(
            abstention_probability.detach().max().cpu().item()
        ),
        "abstention_fraction_010": float(
            (abstention_probability.detach() >= 0.10).float().mean().cpu().item()
        ),
        "conditional_ce": float(
            (-conditional_target_log_probability).detach().mean().cpu().item()
        ),
        "conditional_accuracy": float(
            (predictions == target_indices).float().mean().cpu().item()
        ),
    }
    return loss.to(dtype=logits.dtype), stats


def _initialize_subcenter_proxy_from_classifier(
    model: nn.Module,
    *,
    init_std: float,
    force: bool = False,
) -> Dict[str, object]:
    module = getattr(model, "module", model)
    proxy_head = getattr(module, "subcenter_proxy_head", None)
    if proxy_head is None or not hasattr(proxy_head, "initialize_from_classifier"):
        return {"enabled": False}
    if not force:
        loaded = bool(getattr(proxy_head, "_loaded_from_checkpoint", False))
        if loaded:
            return {"enabled": True, "initialized_from_classifier": False, "reason": "checkpoint_loaded"}
    initialized = bool(
        proxy_head.initialize_from_classifier(
            getattr(module, "head", None),
            noise_std=float(init_std),
        )
    )
    return {
        "enabled": True,
        "initialized_from_classifier": initialized,
        "subcenters": int(getattr(proxy_head, "subcenters", 0) or 0),
        "init_std": float(init_std),
    }


def _parse_ordinal_boundary_threshold_weights(
    weights: Union[str, Sequence[float], None],
    *,
    num_thresholds: int,
    device: torch.device,
) -> Tensor:
    if weights is None:
        values = [1.0]
    elif isinstance(weights, str):
        values = [float(part.strip()) for part in weights.split(",") if part.strip()]
    else:
        values = [float(value) for value in weights]
    if not values:
        values = [1.0]
    if len(values) == 1:
        values = values * int(num_thresholds)
    if len(values) != int(num_thresholds):
        raise ValueError(
            "ordinal boundary threshold weights phai co 1 gia tri hoac bang so nguong."
        )
    return torch.tensor(values, device=device, dtype=torch.float32).clamp_min(0.0)


def _ordinal_boundary_loss_from_logits(
    *,
    logits: Tensor,
    targets: Tensor,
    classes: Union[str, Sequence[int], None] = "0,1,2,3",
    threshold_weights: Union[str, Sequence[float], None] = "1.25,1.25,1.0",
    temperature: float = 1.0,
) -> Tensor:
    if not torch.is_tensor(logits) or logits.ndim != 2:
        return targets.sum() * 0.0
    num_classes = int(logits.size(1))
    ordered_classes = _parse_angular_margin_classes(classes, num_classes=num_classes)
    if len(ordered_classes) < 2:
        return logits.sum() * 0.0

    target_indices = targets.to(device=logits.device, dtype=torch.long).view(-1)
    rank_lookup = torch.full(
        (num_classes,),
        fill_value=-1,
        device=logits.device,
        dtype=torch.long,
    )
    for rank, class_index in enumerate(ordered_classes):
        rank_lookup[int(class_index)] = int(rank)
    valid_class_indices = target_indices.clamp(0, max(0, num_classes - 1))
    target_ranks = rank_lookup.index_select(0, valid_class_indices)
    valid = (target_indices >= 0) & (target_indices < num_classes) & (target_ranks >= 0)
    if not bool(valid.any().item()):
        return logits.sum() * 0.0

    logits_float = logits.float()
    valid_ranks = target_ranks[valid]
    losses: List[Tensor] = []
    for threshold_index in range(len(ordered_classes) - 1):
        left_indices = torch.tensor(
            ordered_classes[: threshold_index + 1],
            device=logits.device,
            dtype=torch.long,
        )
        right_indices = torch.tensor(
            ordered_classes[threshold_index + 1 :],
            device=logits.device,
            dtype=torch.long,
        )
        left_score = torch.logsumexp(logits_float.index_select(1, left_indices), dim=1)
        right_score = torch.logsumexp(logits_float.index_select(1, right_indices), dim=1)
        boundary_logit = (right_score - left_score) / float(max(1e-6, temperature))
        boundary_target = (valid_ranks > int(threshold_index)).to(dtype=boundary_logit.dtype)
        losses.append(
            F.binary_cross_entropy_with_logits(
                boundary_logit[valid],
                boundary_target,
                reduction="none",
            )
        )
    if not losses:
        return logits.sum() * 0.0
    loss_matrix = torch.stack(losses, dim=1)
    weights_tensor = _parse_ordinal_boundary_threshold_weights(
        threshold_weights,
        num_thresholds=loss_matrix.size(1),
        device=logits.device,
    )
    weight_sum = weights_tensor.sum().clamp_min(1e-6)
    ordinal_loss = (loss_matrix * weights_tensor.unsqueeze(0)).sum(dim=1) / weight_sum
    return ordinal_loss.mean().to(dtype=logits.dtype)


def _ordinal_distribution_loss_from_logits(
    *,
    logits: Tensor,
    targets: Tensor,
    classes: Union[str, Sequence[int], None] = "0,1,2,3",
    target_sigma: float = 0.0,
) -> Tensor:
    if not torch.is_tensor(logits) or logits.ndim != 2:
        return targets.sum() * 0.0
    num_classes = int(logits.size(1))
    ordered_classes = _parse_angular_margin_classes(classes, num_classes=num_classes)
    if len(ordered_classes) < 2:
        return logits.sum() * 0.0

    target_indices = targets.to(device=logits.device, dtype=torch.long).view(-1)
    rank_lookup = torch.full(
        (num_classes,),
        fill_value=-1,
        device=logits.device,
        dtype=torch.long,
    )
    for rank, class_index in enumerate(ordered_classes):
        rank_lookup[int(class_index)] = int(rank)
    valid_class_indices = target_indices.clamp(0, max(0, num_classes - 1))
    target_ranks = rank_lookup.index_select(0, valid_class_indices)
    valid = (target_indices >= 0) & (target_indices < num_classes) & (target_ranks >= 0)
    if not bool(valid.any().item()):
        return logits.sum() * 0.0

    class_index_tensor = torch.tensor(ordered_classes, device=logits.device, dtype=torch.long)
    ordinal_logits = logits.float().index_select(1, class_index_tensor)
    ordinal_probs = F.softmax(ordinal_logits[valid], dim=1)
    valid_ranks = target_ranks[valid]
    class_count = int(len(ordered_classes))
    rank_grid = torch.arange(class_count, device=logits.device, dtype=torch.float32)
    if float(target_sigma) > 0.0:
        sigma = max(float(target_sigma), 1e-6)
        distances = rank_grid.unsqueeze(0) - valid_ranks.to(dtype=torch.float32).unsqueeze(1)
        target_distribution = torch.exp(-0.5 * (distances / sigma).pow(2))
        target_distribution = target_distribution / target_distribution.sum(dim=1, keepdim=True).clamp_min(1e-8)
    else:
        target_distribution = F.one_hot(valid_ranks, num_classes=class_count).to(dtype=torch.float32)

    pred_cdf = ordinal_probs.cumsum(dim=1)
    target_cdf = target_distribution.cumsum(dim=1)
    # The final CDF entry is always one for both distributions, so omit it.
    emd_terms = (pred_cdf[:, :-1] - target_cdf[:, :-1]).pow(2)
    return emd_terms.mean().to(dtype=logits.dtype)


def _complement_entropy_loss_from_logits(
    *,
    logits: Tensor,
    targets: Tensor,
    classes: Union[str, Sequence[int], None] = "all",
) -> Tensor:
    if not torch.is_tensor(logits) or logits.ndim != 2:
        return targets.sum() * 0.0
    num_classes = int(logits.size(1))
    if num_classes <= 2:
        return logits.sum() * 0.0

    target_indices = targets.to(device=logits.device, dtype=torch.long).view(-1)
    valid = (target_indices >= 0) & (target_indices < num_classes)
    selected_classes = _parse_angular_margin_classes(classes, num_classes=num_classes)
    if selected_classes:
        selected = torch.zeros(num_classes, device=logits.device, dtype=torch.bool)
        selected[torch.tensor(selected_classes, device=logits.device, dtype=torch.long)] = True
        valid = valid & selected.index_select(0, target_indices.clamp(0, max(0, num_classes - 1)))
    if not bool(valid.any().item()):
        return logits.sum() * 0.0

    valid_logits = logits.float()[valid]
    valid_targets = target_indices[valid]
    probabilities = F.softmax(valid_logits, dim=1)
    target_mask = F.one_hot(valid_targets, num_classes=num_classes).to(dtype=torch.bool)
    complement_probabilities = probabilities.masked_fill(target_mask, 0.0)
    complement_mass = complement_probabilities.sum(dim=1, keepdim=True).clamp_min(1e-7)
    complement_probabilities = complement_probabilities / complement_mass
    complement_entropy = -(
        complement_probabilities
        * complement_probabilities.clamp_min(1e-8).log()
    ).sum(dim=1)
    max_entropy = math.log(float(num_classes - 1))
    complement_collapse = 1.0 - (complement_entropy / max_entropy)
    return complement_collapse.clamp_min(0.0).mean().to(dtype=logits.dtype)


def _parse_pairwise_confusion_sources(sources: Union[str, Sequence[str]]) -> List[str]:
    if isinstance(sources, str):
        requested = [part.strip().lower() for part in sources.split(",") if part.strip()]
    else:
        requested = [str(part).strip().lower() for part in sources if str(part).strip()]
    if not requested:
        requested = ["head"]
    if "all" in requested:
        requested = ["head", "patch", "registers", "logits"]
    parsed: List[str] = []
    for source in requested:
        if source not in {"head", "patch", "registers", "logits"}:
            raise ValueError(f"pairwise confusion source khong hop le: {source}")
        if source not in parsed:
            parsed.append(source)
    return parsed


def _pairwise_confusion_loss_from_features(
    *,
    model: nn.Module,
    features: Optional[Dict[str, Tensor]],
    logits: Optional[Tensor],
    sources: Union[str, Sequence[str]] = "head",
    normalize: bool = True,
) -> Tensor:
    reference = logits
    if features:
        reference = next((value for value in features.values() if torch.is_tensor(value)), reference)
    if reference is None:
        return torch.tensor(0.0)

    embeddings: List[Tensor] = []
    requested_sources = _parse_pairwise_confusion_sources(sources)
    if features is not None and "head" in requested_sources:
        try:
            head_input = extract_head_input_from_features(model, features)
            if torch.is_tensor(head_input) and head_input.ndim == 2:
                embeddings.append(head_input)
        except KeyError:
            pass
    if features is not None and "patch" in requested_sources:
        patches = features.get("patches")
        if torch.is_tensor(patches) and patches.ndim == 3:
            key_padding_mask = features.get("memory_key_padding_mask")
            if torch.is_tensor(key_padding_mask) and key_padding_mask.shape[:2] == patches.shape[:2]:
                valid = (~key_padding_mask.to(device=patches.device, dtype=torch.bool)).unsqueeze(-1)
                denom = valid.sum(dim=1).clamp_min(1).to(dtype=patches.dtype)
                patch_embedding = (patches * valid.to(dtype=patches.dtype)).sum(dim=1) / denom
            else:
                patch_embedding = patches.mean(dim=1)
            embeddings.append(patch_embedding)
    if features is not None and "registers" in requested_sources:
        registers = features.get("registers")
        if torch.is_tensor(registers) and registers.ndim == 3 and int(registers.size(1)) > 0:
            embeddings.append(registers.mean(dim=1))
    if logits is not None and "logits" in requested_sources:
        embeddings.append(logits)

    losses: List[Tensor] = []
    for embedding in embeddings:
        if not torch.is_tensor(embedding) or embedding.ndim != 2 or int(embedding.size(0)) < 2:
            continue
        even_count = int(embedding.size(0)) - (int(embedding.size(0)) % 2)
        if even_count < 2:
            continue
        embedding_float = embedding[:even_count].float()
        if normalize:
            embedding_float = F.normalize(embedding_float, dim=1, eps=1e-6)
        half = even_count // 2
        distance = torch.linalg.vector_norm(
            embedding_float[:half] - embedding_float[half:even_count],
            ord=2,
            dim=1,
        )
        losses.append(distance.mean())
    if not losses:
        return reference.sum() * 0.0
    return torch.stack(losses).mean().to(dtype=reference.dtype)


def _mutual_channel_loss_from_features(
    *,
    features: Optional[Dict[str, Tensor]],
    targets: Tensor,
    num_classes: int,
    top_k: int = 8,
    diversity_weight: float = 0.20,
) -> Tensor:
    reference = targets
    if features:
        reference = next((value for value in features.values() if torch.is_tensor(value)), targets)
    stem = features.get("stem_features") if isinstance(features, dict) else None
    if not torch.is_tensor(stem) or stem.ndim != 4 or int(stem.size(0)) == 0:
        return reference.float().sum() * 0.0 if torch.is_tensor(reference) else torch.tensor(0.0)

    batch_size, channels, height, width = [int(value) for value in stem.shape]
    if batch_size != int(targets.numel()) or channels < int(num_classes) or int(num_classes) <= 1:
        return stem.sum() * 0.0
    target_indices = targets.to(device=stem.device, dtype=torch.long).view(-1)
    valid = (target_indices >= 0) & (target_indices < int(num_classes))
    if not bool(valid.any().item()):
        return stem.sum() * 0.0

    activations = F.relu(stem.float())
    channel_strength = activations.flatten(2).mean(dim=2)
    channel_indices = torch.arange(channels, device=stem.device)
    class_groups = torch.chunk(channel_indices, int(num_classes))
    group_scores: List[Tensor] = []
    k = max(1, int(top_k))
    for group in class_groups:
        group_values = channel_strength.index_select(1, group)
        selected_count = min(k, int(group_values.size(1)))
        selected = torch.topk(group_values, k=selected_count, dim=1, largest=True, sorted=False).values
        group_scores.append(torch.log(selected.mean(dim=1).clamp_min(1e-6)))
    score_logits = torch.stack(group_scores, dim=1)
    discriminability_loss = F.cross_entropy(
        score_logits[valid],
        target_indices[valid],
    )

    diversity_terms: List[Tensor] = []
    flat_activations = activations.flatten(2)
    for sample_index in torch.nonzero(valid, as_tuple=False).flatten():
        class_index = int(target_indices[sample_index].detach().cpu().item())
        group = class_groups[class_index]
        if int(group.numel()) < 2:
            continue
        sample_strength = channel_strength[sample_index].index_select(0, group)
        selected_count = min(k, int(group.numel()))
        selected_local = torch.topk(
            sample_strength,
            k=selected_count,
            largest=True,
            sorted=False,
        ).indices
        selected_channels = group.index_select(0, selected_local)
        maps = flat_activations[sample_index].index_select(0, selected_channels)
        maps = F.normalize(maps, dim=1, eps=1e-6)
        similarity = torch.matmul(maps, maps.T).pow(2)
        off_diagonal = ~torch.eye(
            int(similarity.size(0)),
            device=similarity.device,
            dtype=torch.bool,
        )
        if bool(off_diagonal.any().item()):
            diversity_terms.append(similarity[off_diagonal].mean())
    if diversity_terms:
        diversity_loss = torch.stack(diversity_terms).mean()
    else:
        diversity_loss = stem.sum() * 0.0
    return (
        discriminability_loss + float(diversity_weight) * diversity_loss
    ).to(dtype=stem.dtype)


def _build_pretrained_distillation_teacher(
    *,
    checkpoint_path: Path,
    target_class_names: Sequence[str],
    device: torch.device,
) -> Tuple[nn.Module, Tensor, Dict[str, object]]:
    checkpoint = torch.load(checkpoint_path, map_location="cpu", weights_only=False)
    if not isinstance(checkpoint, dict):
        raise ValueError(f"Teacher checkpoint khong hop le: {checkpoint_path}")
    is_trkh_checkpoint = isinstance(checkpoint.get("model_config"), dict) and isinstance(
        checkpoint.get("model_state"), dict
    )
    if is_trkh_checkpoint:
        teacher_classes = [
            str(value) for value in checkpoint.get("class_names", [])
        ]
        if not teacher_classes:
            raise ValueError(
                "TRKH teacher checkpoint must record non-empty class_names."
            )
        teacher_model_name = str(
            checkpoint.get("model_config", {}).get("model_type", "vit_registers")
        )
        teacher = build_model_from_checkpoint(
            dict(checkpoint),
            num_classes=len(teacher_classes),
        )
        teacher_backend = "trkh"
    else:
        try:
            import timm
        except ImportError as exc:  # pragma: no cover - environment dependent.
            raise RuntimeError(
                "TIMM distillation teacher yeu cau package timm."
            ) from exc
        teacher_args = checkpoint.get("args", {})
        teacher_classes = [str(value) for value in checkpoint.get("classes", [])]
        teacher_model_name = str(
            teacher_args.get("model", "")
            if isinstance(teacher_args, dict)
            else ""
        ).strip()
        teacher_state = checkpoint.get("model")
        if not teacher_model_name or not isinstance(teacher_state, dict):
            raise ValueError(
                "Teacher checkpoint phai la TRKH model_state/model_config hoac "
                "baseline TIMM args.model/model."
            )
        teacher = timm.create_model(
            teacher_model_name,
            pretrained=False,
            num_classes=len(teacher_classes),
        )
        teacher.load_state_dict(teacher_state, strict=True)
        teacher_backend = "timm"
    missing_classes = sorted(set(target_class_names) - set(teacher_classes))
    if missing_classes or len(teacher_classes) != len(target_class_names):
        raise ValueError(
            "Teacher class names khong khop dataset: "
            f"teacher={teacher_classes} target={list(target_class_names)}"
        )
    teacher_total_parameters = sum(
        int(parameter.numel()) for parameter in teacher.parameters()
    )
    teacher.eval().requires_grad_(False).to(device)
    target_to_teacher = torch.tensor(
        [teacher_classes.index(str(class_name)) for class_name in target_class_names],
        dtype=torch.long,
        device=device,
    )
    summary = {
        "enabled": True,
        "checkpoint": str(Path(checkpoint_path).resolve()),
        "backend": teacher_backend,
        "model": teacher_model_name,
        "teacher_classes": teacher_classes,
        "target_classes": list(target_class_names),
        "target_to_teacher_indices": target_to_teacher.detach().cpu().tolist(),
        "parameter_count": teacher_total_parameters,
        "trainable_parameters": sum(
            int(parameter.numel())
            for parameter in teacher.parameters()
            if parameter.requires_grad
        ),
    }
    return teacher, target_to_teacher, summary


def _load_offline_distillation_probabilities(
    *,
    csv_path: Path,
    num_classes: int,
    class_names: Sequence[str],
) -> Tuple[Dict[str, List[float]], Dict[int, List[float]], Dict[str, object]]:
    csv_path = Path(csv_path)
    if not csv_path.is_file():
        raise FileNotFoundError(f"Khong tim thay teacher probability CSV: {csv_path}")
    probabilities_by_path: Dict[str, List[float]] = {}
    probabilities_by_sample_index: Dict[int, List[float]] = {}
    confidence_sum = 0.0
    pred_counts = [0 for _ in range(max(1, int(num_classes)))]
    duplicate_count = 0
    duplicate_sample_index_count = 0
    row_count = 0
    with csv_path.open("r", newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames is None:
            raise ValueError(f"Teacher probability CSV rong: {csv_path}")
        has_sample_index = "sample_index" in reader.fieldnames
        required = {"path", *[f"prob_{index}" for index in range(int(num_classes))]}
        missing = required.difference(reader.fieldnames)
        if missing:
            raise ValueError(
                f"Teacher probability CSV thieu cot {sorted(missing)}: {csv_path}"
            )
        for row in reader:
            path_text = str(row.get("path", "") or "").strip()
            if not path_text:
                continue
            values = [float(row[f"prob_{index}"]) for index in range(int(num_classes))]
            probabilities = torch.tensor(values, dtype=torch.float32).clamp(min=0.0)
            total = probabilities.sum().clamp(min=1e-12)
            probabilities = probabilities / total
            if not torch.isfinite(probabilities).all():
                raise ValueError(f"Teacher probability CSV co prob khong huu han: {path_text}")
            key = str(Path(path_text).resolve()).lower()
            if key in probabilities_by_path:
                duplicate_count += 1
            probability_values = [float(value) for value in probabilities.tolist()]
            probabilities_by_path[key] = probability_values
            if has_sample_index:
                sample_index_text = str(row.get("sample_index", "") or "").strip()
                if sample_index_text:
                    sample_index = int(sample_index_text)
                    if sample_index < 0:
                        raise ValueError(
                            f"Teacher probability CSV co sample_index am: {sample_index_text}"
                        )
                    if sample_index in probabilities_by_sample_index:
                        duplicate_sample_index_count += 1
                    probabilities_by_sample_index[sample_index] = probability_values
            pred_index = int(probabilities.argmax().item())
            if 0 <= pred_index < len(pred_counts):
                pred_counts[pred_index] += 1
            confidence_sum += float(probabilities.max().item())
            row_count += 1
    if not probabilities_by_path:
        raise ValueError(f"Teacher probability CSV khong co dong hop le: {csv_path}")
    sample_count = (
        len(probabilities_by_sample_index)
        if probabilities_by_sample_index
        else len(probabilities_by_path)
    )
    summary = {
        "enabled": True,
        "csv": str(csv_path.resolve()),
        "samples": sample_count,
        "rows": row_count,
        "path_samples": len(probabilities_by_path),
        "sample_index_samples": len(probabilities_by_sample_index),
        "key_mode": "sample_index" if probabilities_by_sample_index else "path",
        "duplicate_rows": duplicate_count,
        "duplicate_sample_index_rows": duplicate_sample_index_count,
        "num_classes": int(num_classes),
        "class_names": list(class_names),
        "mean_confidence": float(confidence_sum / max(1, row_count)),
        "predicted_class_counts": pred_counts,
    }
    return probabilities_by_path, probabilities_by_sample_index, summary


def _npz_string_array(values: object) -> List[str]:
    array = np.asarray(values)
    return [str(value) for value in array.reshape(-1).tolist()]


def _load_teacher_feature_npz(
    *,
    npz_path: Path,
) -> Tuple[Dict[str, List[float]], Dict[int, List[float]], Dict[str, object]]:
    npz_path = Path(npz_path)
    if not npz_path.is_file():
        raise FileNotFoundError(f"Khong tim thay teacher feature NPZ: {npz_path}")
    with np.load(npz_path, allow_pickle=True) as data:
        if "features" not in data:
            raise ValueError(f"Teacher feature NPZ thieu mang 'features': {npz_path}")
        features = np.asarray(data["features"], dtype=np.float32)
        if features.ndim != 2 or features.shape[0] <= 0 or features.shape[1] <= 0:
            raise ValueError(
                f"Teacher feature NPZ features phai co shape [N, D], got {features.shape}: {npz_path}"
            )
        if not np.isfinite(features).all():
            raise ValueError(f"Teacher feature NPZ co feature khong huu han: {npz_path}")

        sample_indices_array = None
        for name in ("sample_index", "sample_indices", "dataset_index", "dataset_indices"):
            if name in data:
                sample_indices_array = np.asarray(data[name]).reshape(-1)
                break
        paths: List[str] = []
        for name in ("paths", "path", "image_paths", "image_path"):
            if name in data:
                paths = _npz_string_array(data[name])
                break
        labels = None
        for name in ("labels", "label", "y_true", "targets"):
            if name in data:
                labels = np.asarray(data[name]).reshape(-1)
                break

    row_count = int(features.shape[0])
    if sample_indices_array is not None and int(sample_indices_array.shape[0]) != row_count:
        raise ValueError(
            f"Teacher feature NPZ sample_index length khong khop features: "
            f"{sample_indices_array.shape[0]} != {row_count}"
        )
    if paths and len(paths) != row_count:
        raise ValueError(
            f"Teacher feature NPZ paths length khong khop features: {len(paths)} != {row_count}"
        )
    if labels is not None and int(labels.shape[0]) != row_count:
        raise ValueError(
            f"Teacher feature NPZ labels length khong khop features: {labels.shape[0]} != {row_count}"
        )

    features_by_path: Dict[str, List[float]] = {}
    features_by_sample_index: Dict[int, List[float]] = {}
    duplicate_path_rows = 0
    duplicate_sample_index_rows = 0
    invalid_sample_index_rows = 0
    for row_index in range(row_count):
        feature_values = [float(value) for value in features[row_index].tolist()]
        if sample_indices_array is not None:
            try:
                sample_index = int(sample_indices_array[row_index])
            except (TypeError, ValueError):
                invalid_sample_index_rows += 1
                continue
            if sample_index < 0:
                invalid_sample_index_rows += 1
                continue
            if sample_index in features_by_sample_index:
                duplicate_sample_index_rows += 1
            features_by_sample_index[sample_index] = feature_values
        elif paths:
            key = str(Path(paths[row_index]).resolve()).lower()
            if key in features_by_path:
                duplicate_path_rows += 1
            features_by_path[key] = feature_values

    if not features_by_sample_index and not features_by_path:
        raise ValueError(f"Teacher feature NPZ khong co key sample_index/path hop le: {npz_path}")

    norms = np.linalg.norm(features.astype(np.float32), axis=1)
    summary = {
        "enabled": True,
        "npz": str(npz_path.resolve()),
        "rows": row_count,
        "samples": int(len(features_by_sample_index) if features_by_sample_index else len(features_by_path)),
        "feature_dim": int(features.shape[1]),
        "path_samples": int(len(features_by_path)),
        "sample_index_samples": int(len(features_by_sample_index)),
        "key_mode": "sample_index" if features_by_sample_index else "path",
        "duplicate_path_rows": int(duplicate_path_rows),
        "duplicate_sample_index_rows": int(duplicate_sample_index_rows),
        "invalid_sample_index_rows": int(invalid_sample_index_rows),
        "mean_norm": float(np.mean(norms)) if norms.size else 0.0,
        "std_norm": float(np.std(norms)) if norms.size else 0.0,
        "has_labels": bool(labels is not None),
        "has_paths": bool(paths),
    }
    return features_by_path, features_by_sample_index, summary


def _distillation_loss(
    *,
    student_logits: Tensor,
    teacher_logits: Tensor,
    targets,
    temperature: float,
    focus_class_index: int,
    focus_class_weight: float,
) -> Tensor:
    temperature = max(1e-4, float(temperature))
    teacher_probabilities = F.softmax(
        teacher_logits.float() / temperature,
        dim=1,
    )
    student_log_probabilities = F.log_softmax(
        student_logits.float() / temperature,
        dim=1,
    )
    teacher_log_probabilities = torch.log(
        teacher_probabilities.clamp(min=1e-8)
    )
    per_sample = (
        teacher_probabilities
        * (teacher_log_probabilities - student_log_probabilities)
    ).sum(dim=1)
    target_indices = _classification_target_indices(targets, student_logits)
    if (
        target_indices is not None
        and 0 <= int(focus_class_index) < int(student_logits.size(1))
        and float(focus_class_weight) != 1.0
    ):
        sample_weights = torch.ones_like(per_sample)
        sample_weights[target_indices == int(focus_class_index)] = float(
            focus_class_weight
        )
        per_sample = per_sample * sample_weights
        loss = per_sample.sum() / sample_weights.sum().clamp(min=1.0)
    else:
        loss = per_sample.mean()
    return loss.to(dtype=student_logits.dtype) * (temperature * temperature)


def _probability_distillation_loss(
    *,
    student_logits: Tensor,
    teacher_probabilities: Tensor,
    targets,
    temperature: float,
    focus_class_index: int,
    focus_class_weight: float,
) -> Tensor:
    temperature = max(1e-4, float(temperature))
    teacher_probabilities = teacher_probabilities.to(
        device=student_logits.device,
        dtype=torch.float32,
    ).clamp(min=0.0)
    teacher_probabilities = teacher_probabilities / teacher_probabilities.sum(
        dim=1,
        keepdim=True,
    ).clamp(min=1e-12)
    student_log_probabilities = F.log_softmax(
        student_logits.float() / temperature,
        dim=1,
    )
    teacher_log_probabilities = torch.log(
        teacher_probabilities.clamp(min=1e-8)
    )
    per_sample = (
        teacher_probabilities
        * (teacher_log_probabilities - student_log_probabilities)
    ).sum(dim=1)
    target_indices = _classification_target_indices(targets, student_logits)
    if (
        target_indices is not None
        and 0 <= int(focus_class_index) < int(student_logits.size(1))
        and float(focus_class_weight) != 1.0
    ):
        sample_weights = torch.ones_like(per_sample)
        sample_weights[target_indices == int(focus_class_index)] = float(
            focus_class_weight
        )
        per_sample = per_sample * sample_weights
        loss = per_sample.sum() / sample_weights.sum().clamp(min=1.0)
    else:
        loss = per_sample.mean()
    return loss.to(dtype=student_logits.dtype) * (temperature * temperature)


def _teacher_non_target_distillation_loss_from_logits(
    *,
    logits: Tensor,
    teacher_probabilities: Optional[Tensor],
    hard_labels: Optional[Tensor],
    targets,
    classes: Union[str, Sequence[int]],
    temperature: float,
    teacher_min_confidence: float,
    require_agreement: bool,
) -> Tuple[Tensor, float, Tensor]:
    zero = logits.sum() * 0.0
    if (
        teacher_probabilities is None
        or not torch.is_tensor(teacher_probabilities)
        or logits.ndim != 2
        or logits.size(0) == 0
    ):
        return zero, 0.0, zero.detach()
    if teacher_probabilities.ndim != 2 or teacher_probabilities.size(0) != logits.size(0):
        return zero, 0.0, zero.detach()

    num_classes = int(logits.size(1))
    if int(teacher_probabilities.size(1)) != num_classes:
        return zero, 0.0, zero.detach()
    candidate_classes = _parse_angular_margin_classes(
        classes,
        num_classes=num_classes,
    )
    if len(candidate_classes) < 2:
        return zero, 0.0, zero.detach()

    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, logits)
    if target_indices is None or target_indices.numel() != logits.size(0):
        return zero, 0.0, zero.detach()

    teacher_probs = teacher_probabilities.to(device=logits.device, dtype=torch.float32).clamp(min=0.0)
    teacher_probs = teacher_probs / teacher_probs.sum(dim=1, keepdim=True).clamp(min=1e-12)
    teacher_confidence, teacher_predictions = teacher_probs.max(dim=1)
    class_tensor = torch.tensor(candidate_classes, device=logits.device, dtype=torch.long)
    candidate_mask_1d = torch.zeros(num_classes, device=logits.device, dtype=torch.bool)
    candidate_mask_1d[class_tensor] = True
    candidate_mask = candidate_mask_1d.unsqueeze(0).expand(logits.size(0), -1)

    safe_targets = target_indices.clamp(min=0, max=max(0, num_classes - 1))
    target_mask = F.one_hot(safe_targets, num_classes=num_classes).to(dtype=torch.bool)
    non_target_mask = candidate_mask & (~target_mask)
    non_target_count = non_target_mask.sum(dim=1)
    valid = (
        (target_indices >= 0)
        & (target_indices < num_classes)
        & candidate_mask_1d.index_select(0, safe_targets)
        & (non_target_count >= 2)
    )
    if bool(require_agreement):
        valid = valid & (teacher_predictions == target_indices)
    if float(teacher_min_confidence) > 0.0:
        valid = valid & (teacher_confidence >= float(teacher_min_confidence))

    teacher_non_target = teacher_probs.masked_fill(~non_target_mask, 0.0)
    teacher_mass = teacher_non_target.sum(dim=1, keepdim=True)
    valid = valid & (teacher_mass.squeeze(1) > 1e-8)
    if not bool(valid.any().item()):
        return zero, 0.0, zero.detach()

    teacher_non_target = teacher_non_target / teacher_mass.clamp(min=1e-12)
    scaled_logits = logits.float() / max(1e-4, float(temperature))
    student_non_target_log_probs = F.log_softmax(
        scaled_logits.masked_fill(~non_target_mask, -1e9),
        dim=1,
    )
    teacher_log_probs = torch.log(teacher_non_target.clamp(min=1e-8))
    per_sample = (
        teacher_non_target
        * (teacher_log_probs - student_non_target_log_probs)
    ).sum(dim=1)
    valid_loss = per_sample[valid].mean() * (max(1e-4, float(temperature)) ** 2)
    fraction = float(valid.float().mean().detach().cpu().item())
    mean_confidence = teacher_confidence[valid].detach().mean().to(dtype=logits.dtype)
    return valid_loss.to(dtype=logits.dtype), fraction, mean_confidence


def _early_learning_regularization_loss(
    logits: Tensor,
    sample_indices: Optional[Tensor],
    target_state: Optional[Tensor],
    *,
    beta: float,
    update_state: bool = True,
) -> Tensor:
    zero = logits.sum() * 0.0
    if (
        target_state is None
        or sample_indices is None
        or not torch.is_tensor(sample_indices)
        or logits.ndim != 2
        or target_state.ndim != 2
        or target_state.size(1) != logits.size(1)
    ):
        return zero
    flat_indices = sample_indices.to(device=target_state.device, dtype=torch.long).view(-1)
    if flat_indices.numel() != logits.size(0):
        return zero
    valid_mask = (flat_indices >= 0) & (flat_indices < int(target_state.size(0)))
    if not bool(valid_mask.any().item()):
        return zero
    valid_indices = flat_indices[valid_mask]
    valid_logits = logits[valid_mask.to(device=logits.device)]
    with torch.no_grad():
        probabilities = F.softmax(valid_logits.detach().float(), dim=1).to(
            device=target_state.device,
            dtype=target_state.dtype,
        )
        previous = target_state.index_select(0, valid_indices)
        updated = float(beta) * previous + (1.0 - float(beta)) * probabilities
        updated = updated / updated.sum(dim=1, keepdim=True).clamp(min=1e-12)
        if update_state:
            target_state.index_copy_(0, valid_indices, updated)
        target = updated.detach().to(device=logits.device, dtype=torch.float32)
    student_probabilities = F.softmax(valid_logits.float(), dim=1)
    agreement = (student_probabilities * target).sum(dim=1).clamp(min=1e-6, max=1.0 - 1e-6)
    return torch.log1p(-agreement).mean().to(dtype=logits.dtype)


def _initialize_self_adaptive_target_state(
    labels: Sequence[int],
    *,
    num_classes: int,
    device: torch.device,
) -> Tensor:
    if int(num_classes) <= 0:
        raise ValueError("num_classes phai > 0 cho Self-Adaptive Target.")
    state = torch.zeros((len(labels), int(num_classes)), device=device, dtype=torch.float32)
    if not labels:
        return state
    label_tensor = torch.as_tensor(labels, device=device, dtype=torch.long).view(-1)
    valid = (label_tensor >= 0) & (label_tensor < int(num_classes))
    if bool(valid.any().item()):
        rows = torch.arange(label_tensor.numel(), device=device, dtype=torch.long)[valid]
        state[rows, label_tensor[valid]] = 1.0
    return state


def _self_adaptive_target_loss(
    logits: Tensor,
    targets,
    sample_indices: Optional[Tensor],
    target_state: Optional[Tensor],
    *,
    beta: float,
    hard_target_weight: float,
    confidence_power: float,
    min_confidence: float,
    update_state: bool = True,
) -> Tuple[Tensor, Dict[str, float]]:
    zero = logits.sum() * 0.0
    stats = {
        "fraction": 0.0,
        "confidence": 0.0,
        "hard_agreement": 0.0,
    }
    if (
        target_state is None
        or sample_indices is None
        or not torch.is_tensor(sample_indices)
        or logits.ndim != 2
        or target_state.ndim != 2
        or target_state.size(1) != logits.size(1)
    ):
        return zero, stats
    target_indices = _classification_target_indices(targets, logits)
    if target_indices is None or target_indices.numel() != logits.size(0):
        return zero, stats
    flat_indices = sample_indices.to(device=target_state.device, dtype=torch.long).view(-1)
    if flat_indices.numel() != logits.size(0):
        return zero, stats
    valid = (
        (flat_indices >= 0)
        & (flat_indices < int(target_state.size(0)))
        & (target_indices.to(device=flat_indices.device) >= 0)
        & (target_indices.to(device=flat_indices.device) < logits.size(1))
    )
    if not bool(valid.any().item()):
        return zero, stats

    valid_indices = flat_indices[valid]
    valid_logits = logits[valid.to(device=logits.device)]
    hard_targets = target_indices[valid.to(device=target_indices.device)].to(
        device=logits.device,
        dtype=torch.long,
    )
    hard_probs = F.one_hot(hard_targets, num_classes=logits.size(1)).to(dtype=torch.float32)

    with torch.no_grad():
        probabilities = F.softmax(valid_logits.detach().float(), dim=1)
        previous = target_state.index_select(0, valid_indices).to(
            device=logits.device,
            dtype=torch.float32,
        )
        previous_mass = previous.sum(dim=1, keepdim=True)
        previous = torch.where(previous_mass > 1e-8, previous / previous_mass.clamp(min=1e-12), hard_probs)
        adaptive = float(beta) * previous + (1.0 - float(beta)) * probabilities
        hard_weight = float(min(max(hard_target_weight, 0.0), 1.0))
        if hard_weight > 0.0:
            adaptive = (1.0 - hard_weight) * adaptive + hard_weight * hard_probs
        adaptive = adaptive / adaptive.sum(dim=1, keepdim=True).clamp(min=1e-12)
        if update_state:
            target_state.index_copy_(
                0,
                valid_indices,
                adaptive.to(device=target_state.device, dtype=target_state.dtype),
            )
        adaptive_target = adaptive.detach()

    confidence, adaptive_predictions = adaptive_target.max(dim=1)
    selected = confidence >= float(min_confidence)
    if not bool(selected.any().item()):
        return zero, stats
    log_probs = F.log_softmax(valid_logits.float(), dim=1)
    per_sample = -(adaptive_target * log_probs).sum(dim=1)
    if float(confidence_power) > 0.0:
        weights = confidence.clamp(min=1e-6).pow(float(confidence_power))
    else:
        weights = torch.ones_like(confidence)
    weights = weights * selected.to(dtype=weights.dtype)
    loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
    selected_confidence = confidence[selected]
    selected_agreement = (adaptive_predictions[selected] == hard_targets[selected]).float()
    stats = {
        "fraction": float(selected.float().mean().detach().cpu().item()),
        "confidence": float(selected_confidence.detach().mean().cpu().item()),
        "hard_agreement": float(selected_agreement.detach().mean().cpu().item()),
    }
    return loss.to(dtype=logits.dtype), stats


def _classification_per_sample_loss(
    criterion: nn.Module,
    logits: Tensor,
    targets,
) -> Optional[Tensor]:
    per_sample_loss_fn = getattr(criterion, "per_sample_loss", None)
    if callable(per_sample_loss_fn):
        return per_sample_loss_fn(logits, targets)
    elif isinstance(criterion, nn.CrossEntropyLoss) and torch.is_tensor(targets):
        ce_weight = criterion.weight
        if torch.is_tensor(ce_weight):
            ce_weight = ce_weight.to(device=logits.device, dtype=logits.dtype)
        return F.cross_entropy(
            logits,
            targets.to(device=logits.device, dtype=torch.long),
            weight=ce_weight,
            ignore_index=criterion.ignore_index,
            reduction="none",
            label_smoothing=float(getattr(criterion, "label_smoothing", 0.0) or 0.0),
        )
    return None


def _classification_loss_with_sample_weights(
    criterion: nn.Module,
    logits: Tensor,
    targets,
    sample_weights: Optional[Tensor],
) -> Tuple[Tensor, Tensor, Optional[Tensor]]:
    per_sample = _classification_per_sample_loss(criterion, logits, targets)
    if sample_weights is None or not torch.is_tensor(sample_weights):
        return criterion(logits, targets), logits.new_tensor(1.0), per_sample
    weights = sample_weights.to(device=logits.device, dtype=logits.dtype).view(-1)
    if weights.numel() != logits.size(0):
        return criterion(logits, targets), logits.new_tensor(1.0), per_sample
    weights = weights.clamp(min=0.0)
    if float(weights.sum().detach().cpu().item()) <= 0.0:
        return criterion(logits, targets), logits.new_tensor(0.0), per_sample

    if per_sample is None:
        return criterion(logits, targets), weights.mean().detach(), per_sample
    if per_sample.ndim != 1 or per_sample.numel() != weights.numel():
        return criterion(logits, targets), weights.mean().detach(), per_sample
    weighted_loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
    return weighted_loss.to(dtype=logits.dtype), weights.mean().detach(), per_sample


def _self_paced_classification_loss_from_per_sample(
    per_sample: Tensor,
    sample_weights: Optional[Tensor] = None,
    target_indices: Optional[Tensor] = None,
    *,
    percentile: float = 0.80,
    gamma: float = 1.0,
    min_weight: float = 0.35,
    class_balanced: bool = False,
) -> Tuple[Tensor, Dict[str, Tensor]]:
    if not torch.is_tensor(per_sample) or per_sample.ndim != 1 or per_sample.numel() == 0:
        reference = per_sample if torch.is_tensor(per_sample) else torch.tensor(0.0)
        zero = reference.sum() * 0.0
        stats = {
            "raw_loss": zero.detach(),
            "threshold": zero.detach(),
            "weight_mean": zero.detach(),
            "selected_fraction": zero.detach(),
            "high_loss_weight_mean": zero.detach(),
            "normalized_loss": zero.detach(),
            "class_count": zero.detach(),
        }
        return zero, stats

    losses = per_sample.float().view(-1)
    valid = torch.isfinite(losses)
    if torch.is_tensor(sample_weights):
        base_weights = sample_weights.to(device=losses.device, dtype=losses.dtype).view(-1)
        if base_weights.numel() != losses.numel():
            base_weights = torch.ones_like(losses)
        else:
            base_weights = base_weights.clamp(min=0.0)
    else:
        base_weights = torch.ones_like(losses)
    valid = valid & (base_weights > 0.0)
    if not bool(valid.any().item()):
        zero = losses.sum() * 0.0
        stats = {
            "raw_loss": zero.detach(),
            "threshold": zero.detach(),
            "weight_mean": zero.detach(),
            "selected_fraction": zero.detach(),
            "high_loss_weight_mean": zero.detach(),
            "normalized_loss": zero.detach(),
            "class_count": zero.detach(),
        }
        return zero.to(dtype=per_sample.dtype), stats

    q = min(max(float(percentile), 0.0), 1.0)
    detached_losses = losses.detach().clamp(min=1e-8)
    selection_scores = detached_losses
    threshold_per_sample = torch.empty_like(losses)
    threshold = torch.quantile(detached_losses[valid], q).clamp(min=1e-8)
    threshold_per_sample.fill_(threshold)
    normalized_loss = losses.new_tensor(0.0)
    class_count = losses.new_tensor(0.0)
    if bool(class_balanced) and torch.is_tensor(target_indices):
        labels = target_indices.to(device=losses.device, dtype=torch.long).view(-1)
        if labels.numel() == losses.numel():
            class_valid = valid & (labels >= 0)
            if bool(class_valid.any().item()):
                class_selection_scores = torch.zeros_like(losses)
                class_thresholds = torch.zeros_like(losses)
                threshold_values: List[Tensor] = []
                unique_labels = torch.unique(labels[class_valid].detach()).cpu().tolist()
                for class_index in unique_labels:
                    class_mask = class_valid & (labels == int(class_index))
                    class_losses = detached_losses[class_mask]
                    if class_losses.numel() == 0:
                        continue
                    class_min = class_losses.min()
                    class_max = class_losses.max()
                    class_scores = (class_losses - class_min) / (class_max - class_min).clamp(min=1e-8)
                    class_threshold = torch.quantile(class_scores, q).clamp(min=1e-8)
                    class_selection_scores[class_mask] = class_scores
                    class_thresholds[class_mask] = class_threshold
                    threshold_values.append(class_threshold)
                if threshold_values:
                    selection_scores = class_selection_scores
                    threshold_per_sample = class_thresholds.clamp(min=1e-8)
                    threshold = torch.stack(threshold_values).mean().clamp(min=1e-8)
                    normalized_loss = selection_scores[class_valid].mean().detach()
                    class_count = losses.new_tensor(float(len(threshold_values)))
    if float(gamma) <= 0.0:
        paced_weights = torch.ones_like(losses)
    else:
        score_denominator = selection_scores.clamp(min=1e-8)
        ratio_weights = (threshold_per_sample / score_denominator).pow(float(gamma))
        paced_weights = torch.where(
            selection_scores <= threshold_per_sample,
            torch.ones_like(losses),
            ratio_weights,
        )
    paced_weights = paced_weights.clamp(
        min=min(max(float(min_weight), 0.0), 1.0),
        max=1.0,
    )
    paced_weights = torch.where(valid, paced_weights, torch.zeros_like(paced_weights))
    effective_weights = paced_weights * base_weights
    denominator = effective_weights.sum().clamp(min=1e-12)
    loss = (losses * effective_weights).sum() / denominator

    selected = valid & (selection_scores <= threshold_per_sample)
    high_loss = valid & (~selected)
    selected_fraction = selected.to(dtype=losses.dtype).sum() / valid.to(dtype=losses.dtype).sum().clamp(min=1.0)
    if bool(high_loss.any().item()):
        high_loss_weight_mean = paced_weights[high_loss].mean()
    else:
        high_loss_weight_mean = losses.new_tensor(1.0)
    stats = {
        "raw_loss": losses[valid].mean().detach(),
        "threshold": threshold.detach(),
        "weight_mean": paced_weights[valid].mean().detach(),
        "selected_fraction": selected_fraction.detach(),
        "high_loss_weight_mean": high_loss_weight_mean.detach(),
        "normalized_loss": normalized_loss.detach(),
        "class_count": class_count.detach(),
    }
    return loss.to(dtype=per_sample.dtype), stats


def _cyflod_damped_classification_loss_from_per_sample(
    per_sample: Tensor,
    sample_weights: Optional[Tensor] = None,
    *,
    delta: float = 0.25,
    cycle_epochs: int = 2,
    epoch_index: int = 1,
    min_weight: float = 0.10,
) -> Tuple[Tensor, Dict[str, Tensor]]:
    if not torch.is_tensor(per_sample) or per_sample.ndim != 1 or per_sample.numel() == 0:
        reference = per_sample if torch.is_tensor(per_sample) else torch.tensor(0.0)
        zero = reference.sum() * 0.0
        stats = {
            "raw_loss": zero.detach(),
            "active_delta": zero.detach(),
            "weight_mean": zero.detach(),
            "damped_fraction": zero.detach(),
            "target_probability_mean": zero.detach(),
            "damped_weight_mean": zero.detach(),
        }
        return zero, stats

    losses = per_sample.float().view(-1)
    valid = torch.isfinite(losses)
    if torch.is_tensor(sample_weights):
        base_weights = sample_weights.to(device=losses.device, dtype=losses.dtype).view(-1)
        if base_weights.numel() != losses.numel():
            base_weights = torch.ones_like(losses)
        else:
            base_weights = base_weights.clamp(min=0.0)
    else:
        base_weights = torch.ones_like(losses)
    valid = valid & (base_weights > 0.0)
    if not bool(valid.any().item()):
        zero = losses.sum() * 0.0
        stats = {
            "raw_loss": zero.detach(),
            "active_delta": zero.detach(),
            "weight_mean": zero.detach(),
            "damped_fraction": zero.detach(),
            "target_probability_mean": zero.detach(),
            "damped_weight_mean": zero.detach(),
        }
        return zero.to(dtype=per_sample.dtype), stats

    max_delta = max(float(delta), 0.0)
    cycle = max(1, int(cycle_epochs))
    schedule_epoch = max(1, int(epoch_index))
    cycle_position = ((schedule_epoch - 1) % cycle) + 1
    active_delta_value = max_delta * math.sin(math.pi * float(cycle_position) / float(cycle))
    active_delta = losses.new_tensor(max(active_delta_value, 0.0))

    target_probability = torch.exp(-losses.detach().clamp(min=0.0, max=80.0))
    if float(active_delta.detach().cpu().item()) <= 1e-8:
        damping_weights = torch.ones_like(losses)
        damped = torch.zeros_like(valid)
    else:
        scaled = (target_probability / active_delta.clamp(min=1e-8)).clamp(min=0.0, max=1.0)
        smooth = scaled.pow(3) * (scaled * (scaled * 6.0 - 15.0) + 10.0)
        damped = target_probability < active_delta
        damping_weights = torch.where(damped, smooth, torch.ones_like(losses))
    damping_weights = damping_weights.clamp(
        min=min(max(float(min_weight), 0.0), 1.0),
        max=1.0,
    )
    damping_weights = torch.where(valid, damping_weights, torch.zeros_like(damping_weights))
    effective_weights = damping_weights * base_weights
    denominator = base_weights[valid].sum().clamp(min=1e-12)
    loss = (losses * effective_weights).sum() / denominator

    damped_valid = valid & damped
    damped_fraction = damped_valid.to(dtype=losses.dtype).sum() / valid.to(dtype=losses.dtype).sum().clamp(min=1.0)
    if bool(damped_valid.any().item()):
        damped_weight_mean = damping_weights[damped_valid].mean()
    else:
        damped_weight_mean = losses.new_tensor(1.0)
    stats = {
        "raw_loss": losses[valid].mean().detach(),
        "active_delta": active_delta.detach(),
        "weight_mean": damping_weights[valid].mean().detach(),
        "damped_fraction": damped_fraction.detach(),
        "target_probability_mean": target_probability[valid].mean().detach(),
        "damped_weight_mean": damped_weight_mean.detach(),
    }
    return loss.to(dtype=per_sample.dtype), stats


def _rdrop_symmetric_kl_loss(
    logits_a: Tensor,
    logits_b: Tensor,
    *,
    temperature: float = 1.0,
) -> Tensor:
    if logits_a.shape != logits_b.shape or logits_a.ndim != 2 or logits_a.numel() == 0:
        return logits_a.sum() * 0.0
    temp = max(float(temperature), 1e-6)
    log_prob_a = F.log_softmax(logits_a.float() / temp, dim=1)
    log_prob_b = F.log_softmax(logits_b.float() / temp, dim=1)
    prob_a = log_prob_a.exp()
    prob_b = log_prob_b.exp()
    kl_ab = (prob_a * (log_prob_a - log_prob_b)).sum(dim=1)
    kl_ba = (prob_b * (log_prob_b - log_prob_a)).sum(dim=1)
    return (0.5 * (kl_ab + kl_ba).mean() * (temp * temp)).to(dtype=logits_a.dtype)


def _sample_illumination_consistency_images(
    images: Tensor,
    *,
    brightness: float = 0.08,
    contrast: float = 0.08,
    gamma: float = 0.12,
) -> Tensor:
    if images.ndim != 4 or images.size(1) != 3:
        raise ValueError("illumination consistency expects normalized RGB tensor (B, 3, H, W).")
    rgb = _denormalize_classification_images(images)
    batch_size = int(rgb.size(0))
    device = rgb.device
    dtype = rgb.dtype
    brightness = max(0.0, float(brightness))
    contrast = max(0.0, float(contrast))
    gamma = max(0.0, float(gamma))
    if brightness > 0.0:
        factor = 1.0 + (
            torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0
        ) * brightness
        rgb = rgb * factor
    if contrast > 0.0:
        mean = rgb.mean(dim=(2, 3), keepdim=True)
        factor = 1.0 + (
            torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0
        ) * contrast
        rgb = (rgb - mean) * factor + mean
    rgb = rgb.clamp(0.0, 1.0)
    if gamma > 0.0:
        gamma_value = torch.exp(
            (torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0)
            * gamma
        )
        rgb = rgb.clamp(min=1e-4).pow(gamma_value)
    return _normalize_classification_images(rgb.clamp(0.0, 1.0)).to(dtype=images.dtype)


def _illumination_consistency_loss(
    logits_a: Tensor,
    logits_b: Tensor,
    *,
    temperature: float = 1.0,
) -> Tensor:
    return _rdrop_symmetric_kl_loss(logits_a, logits_b, temperature=temperature)


def _apply_augmix_consistency_op(rgb: Tensor, op_index: int, *, severity: float) -> Tensor:
    batch_size = int(rgb.size(0))
    device = rgb.device
    dtype = rgb.dtype
    strength = max(0.0, float(severity))
    if strength <= 0.0:
        return rgb
    if op_index == 0:
        factor = 1.0 + (
            torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0
        ) * strength
        return (rgb * factor).clamp(0.0, 1.0)
    if op_index == 1:
        mean = rgb.mean(dim=(2, 3), keepdim=True)
        factor = 1.0 + (
            torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0
        ) * strength
        return ((rgb - mean) * factor + mean).clamp(0.0, 1.0)
    if op_index == 2:
        luma = (
            0.299 * rgb[:, 0:1]
            + 0.587 * rgb[:, 1:2]
            + 0.114 * rgb[:, 2:3]
        )
        factor = 1.0 + (
            torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0
        ) * strength
        return (luma + (rgb - luma) * factor).clamp(0.0, 1.0)
    if op_index == 3:
        gamma_value = torch.exp(
            (torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0)
            * strength
        )
        return rgb.clamp(min=1e-4).pow(gamma_value).clamp(0.0, 1.0)
    blur = F.avg_pool2d(rgb, kernel_size=3, stride=1, padding=1)
    amount = (
        torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0
    ) * strength
    return (rgb + amount * (rgb - blur)).clamp(0.0, 1.0)


def _sample_augmix_consistency_images(
    images: Tensor,
    *,
    severity: float = 0.18,
    width: int = 2,
    depth: int = 2,
    alpha: float = 1.0,
) -> Tensor:
    if images.ndim != 4 or images.size(1) != 3:
        raise ValueError("AugMix consistency expects normalized RGB tensor (B, 3, H, W).")
    rgb = _denormalize_classification_images(images)
    batch_size = int(rgb.size(0))
    if batch_size <= 0:
        return images
    width = max(1, int(width))
    depth = max(1, int(depth))
    severity = max(0.0, float(severity))
    if severity <= 0.0:
        return images
    alpha = max(float(alpha), 1e-3)
    device = rgb.device
    dtype = rgb.dtype
    raw_weights = torch.rand(batch_size, width, 1, 1, 1, device=device, dtype=dtype).clamp(
        min=1e-6
    )
    if abs(alpha - 1.0) > 1e-6:
        raw_weights = raw_weights.pow(1.0 / alpha)
    chain_weights = raw_weights / raw_weights.sum(dim=1, keepdim=True).clamp(min=1e-6)
    mixed = torch.zeros_like(rgb)
    for chain_index in range(width):
        chain = rgb
        for _ in range(depth):
            op_index = int(torch.randint(0, 5, (1,), device=device).detach().cpu().item())
            chain = _apply_augmix_consistency_op(chain, op_index, severity=severity)
        mixed = mixed + chain_weights[:, chain_index] * chain
    mix = torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype).clamp(min=1e-6)
    if abs(alpha - 1.0) > 1e-6:
        mix = mix.pow(1.0 / alpha)
    augmented = (1.0 - mix) * rgb + mix * mixed
    return _normalize_classification_images(augmented.clamp(0.0, 1.0)).to(dtype=images.dtype)


def _augmix_consistency_loss(
    logits_clean: Tensor,
    logits_augmented_a: Tensor,
    logits_augmented_b: Tensor,
    *,
    temperature: float = 1.0,
) -> Tensor:
    if (
        logits_clean.shape != logits_augmented_a.shape
        or logits_clean.shape != logits_augmented_b.shape
        or logits_clean.ndim != 2
        or logits_clean.numel() == 0
    ):
        return logits_clean.sum() * 0.0
    temp = max(float(temperature), 1e-6)
    log_prob_clean = F.log_softmax(logits_clean.float() / temp, dim=1)
    log_prob_aug_a = F.log_softmax(logits_augmented_a.float() / temp, dim=1)
    log_prob_aug_b = F.log_softmax(logits_augmented_b.float() / temp, dim=1)
    prob_clean = log_prob_clean.exp()
    prob_aug_a = log_prob_aug_a.exp()
    prob_aug_b = log_prob_aug_b.exp()
    mixture = ((prob_clean + prob_aug_a + prob_aug_b) / 3.0).clamp(min=1e-7)
    log_mixture = mixture.log()
    jsd = (
        (prob_clean * (log_prob_clean - log_mixture)).sum(dim=1).mean()
        + (prob_aug_a * (log_prob_aug_a - log_mixture)).sum(dim=1).mean()
        + (prob_aug_b * (log_prob_aug_b - log_mixture)).sum(dim=1).mean()
    ) / 3.0
    return (jsd * (temp * temp)).to(dtype=logits_clean.dtype)


def _sample_foreground_chroma_consistency_images(
    images: Tensor,
    bboxes: Optional[Tensor],
    *,
    selected_mask: Optional[Tensor] = None,
    saturation_delta: float = 0.10,
    hue_delta: float = 0.015,
    bbox_margin_ratio: float = 0.02,
) -> Tuple[Tensor, float, float]:
    if images.ndim != 4 or images.size(1) != 3:
        raise ValueError("foreground chroma consistency expects normalized RGB tensor (B, 3, H, W).")
    if not torch.is_tensor(bboxes):
        return images, 0.0, 0.0
    if bboxes.ndim == 3:
        bboxes = bboxes[:, 0]
    if bboxes.ndim != 2 or bboxes.size(0) != images.size(0) or bboxes.size(1) < 4:
        return images, 0.0, 0.0

    batch_size, _, height, width = images.shape
    device = images.device
    if selected_mask is None:
        selected = torch.ones(batch_size, device=device, dtype=torch.bool)
    else:
        selected = selected_mask.to(device=device, dtype=torch.bool).view(-1)
        if selected.numel() != batch_size:
            return images, 0.0, 0.0
    if not bool(selected.any().item()):
        return images, 0.0, 0.0

    saturation_delta = max(0.0, float(saturation_delta))
    hue_delta = max(0.0, min(0.5, float(hue_delta)))
    if saturation_delta <= 0.0 and hue_delta <= 0.0:
        return images, 0.0, 0.0

    mask = torch.zeros(
        (batch_size, 1, height, width),
        device=device,
        dtype=images.dtype,
    )
    for sample_index in torch.nonzero(selected, as_tuple=False).flatten().detach().cpu().tolist():
        x1, y1, x2, y2 = _normalized_bbox_to_pixels(
            bboxes[sample_index],
            height=height,
            width=width,
            margin_ratio=bbox_margin_ratio,
        )
        mask[sample_index, :, y1:y2, x1:x2] = 1.0

    selected_count = int(selected.sum().detach().cpu().item())
    if selected_count <= 0 or float(mask.sum().detach().cpu().item()) <= 0.0:
        return images, 0.0, 0.0

    rgb = _denormalize_classification_images(images)
    y_channel = (
        0.299 * rgb[:, 0:1]
        + 0.587 * rgb[:, 1:2]
        + 0.114 * rgb[:, 2:3]
    )
    u_channel = rgb[:, 2:3] - y_channel
    v_channel = rgb[:, 0:1] - y_channel
    dtype = rgb.dtype
    saturation_factor = 1.0 + (
        torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0
    ) * saturation_delta
    angle = (
        torch.rand(batch_size, 1, 1, 1, device=device, dtype=dtype) * 2.0 - 1.0
    ) * (2.0 * math.pi * hue_delta)
    cos_angle = torch.cos(angle)
    sin_angle = torch.sin(angle)
    rotated_u = (cos_angle * u_channel - sin_angle * v_channel) * saturation_factor
    rotated_v = (sin_angle * u_channel + cos_angle * v_channel) * saturation_factor
    red = y_channel + rotated_v
    blue = y_channel + rotated_u
    green = (y_channel - 0.299 * red - 0.114 * blue) / 0.587
    perturbed = torch.cat([red, green, blue], dim=1).clamp(0.0, 1.0)
    blended = rgb * (1.0 - mask) + perturbed * mask
    selected_area = float(mask.sum().detach().float().cpu().item())
    mask_fraction = selected_area / float(max(1, selected_count * height * width))
    return (
        _normalize_classification_images(blended.clamp(0.0, 1.0)).to(dtype=images.dtype),
        float(selected_count) / float(max(1, batch_size)),
        float(mask_fraction),
    )


def _foreground_chroma_consistency_loss(
    logits_a: Tensor,
    logits_b: Tensor,
    *,
    temperature: float = 1.0,
) -> Tensor:
    return _rdrop_symmetric_kl_loss(logits_a, logits_b, temperature=temperature)


def _parse_friendly_adversarial_negative_classes(
    values: Union[str, Sequence[int]],
    *,
    num_classes: int,
    focus_class: int,
) -> List[int]:
    if isinstance(values, str):
        raw_values = [value.strip() for value in values.split(",") if value.strip()]
        parsed = [int(value) for value in raw_values]
    else:
        parsed = [int(value) for value in values]
    classes: List[int] = []
    for class_index in parsed:
        if not 0 <= int(class_index) < int(num_classes):
            raise ValueError(
                f"friendly adversarial negative class {class_index} outside [0,{num_classes})"
            )
        if int(class_index) == int(focus_class):
            raise ValueError("friendly adversarial negative classes cannot contain focus class")
        if int(class_index) not in classes:
            classes.append(int(class_index))
    if not classes:
        raise ValueError("friendly adversarial negative classes cannot be empty")
    return classes


def _select_friendly_adversarial_indices(
    logits: Tensor,
    target_indices: Tensor,
    *,
    focus_class: int,
    negative_classes: Sequence[int],
    max_per_direction: int,
) -> Tuple[Tensor, Tensor]:
    if logits.ndim != 2 or target_indices.ndim != 1:
        raise ValueError("friendly adversarial logits/targets must be [B,C] and [B]")
    if int(logits.size(0)) != int(target_indices.numel()):
        raise ValueError("friendly adversarial logits/targets batch sizes differ")
    if int(max_per_direction) <= 0:
        empty = torch.empty(0, device=logits.device, dtype=torch.long)
        return empty, empty
    detached_logits = logits.detach().float()
    targets = target_indices.to(device=logits.device, dtype=torch.long)
    predictions = detached_logits.argmax(dim=1)
    top2 = detached_logits.topk(k=min(2, int(detached_logits.size(1))), dim=1).indices
    focus_in_top2 = (top2 == int(focus_class)).any(dim=1)
    negative_tensor = torch.as_tensor(
        list(negative_classes), device=logits.device, dtype=torch.long
    )
    target_is_negative = torch.isin(targets, negative_tensor)

    protect_mask = (targets == int(focus_class)) & (predictions == int(focus_class))
    suppress_mask = target_is_negative & (predictions == targets) & focus_in_top2
    rival_logits = detached_logits.index_select(1, negative_tensor).max(dim=1).values
    protect_margin = detached_logits[:, int(focus_class)] - rival_logits
    true_logits = detached_logits.gather(1, targets.view(-1, 1)).squeeze(1)
    suppress_margin = true_logits - detached_logits[:, int(focus_class)]

    def select(mask: Tensor, margins: Tensor) -> Tensor:
        candidates = torch.nonzero(mask, as_tuple=False).flatten()
        if candidates.numel() == 0:
            return candidates
        candidate_margins = margins.index_select(0, candidates)
        order = torch.argsort(candidate_margins, stable=True)
        return candidates.index_select(0, order[: int(max_per_direction)])

    return select(protect_mask, protect_margin), select(suppress_mask, suppress_margin)


def _friendly_foreground_adversarial_loss(
    *,
    model: nn.Module,
    images: Tensor,
    logits: Tensor,
    target_indices: Tensor,
    image_valid_mask: Optional[Tensor],
    bbox_metadata: Optional[Tensor],
    crop_bbox_metadata: Optional[Tensor],
    bbox_token_prior_metadata: Optional[Tensor],
    device: torch.device,
    amp: bool,
    input_mean: Sequence[float],
    input_std: Sequence[float],
    epsilon: float,
    step_size: float,
    steps: int,
    bbox_erode_ratio: float,
    focus_class: int,
    negative_classes: Union[str, Sequence[int]],
    max_per_direction: int,
) -> Tuple[Tensor, Dict[str, float]]:
    zero = logits.sum() * 0.0
    stats = {
        "friendly_adversarial_protect_fraction": 0.0,
        "friendly_adversarial_suppress_fraction": 0.0,
        "friendly_adversarial_protect_count": 0.0,
        "friendly_adversarial_suppress_count": 0.0,
        "friendly_adversarial_protect_crossing_rate": 0.0,
        "friendly_adversarial_suppress_crossing_rate": 0.0,
        "friendly_adversarial_max_delta_rgb": 0.0,
        "friendly_adversarial_direction_count": 0.0,
    }
    if (
        images.ndim != 4
        or not torch.is_tensor(image_valid_mask)
        or not torch.is_tensor(bbox_metadata)
        or not torch.is_tensor(crop_bbox_metadata)
        or not torch.is_tensor(bbox_token_prior_metadata)
    ):
        return zero, stats
    parsed_negatives = _parse_friendly_adversarial_negative_classes(
        negative_classes,
        num_classes=int(logits.size(1)),
        focus_class=int(focus_class),
    )
    protect_indices, suppress_indices = _select_friendly_adversarial_indices(
        logits,
        target_indices,
        focus_class=int(focus_class),
        negative_classes=parsed_negatives,
        max_per_direction=int(max_per_direction),
    )
    direction_losses: List[Tensor] = []
    batch_size = int(images.size(0))
    module_modes = [(module, bool(module.training)) for module in model.modules()]
    model.eval()
    try:
        for direction, selected_indices in (
            ("protect", protect_indices),
            ("suppress", suppress_indices),
        ):
            if selected_indices.numel() == 0:
                continue
            selected_images = images.index_select(0, selected_indices)
            selected_targets = target_indices.index_select(0, selected_indices).long()
            selected_valid_mask = image_valid_mask.index_select(0, selected_indices)
            selected_bbox = bbox_metadata.index_select(0, selected_indices)
            selected_crop_bbox = crop_bbox_metadata.index_select(0, selected_indices)
            selected_prior = bbox_token_prior_metadata.index_select(0, selected_indices)
            attack_mask = build_eroded_bbox_mask(
                selected_crop_bbox,
                selected_valid_mask,
                height=int(images.size(2)),
                width=int(images.size(3)),
                erode_ratio=float(bbox_erode_ratio),
            )

            def forward_logits(candidate_images: Tensor) -> Tensor:
                with autocast_context(device, False):
                    _, candidate_outputs = _forward_model_outputs(
                        model,
                        candidate_images.float(),
                        image_valid_mask=selected_valid_mask,
                        bbox_metadata=selected_bbox,
                        bbox_token_prior=selected_prior,
                    )
                    candidate_logits, _ = extract_bbox_from_model_output(candidate_outputs)
                return candidate_logits.float()

            attack = generate_friendly_adversarial_examples(
                images=selected_images.float(),
                labels=selected_targets,
                attack_mask=attack_mask,
                forward_logits=forward_logits,
                mean=input_mean,
                std=input_std,
                direction=direction,
                focus_class=int(focus_class),
                negative_classes=parsed_negatives,
                epsilon=float(epsilon),
                step_size=float(step_size),
                steps=int(steps),
            )
            valid = (attack.clean_margin < 0.0) & attack.attack_mask.flatten(1).any(dim=1)
            if not bool(valid.any().item()):
                continue
            valid_positions = torch.nonzero(valid, as_tuple=False).flatten()
            valid_images = attack.adversarial_images.index_select(0, valid_positions)
            valid_targets = selected_targets.index_select(0, valid_positions)
            valid_mask = selected_valid_mask.index_select(0, valid_positions)
            valid_bbox = selected_bbox.index_select(0, valid_positions)
            valid_prior = selected_prior.index_select(0, valid_positions)
            for module, training in module_modes:
                module.training = training
            with autocast_context(device, amp):
                _, adversarial_outputs = _forward_model_outputs(
                    model,
                    valid_images,
                    image_valid_mask=valid_mask,
                    bbox_metadata=valid_bbox,
                    bbox_token_prior=valid_prior,
                )
                adversarial_logits, _ = extract_bbox_from_model_output(adversarial_outputs)
                direction_losses.append(F.cross_entropy(adversarial_logits, valid_targets))
            model.eval()
            prefix = f"friendly_adversarial_{direction}"
            count = int(valid_positions.numel())
            stats[f"{prefix}_count"] = float(count)
            stats[f"{prefix}_fraction"] = float(count / max(1, batch_size))
            stats[f"{prefix}_crossing_rate"] = float(
                attack.crossed.index_select(0, valid_positions).float().mean().item()
            )
            stats["friendly_adversarial_max_delta_rgb"] = max(
                stats["friendly_adversarial_max_delta_rgb"],
                float(attack.delta_rgb.index_select(0, valid_positions).abs().max().item()),
            )
    finally:
        for module, training in module_modes:
            module.training = training
    if not direction_losses:
        return zero, stats
    stats["friendly_adversarial_direction_count"] = float(len(direction_losses))
    return torch.stack(direction_losses).mean().to(dtype=logits.dtype), stats


def _parse_semantic_attribute_specs(
    specs: Union[str, Sequence[str]],
    *,
    num_classes: int,
) -> List[Tuple[str, List[Tuple[int, ...]]]]:
    if isinstance(specs, str):
        raw_specs = [item.strip() for item in specs.replace("\n", ";").split(";")]
    else:
        raw_specs = [str(item).strip() for item in specs]
    parsed: List[Tuple[str, List[Tuple[int, ...]]]] = []
    for spec_index, raw_spec in enumerate(raw_specs):
        if not raw_spec:
            continue
        if ":" in raw_spec:
            name, group_text = raw_spec.split(":", 1)
            name = name.strip() or f"attribute_{spec_index}"
        else:
            name = f"attribute_{spec_index}"
            group_text = raw_spec
        groups: List[Tuple[int, ...]] = []
        seen: set[int] = set()
        for raw_group in group_text.split("|"):
            group = []
            for raw_class in raw_group.replace("/", ",").split(","):
                raw_class = raw_class.strip()
                if not raw_class:
                    continue
                class_index = int(raw_class)
                if class_index < 0 or class_index >= int(num_classes):
                    raise ValueError(
                        "semantic attribute class nam ngoai khoang: "
                        f"task={name!r}, class={class_index}, num_classes={num_classes}"
                    )
                if class_index in seen:
                    raise ValueError(
                        "semantic attribute spec khong duoc lap class trong cung task: "
                        f"task={name!r}, class={class_index}"
                    )
                seen.add(class_index)
                group.append(class_index)
            if group:
                groups.append(tuple(group))
        if len(groups) < 2:
            raise ValueError(
                "semantic attribute task can it nhat 2 group co class: "
                f"task={name!r}"
            )
        parsed.append((name, groups))
    return parsed


def _semantic_attribute_loss_from_logits(
    logits: Tensor,
    targets,
    specs: Union[str, Sequence[str]],
) -> Tuple[Tensor, float]:
    target_indices = _classification_target_indices(targets, logits)
    if target_indices is None or logits.ndim != 2 or logits.numel() == 0:
        return logits.sum() * 0.0, 0.0
    parsed_specs = _parse_semantic_attribute_specs(
        specs,
        num_classes=int(logits.size(1)),
    )
    if not parsed_specs:
        return logits.sum() * 0.0, 0.0

    log_probs = F.log_softmax(logits.float(), dim=1)
    losses: List[Tensor] = []
    for _, groups in parsed_specs:
        group_log_probs = []
        group_targets = target_indices.new_full(target_indices.shape, -100)
        for group_index, group in enumerate(groups):
            class_indices = torch.tensor(group, device=logits.device, dtype=torch.long)
            group_log_probs.append(
                torch.logsumexp(log_probs.index_select(1, class_indices), dim=1)
            )
            mask = torch.zeros_like(target_indices, dtype=torch.bool)
            for class_index in group:
                mask |= target_indices == int(class_index)
            group_targets[mask] = int(group_index)
        valid = group_targets >= 0
        if not bool(valid.any().detach().cpu().item()):
            continue
        grouped = torch.stack(group_log_probs, dim=1)
        grouped = grouped - torch.logsumexp(grouped, dim=1, keepdim=True)
        losses.append(F.nll_loss(grouped[valid], group_targets[valid]))
    if not losses:
        return logits.sum() * 0.0, 0.0
    loss = torch.stack(losses).mean()
    return loss.to(dtype=logits.dtype), float(len(losses))


class DataCartographyRecorder:
    def __init__(
        self,
        *,
        sample_paths: Sequence[Path],
        labels: Sequence[int],
        class_names: Sequence[str],
        output_path: Path,
    ) -> None:
        self.sample_paths = [Path(path) for path in sample_paths]
        self.labels = [int(label) for label in labels]
        self.class_names = [str(name) for name in class_names]
        self.output_path = Path(output_path)
        sample_count = len(self.sample_paths)
        self.num_classes = max(
            len(self.class_names),
            (max(self.labels) + 1) if self.labels else 0,
        )
        self.seen_counts = [0 for _ in range(sample_count)]
        self.confidence_sums = [0.0 for _ in range(sample_count)]
        self.confidence_square_sums = [0.0 for _ in range(sample_count)]
        self.correct_sums = [0.0 for _ in range(sample_count)]
        self.ce_loss_sums = [0.0 for _ in range(sample_count)]
        self.probability_sums = [
            [0.0 for _ in range(self.num_classes)] for _ in range(sample_count)
        ]
        self.prediction_counts = [
            [0 for _ in range(self.num_classes)] for _ in range(sample_count)
        ]

    def _ensure_class_count(self, num_classes: int) -> None:
        num_classes = int(num_classes)
        if num_classes <= self.num_classes:
            return
        extra = num_classes - self.num_classes
        for probabilities in self.probability_sums:
            probabilities.extend([0.0 for _ in range(extra)])
        for counts in self.prediction_counts:
            counts.extend([0 for _ in range(extra)])
        self.num_classes = num_classes

    def update(
        self,
        *,
        sample_indices: Optional[Tensor],
        logits: Tensor,
        labels: Optional[Tensor],
    ) -> None:
        if sample_indices is None or labels is None:
            return
        if not torch.is_tensor(sample_indices) or not torch.is_tensor(labels):
            return
        if logits.ndim != 2 or logits.size(0) == 0:
            return
        indices = sample_indices.detach().to(device="cpu", dtype=torch.long).view(-1)
        targets = labels.detach().to(device="cpu", dtype=torch.long).view(-1)
        if indices.numel() != logits.size(0) or targets.numel() != logits.size(0):
            return
        logits_cpu = logits.detach().float().cpu()
        probabilities = torch.softmax(logits_cpu, dim=1)
        self._ensure_class_count(int(probabilities.size(1)))
        predictions = probabilities.argmax(dim=1)
        safe_targets = targets.clamp(min=0, max=max(0, probabilities.size(1) - 1))
        row_indices = torch.arange(probabilities.size(0), dtype=torch.long)
        confidences = probabilities[row_indices, safe_targets]
        ce_losses = F.cross_entropy(logits_cpu, safe_targets, reduction="none")
        for row, sample_index_value in enumerate(indices.tolist()):
            sample_index = int(sample_index_value)
            if sample_index < 0 or sample_index >= len(self.seen_counts):
                continue
            target_index = int(targets[row].item())
            if target_index < 0 or target_index >= probabilities.size(1):
                continue
            confidence = float(confidences[row].item())
            correct = 1.0 if int(predictions[row].item()) == target_index else 0.0
            ce_loss = float(ce_losses[row].item())
            self.seen_counts[sample_index] += 1
            self.confidence_sums[sample_index] += confidence
            self.confidence_square_sums[sample_index] += confidence * confidence
            self.correct_sums[sample_index] += correct
            self.ce_loss_sums[sample_index] += ce_loss
            row_probabilities = probabilities[row].tolist()
            for class_index, probability in enumerate(row_probabilities):
                self.probability_sums[sample_index][class_index] += float(probability)
            prediction_index = int(predictions[row].item())
            if 0 <= prediction_index < self.num_classes:
                self.prediction_counts[sample_index][prediction_index] += 1

    @staticmethod
    def _bucket(confidence_mean: float, confidence_std: float, correctness_mean: float) -> str:
        if correctness_mean >= 0.80 and confidence_mean >= 0.60 and confidence_std <= 0.18:
            return "easy_clean"
        if correctness_mean <= 0.20 or confidence_mean <= 0.35:
            return "hard_or_mislabeled"
        if confidence_std >= 0.20 or 0.35 < confidence_mean < 0.65:
            return "ambiguous_boundary"
        return "review"

    def write(self, *, epoch: int) -> None:
        self.output_path.parent.mkdir(parents=True, exist_ok=True)
        with self.output_path.open("w", encoding="utf-8", newline="") as handle:
            writer = csv.DictWriter(
                handle,
                fieldnames=[
                    "sample_index",
                    "image_path",
                    "target_index",
                    "target_name",
                    "seen_count",
                    "confidence_mean",
                    "confidence_std",
                    "correctness_mean",
                    "ce_loss_mean",
                    "cartography_bucket",
                    "prediction_index",
                    "prediction_name",
                    "prediction_mean",
                    "top2_index",
                    "top2_name",
                    "top2_probability",
                    "top2_margin",
                    "last_epoch",
                ],
            )
            for class_index in range(self.num_classes):
                writer.fieldnames.append(f"prob_{class_index}")  # type: ignore[union-attr]
            writer.writeheader()
            for sample_index, sample_path in enumerate(self.sample_paths):
                seen = int(self.seen_counts[sample_index])
                target_index = int(self.labels[sample_index]) if sample_index < len(self.labels) else -1
                target_name = (
                    self.class_names[target_index]
                    if 0 <= target_index < len(self.class_names)
                    else ""
                )
                if seen <= 0:
                    confidence_mean = 0.0
                    confidence_std = 0.0
                    correctness_mean = 0.0
                    ce_loss_mean = 0.0
                    bucket = "unseen"
                    mean_probabilities = [0.0 for _ in range(self.num_classes)]
                else:
                    confidence_mean = self.confidence_sums[sample_index] / float(seen)
                    confidence_square_mean = self.confidence_square_sums[sample_index] / float(seen)
                    variance = max(0.0, confidence_square_mean - confidence_mean * confidence_mean)
                    confidence_std = math.sqrt(variance)
                    correctness_mean = self.correct_sums[sample_index] / float(seen)
                    ce_loss_mean = self.ce_loss_sums[sample_index] / float(seen)
                    bucket = self._bucket(confidence_mean, confidence_std, correctness_mean)
                    mean_probabilities = [
                        value / float(seen)
                        for value in self.probability_sums[sample_index]
                    ]
                ranked_indices = sorted(
                    range(len(mean_probabilities)),
                    key=lambda class_index: mean_probabilities[class_index],
                    reverse=True,
                )
                prediction_index = int(ranked_indices[0]) if ranked_indices else -1
                top2_index = int(ranked_indices[1]) if len(ranked_indices) > 1 else -1
                prediction_mean = (
                    float(mean_probabilities[prediction_index]) if prediction_index >= 0 else 0.0
                )
                top2_probability = (
                    float(mean_probabilities[top2_index]) if top2_index >= 0 else 0.0
                )
                prediction_name = (
                    self.class_names[prediction_index]
                    if 0 <= prediction_index < len(self.class_names)
                    else ""
                )
                top2_name = (
                    self.class_names[top2_index]
                    if 0 <= top2_index < len(self.class_names)
                    else ""
                )
                output_row = {
                    "sample_index": int(sample_index),
                    "image_path": str(sample_path),
                    "target_index": int(target_index),
                    "target_name": target_name,
                    "seen_count": int(seen),
                    "confidence_mean": f"{confidence_mean:.8f}",
                    "confidence_std": f"{confidence_std:.8f}",
                    "correctness_mean": f"{correctness_mean:.8f}",
                    "ce_loss_mean": f"{ce_loss_mean:.8f}",
                    "cartography_bucket": bucket,
                    "prediction_index": int(prediction_index) if seen > 0 else -1,
                    "prediction_name": prediction_name if seen > 0 else "",
                    "prediction_mean": f"{prediction_mean:.8f}" if seen > 0 else "0.00000000",
                    "top2_index": int(top2_index) if seen > 0 else -1,
                    "top2_name": top2_name if seen > 0 else "",
                    "top2_probability": f"{top2_probability:.8f}" if seen > 0 else "0.00000000",
                    "top2_margin": f"{(prediction_mean - top2_probability):.8f}" if seen > 0 else "0.00000000",
                    "last_epoch": int(epoch),
                }
                for class_index, probability in enumerate(mean_probabilities):
                    output_row[f"prob_{class_index}"] = f"{float(probability):.8f}"
                writer.writerow(output_row)


def _expanded_dataset_sample_paths(dataset) -> List[Path]:
    indices = getattr(dataset, "indices", None)
    child = getattr(dataset, "dataset", None)
    if child is not None and isinstance(indices, Sequence):
        base_paths = _expanded_dataset_sample_paths(child)
        return [
            Path(base_paths[int(index)])
            for index in indices
            if 0 <= int(index) < len(base_paths)
        ]
    sample_paths_fn = getattr(dataset, "sample_paths", None)
    if callable(sample_paths_fn):
        return [Path(path) for path in sample_paths_fn()]
    samples = getattr(dataset, "samples", None)
    if samples is not None:
        return [
            Path(getattr(sample, "image_path"))
            for sample in samples
            if getattr(sample, "image_path", None) is not None
        ]
    return []


def _expanded_dataset_labels(dataset) -> List[int]:
    indices = getattr(dataset, "indices", None)
    child = getattr(dataset, "dataset", None)
    if child is not None and isinstance(indices, Sequence):
        base_labels = _expanded_dataset_labels(child)
        return [
            int(base_labels[int(index)])
            for index in indices
            if 0 <= int(index) < len(base_labels)
        ]
    labels_fn = getattr(dataset, "labels", None)
    if callable(labels_fn):
        return [int(label) for label in labels_fn()]
    samples = getattr(dataset, "samples", None)
    if samples is not None:
        labels: List[int] = []
        for sample in samples:
            if hasattr(sample, "primary_label"):
                labels.append(int(getattr(sample, "primary_label")))
            elif hasattr(sample, "label"):
                labels.append(int(getattr(sample, "label")))
        return labels
    return []


def _group_dro_loss_from_per_sample(
    per_sample_loss: Optional[Tensor],
    group_indices: Optional[Tensor],
    *,
    temperature: float,
    min_samples: int,
) -> Tuple[Tensor, float, float]:
    if per_sample_loss is None or not torch.is_tensor(per_sample_loss):
        reference = group_indices if torch.is_tensor(group_indices) else torch.tensor(0.0)
        return reference.float().sum() * 0.0, 0.0, 0.0
    if group_indices is None or not torch.is_tensor(group_indices):
        return per_sample_loss.sum() * 0.0, 0.0, 0.0
    losses = per_sample_loss.float().view(-1)
    groups = group_indices.to(device=losses.device, dtype=torch.long).view(-1)
    if losses.numel() != groups.numel() or losses.numel() == 0:
        return losses.sum() * 0.0, 0.0, 0.0
    valid = groups >= 0
    if not bool(valid.any().item()):
        return losses.sum() * 0.0, 0.0, 0.0

    group_losses: List[Tensor] = []
    min_count = max(1, int(min_samples))
    for group_index in torch.unique(groups[valid]).tolist():
        mask = valid & (groups == int(group_index))
        if int(mask.sum().item()) < min_count:
            continue
        group_losses.append(losses[mask].mean())
    if not group_losses:
        return losses.sum() * 0.0, 0.0, 0.0

    stacked = torch.stack(group_losses)
    weights = torch.softmax(stacked.detach() / max(float(temperature), 1e-6), dim=0)
    loss = (weights * stacked).sum()
    return loss.to(dtype=per_sample_loss.dtype), float(len(group_losses)), float(stacked.max().detach().cpu().item())


def _targeted_margin_loss_from_logits(
    *,
    logits: Tensor,
    hard_labels: Optional[Tensor],
    targets,
    negative_indices: Optional[Tensor],
    weights: Optional[Tensor],
    margins: Optional[Tensor],
    default_margin: float,
) -> Tuple[Tensor, Tensor, float]:
    zero = logits.sum() * 0.0
    if negative_indices is None or not torch.is_tensor(negative_indices) or logits.ndim != 2:
        return zero, zero.detach(), 0.0
    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, logits)
    if target_indices is None:
        return zero, zero.detach(), 0.0

    negatives = negative_indices.to(device=logits.device, dtype=torch.long).view(-1)
    if target_indices.numel() != logits.size(0) or negatives.numel() != logits.size(0):
        return zero, zero.detach(), 0.0
    valid = (
        (target_indices >= 0)
        & (target_indices < int(logits.size(1)))
        & (negatives >= 0)
        & (negatives < int(logits.size(1)))
        & (negatives != target_indices)
    )
    if weights is not None and torch.is_tensor(weights):
        sample_weights = weights.to(device=logits.device, dtype=logits.dtype).view(-1)
        if sample_weights.numel() != logits.size(0):
            sample_weights = torch.ones_like(negatives, dtype=logits.dtype)
    else:
        sample_weights = torch.ones_like(negatives, dtype=logits.dtype)
    sample_weights = sample_weights.clamp(min=0.0)
    valid = valid & (sample_weights > 0)
    if not bool(valid.any().item()):
        return zero, sample_weights.detach().mean() if sample_weights.numel() else zero.detach(), 0.0

    if margins is not None and torch.is_tensor(margins):
        sample_margins = margins.to(device=logits.device, dtype=logits.dtype).view(-1)
        if sample_margins.numel() != logits.size(0):
            sample_margins = logits.new_full((logits.size(0),), float(default_margin))
    else:
        sample_margins = logits.new_full((logits.size(0),), float(default_margin))
    sample_margins = sample_margins.clamp(min=0.0)

    row_indices = torch.arange(logits.size(0), device=logits.device)
    target_logits = logits[row_indices[valid], target_indices[valid]]
    negative_logits = logits[row_indices[valid], negatives[valid]]
    per_sample = F.relu(sample_margins[valid] + negative_logits - target_logits)
    valid_weights = sample_weights[valid]
    loss = (per_sample * valid_weights).sum() / valid_weights.sum().clamp(min=1e-12)
    fraction = float(valid.float().mean().detach().cpu().item())
    return loss.to(dtype=logits.dtype), sample_weights.detach().mean(), fraction


def _focus_neighbor_binary_loss_from_logits(
    *,
    logits: Tensor,
    binary_targets: Optional[Tensor],
    weights: Optional[Tensor],
    neighbor_indices: Optional[Tensor],
    focus_class: int,
    neighbor_classes: Union[str, Sequence[int]],
) -> Tuple[Tensor, float, Tensor, Tensor]:
    zero = logits.sum() * 0.0
    if logits.ndim != 2 or logits.size(0) == 0:
        return zero, 0.0, zero.detach(), zero.detach()
    num_classes = int(logits.size(1))
    focus = int(focus_class)
    if focus < 0 or focus >= num_classes:
        raise ValueError(
            f"focus-neighbor binary class {focus} nam ngoai [0, {num_classes - 1}]."
        )
    if binary_targets is None or not torch.is_tensor(binary_targets):
        return zero, 0.0, zero.detach(), zero.detach()
    targets = binary_targets.to(device=logits.device, dtype=logits.dtype).view(-1)
    if targets.numel() != logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    neighbors = _parse_angular_margin_classes(
        neighbor_classes,
        num_classes=num_classes,
    )
    neighbors = [class_index for class_index in neighbors if int(class_index) != focus]
    if not neighbors:
        return zero, 0.0, zero.detach(), zero.detach()
    neighbor_tensor = torch.tensor(neighbors, device=logits.device, dtype=torch.long)
    default_neighbor_logits = torch.logsumexp(
        logits.index_select(1, neighbor_tensor).float(),
        dim=1,
    ).to(dtype=logits.dtype)

    selected_neighbor_logits = default_neighbor_logits
    if neighbor_indices is not None and torch.is_tensor(neighbor_indices):
        specific_neighbors = neighbor_indices.to(device=logits.device, dtype=torch.long).view(-1)
        if specific_neighbors.numel() == logits.size(0):
            specific_valid = (
                (specific_neighbors >= 0)
                & (specific_neighbors < num_classes)
                & (specific_neighbors != focus)
            )
            if bool(specific_valid.any().item()):
                selected_neighbor_logits = default_neighbor_logits.clone()
                row_indices = torch.arange(logits.size(0), device=logits.device)
                selected_neighbor_logits[specific_valid] = logits[
                    row_indices[specific_valid],
                    specific_neighbors[specific_valid],
                ]

    if weights is not None and torch.is_tensor(weights):
        sample_weights = weights.to(device=logits.device, dtype=logits.dtype).view(-1)
        if sample_weights.numel() != logits.size(0):
            sample_weights = torch.ones_like(targets)
    else:
        sample_weights = torch.ones_like(targets)
    sample_weights = sample_weights.clamp(min=0.0)
    targets = targets.clamp(min=0.0, max=1.0)
    valid = sample_weights > 0.0
    if not bool(valid.any().item()):
        return (
            zero,
            0.0,
            zero.detach(),
            sample_weights.detach().mean() if sample_weights.numel() else zero.detach(),
        )

    binary_logits = logits[:, focus] - selected_neighbor_logits
    per_sample = F.binary_cross_entropy_with_logits(
        binary_logits[valid].float(),
        targets[valid].float(),
        reduction="none",
    ).to(dtype=logits.dtype)
    valid_weights = sample_weights[valid]
    loss = (per_sample * valid_weights).sum() / valid_weights.sum().clamp(min=1e-12)
    focus_probability = torch.sigmoid(binary_logits[valid].float()).to(dtype=logits.dtype)
    weighted_probability = (
        focus_probability * valid_weights
    ).sum() / valid_weights.sum().clamp(min=1e-12)
    fraction = float(valid.float().mean().detach().cpu().item())
    return (
        loss.to(dtype=logits.dtype),
        fraction,
        weighted_probability.detach(),
        sample_weights.detach().mean(),
    )


def _focused_false_positive_margin_loss_from_logits(
    *,
    logits: Tensor,
    hard_labels: Optional[Tensor],
    targets,
    focus_class: int,
    negative_classes: Union[str, Sequence[int]],
    margin: float,
    min_probability: float,
    probability_power: float,
) -> Tuple[Tensor, float, Tensor]:
    zero = logits.sum() * 0.0
    if logits.ndim != 2 or logits.size(0) == 0:
        return zero, 0.0, zero.detach()
    num_classes = int(logits.size(1))
    focus = int(focus_class)
    if focus < 0 or focus >= num_classes:
        raise ValueError(
            f"focused false-positive class {focus} nam ngoai [0, {num_classes - 1}]."
        )
    negatives = _parse_angular_margin_classes(
        negative_classes,
        num_classes=num_classes,
    )
    negatives = [class_index for class_index in negatives if int(class_index) != focus]
    if not negatives:
        return zero, 0.0, zero.detach()

    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, logits)
    if target_indices is None or target_indices.numel() != logits.size(0):
        return zero, 0.0, zero.detach()

    negative_tensor = torch.tensor(negatives, device=logits.device, dtype=torch.long)
    valid = (
        (target_indices >= 0)
        & (target_indices < num_classes)
        & torch.isin(target_indices, negative_tensor)
    )
    probabilities = torch.softmax(logits.float(), dim=1).to(dtype=logits.dtype)
    focus_probabilities = probabilities[:, focus].clamp(min=0.0, max=1.0)
    if float(min_probability) > 0.0:
        valid = valid & (focus_probabilities >= float(min_probability))
    if not bool(valid.any().item()):
        return zero, 0.0, focus_probabilities.detach().mean()

    row_indices = torch.arange(logits.size(0), device=logits.device)
    target_logits = logits[row_indices[valid], target_indices[valid]]
    focus_logits = logits[row_indices[valid], focus]
    raw_margin = float(margin) + focus_logits - target_logits
    per_sample = F.softplus(raw_margin / 0.20) * 0.20
    weights = focus_probabilities[valid].detach().pow(float(probability_power)).clamp(min=1e-6)
    loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
    fraction = float(valid.float().mean().detach().cpu().item())
    return loss.to(dtype=logits.dtype), fraction, focus_probabilities.detach().mean()


def _teacher_focus_margin_loss_from_logits(
    *,
    logits: Tensor,
    teacher_probabilities: Optional[Tensor],
    hard_labels: Optional[Tensor],
    targets,
    focus_class: int,
    negative_classes: Union[str, Sequence[int]],
    teacher_max_probability: float,
    margin: float,
    min_probability: float,
    probability_power: float,
    require_agreement: bool,
) -> Tuple[Tensor, float, Tensor, Tensor]:
    zero = logits.sum() * 0.0
    if (
        teacher_probabilities is None
        or not torch.is_tensor(teacher_probabilities)
        or logits.ndim != 2
        or logits.size(0) == 0
    ):
        return zero, 0.0, zero.detach(), zero.detach()
    if teacher_probabilities.ndim != 2 or teacher_probabilities.size(0) != logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    num_classes = int(logits.size(1))
    focus = int(focus_class)
    if focus < 0 or focus >= num_classes:
        raise ValueError(
            f"teacher focus-margin class {focus} nam ngoai [0, {num_classes - 1}]."
        )
    if int(teacher_probabilities.size(1)) != num_classes:
        return zero, 0.0, zero.detach(), zero.detach()

    negatives = _parse_angular_margin_classes(
        negative_classes,
        num_classes=num_classes,
    )
    negatives = [class_index for class_index in negatives if int(class_index) != focus]
    if not negatives:
        return zero, 0.0, zero.detach(), zero.detach()

    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, logits)
    if target_indices is None or target_indices.numel() != logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    teacher_probs = teacher_probabilities.to(device=logits.device, dtype=torch.float32).clamp(min=0.0)
    teacher_probs = teacher_probs / teacher_probs.sum(dim=1, keepdim=True).clamp(min=1e-12)
    teacher_focus_probabilities = teacher_probs[:, focus].clamp(min=0.0, max=1.0)
    teacher_predictions = teacher_probs.argmax(dim=1)

    negative_tensor = torch.tensor(negatives, device=logits.device, dtype=torch.long)
    valid = (
        (target_indices >= 0)
        & (target_indices < num_classes)
        & torch.isin(target_indices, negative_tensor)
        & (teacher_focus_probabilities <= float(teacher_max_probability))
    )
    if bool(require_agreement):
        valid = valid & (teacher_predictions == target_indices)

    probabilities = torch.softmax(logits.float(), dim=1)
    focus_probabilities = probabilities[:, focus].clamp(min=0.0, max=1.0)
    if float(min_probability) > 0.0:
        valid = valid & (focus_probabilities >= float(min_probability))
    if not bool(valid.any().item()):
        return (
            zero,
            0.0,
            focus_probabilities.detach().mean().to(dtype=logits.dtype),
            teacher_focus_probabilities.detach().mean().to(dtype=logits.dtype),
        )

    row_indices = torch.arange(logits.size(0), device=logits.device)
    target_logits = logits[row_indices[valid], target_indices[valid]]
    focus_logits = logits[row_indices[valid], focus]
    raw_margin = float(margin) + focus_logits - target_logits
    per_sample = F.softplus(raw_margin / 0.20) * 0.20
    teacher_confidence = (1.0 - teacher_focus_probabilities[valid]).detach()
    weights = (
        focus_probabilities[valid]
        .detach()
        .pow(float(probability_power))
        .clamp(min=1e-6)
        * teacher_confidence.clamp(min=1e-6)
    )
    loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
    fraction = float(valid.float().mean().detach().cpu().item())
    return (
        loss.to(dtype=logits.dtype),
        fraction,
        focus_probabilities.detach().mean().to(dtype=logits.dtype),
        teacher_focus_probabilities.detach().mean().to(dtype=logits.dtype),
    )


def _teacher_focus_binary_loss_from_logits(
    *,
    logits: Tensor,
    teacher_probabilities: Optional[Tensor],
    hard_labels: Optional[Tensor],
    targets,
    focus_class: int,
    classes: Union[str, Sequence[int]],
    teacher_min_confidence: float,
    error_power: float,
    hard_target_blend: float,
    require_agreement: bool,
) -> Tuple[Tensor, float, Tensor, Tensor]:
    zero = logits.sum() * 0.0
    if (
        teacher_probabilities is None
        or not torch.is_tensor(teacher_probabilities)
        or logits.ndim != 2
        or logits.size(0) == 0
    ):
        return zero, 0.0, zero.detach(), zero.detach()
    if teacher_probabilities.ndim != 2 or teacher_probabilities.size(0) != logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    num_classes = int(logits.size(1))
    focus = int(focus_class)
    if focus < 0 or focus >= num_classes:
        raise ValueError(
            f"teacher focus-binary class {focus} nam ngoai [0, {num_classes - 1}]."
        )
    if int(teacher_probabilities.size(1)) != num_classes:
        return zero, 0.0, zero.detach(), zero.detach()

    candidate_classes = _parse_angular_margin_classes(
        classes,
        num_classes=num_classes,
    )
    if not candidate_classes:
        return zero, 0.0, zero.detach(), zero.detach()

    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, logits)
    if target_indices is None or target_indices.numel() != logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    class_tensor = torch.tensor(candidate_classes, device=logits.device, dtype=torch.long)
    nonfocus_classes = [class_index for class_index in candidate_classes if class_index != focus]
    if not nonfocus_classes or focus not in candidate_classes:
        return zero, 0.0, zero.detach(), zero.detach()
    nonfocus_tensor = torch.tensor(nonfocus_classes, device=logits.device, dtype=torch.long)

    teacher_probs = teacher_probabilities.to(device=logits.device, dtype=torch.float32).clamp(min=0.0)
    teacher_probs = teacher_probs / teacher_probs.sum(dim=1, keepdim=True).clamp(min=1e-12)
    teacher_candidate_mass = teacher_probs.index_select(1, class_tensor).sum(dim=1).clamp(min=1e-12)
    teacher_focus_probabilities = (
        teacher_probs[:, focus] / teacher_candidate_mass
    ).clamp(min=0.0, max=1.0)
    teacher_confidence, teacher_predictions = teacher_probs.max(dim=1)

    valid = (
        (target_indices >= 0)
        & (target_indices < num_classes)
        & torch.isin(target_indices, class_tensor)
    )
    focus_logits = logits.float()[:, focus]
    nonfocus_logits = torch.logsumexp(logits.float().index_select(1, nonfocus_tensor), dim=1)
    focus_binary_logits = focus_logits - nonfocus_logits
    focus_probabilities = torch.sigmoid(focus_binary_logits).clamp(min=1e-6, max=1.0 - 1e-6)
    if bool(require_agreement):
        valid = valid & (teacher_predictions == target_indices)
    if float(teacher_min_confidence) > 0.0:
        valid = valid & (teacher_confidence >= float(teacher_min_confidence))
    if not bool(valid.any().item()):
        return (
            zero,
            0.0,
            focus_probabilities.detach().mean().to(dtype=logits.dtype),
            teacher_focus_probabilities.detach().mean().to(dtype=logits.dtype),
        )

    target_focus = teacher_focus_probabilities.detach().clamp(min=1e-6, max=1.0 - 1e-6)
    blend = min(1.0, max(0.0, float(hard_target_blend)))
    if blend > 0.0:
        hard_focus_targets = (target_indices == focus).to(
            device=logits.device,
            dtype=target_focus.dtype,
        )
        target_focus = (
            target_focus * (1.0 - blend) + hard_focus_targets.detach() * blend
        ).clamp(min=1e-6, max=1.0 - 1e-6)
    per_sample = F.binary_cross_entropy_with_logits(
        focus_binary_logits[valid],
        target_focus[valid],
        reduction="none",
    )
    weights = teacher_confidence[valid].detach().clamp(min=1e-6)
    if float(error_power) > 0.0:
        error_weights = (
            (focus_probabilities[valid].detach() - target_focus[valid])
            .abs()
            .pow(float(error_power))
            .clamp(min=1e-6)
        )
        weights = weights * error_weights
    loss = (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
    fraction = float(valid.float().mean().detach().cpu().item())
    return (
        loss.to(dtype=logits.dtype),
        fraction,
        focus_probabilities.detach().mean().to(dtype=logits.dtype),
        teacher_focus_probabilities.detach().mean().to(dtype=logits.dtype),
    )


def _late_member_specialist_losses_from_features(
    *,
    features: Optional[Dict[str, Tensor]],
    teacher_logits: Optional[Tensor],
    hard_labels: Optional[Tensor],
    targets,
    focus_class: int,
    negative_classes: Union[str, Sequence[int]],
    min_teacher_gap: float,
    hard_target_blend: float,
    preservation_slack: float,
) -> Tuple[Tensor, Tensor, Tensor, Dict[str, float]]:
    candidate_logits = (
        features.get("late_member_logits") if isinstance(features, dict) else None
    )
    primary_logits = (
        features.get("late_member_primary_logits")
        if isinstance(features, dict)
        else None
    )
    reference = candidate_logits if torch.is_tensor(candidate_logits) else primary_logits
    if not torch.is_tensor(reference):
        raise ValueError("Late-member specialist loss requires late-member logits.")
    zero = reference.sum() * 0.0
    stats = {
        "positive_fraction": 0.0,
        "negative_fraction": 0.0,
        "positive_count": 0.0,
        "negative_count": 0.0,
        "protect_positive_fraction": 0.0,
        "protect_negative_fraction": 0.0,
        "candidate_focus_probability": 0.0,
        "primary_focus_probability": 0.0,
        "teacher_focus_probability": 0.0,
    }
    if (
        not torch.is_tensor(candidate_logits)
        or not torch.is_tensor(primary_logits)
        or candidate_logits.ndim != 2
        or tuple(candidate_logits.shape) != tuple(primary_logits.shape)
    ):
        raise ValueError("Late-member candidate/primary logits must have matching [B, C] shapes.")
    num_classes = int(candidate_logits.size(1))
    focus = int(focus_class)
    if not 0 <= focus < num_classes:
        raise ValueError(f"Late-member focus class {focus} is outside [0, {num_classes - 1}].")
    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(
            device=candidate_logits.device,
            dtype=torch.long,
        ).view(-1)
    else:
        target_indices = _classification_target_indices(targets, candidate_logits)
    if target_indices is None or int(target_indices.numel()) != int(candidate_logits.size(0)):
        return zero, zero, zero, stats

    negatives = _parse_angular_margin_classes(
        negative_classes,
        num_classes=num_classes,
    )
    negatives = [class_index for class_index in negatives if class_index != focus]
    if not negatives:
        raise ValueError("Late-member directional loss requires non-focus negative classes.")
    negative_tensor = torch.tensor(
        negatives,
        device=candidate_logits.device,
        dtype=torch.long,
    )
    primary_probabilities = F.softmax(primary_logits.detach().float(), dim=1)
    candidate_probabilities = F.softmax(candidate_logits.float(), dim=1)
    primary_focus = primary_probabilities[:, focus].clamp(min=1e-6, max=1.0 - 1e-6)
    candidate_focus = candidate_probabilities[:, focus].clamp(min=1e-6, max=1.0 - 1e-6)
    primary_predictions = primary_probabilities.argmax(dim=1)
    true_focus = target_indices == focus
    true_negative = torch.isin(target_indices, negative_tensor)

    nonfocus_indices = torch.tensor(
        [class_index for class_index in range(num_classes) if class_index != focus],
        device=candidate_logits.device,
        dtype=torch.long,
    )
    candidate_binary_logits = candidate_logits.float()[:, focus] - torch.logsumexp(
        candidate_logits.float().index_select(1, nonfocus_indices),
        dim=1,
    )
    auxiliary_ce = F.cross_entropy(candidate_logits.float(), target_indices).to(
        dtype=candidate_logits.dtype
    )

    protect_positive = true_focus & (primary_predictions == focus)
    protect_negative = true_negative & (primary_predictions != focus)
    slack = max(0.0, float(preservation_slack))
    preservation_terms: List[Tensor] = []
    if bool(protect_positive.any().item()):
        preservation_terms.append(
            F.relu(primary_focus[protect_positive] - candidate_focus[protect_positive] - slack)
        )
    if bool(protect_negative.any().item()):
        preservation_terms.append(
            F.relu(candidate_focus[protect_negative] - primary_focus[protect_negative] - slack)
        )
    preservation_loss = (
        torch.cat(preservation_terms).mean().to(dtype=candidate_logits.dtype)
        if preservation_terms
        else zero
    )

    directional_loss = zero
    if teacher_logits is not None:
        if (
            not torch.is_tensor(teacher_logits)
            or teacher_logits.ndim != 2
            or tuple(teacher_logits.shape) != tuple(candidate_logits.shape)
        ):
            raise ValueError("Late-member teacher logits must match candidate logits [B, C].")
        teacher_probabilities = F.softmax(teacher_logits.detach().float(), dim=1)
        teacher_focus = teacher_probabilities[:, focus].clamp(min=1e-6, max=1.0 - 1e-6)
        teacher_predictions = teacher_probabilities.argmax(dim=1)
        gap = max(0.0, float(min_teacher_gap))
        positive = (
            true_focus
            & (teacher_predictions == focus)
            & (teacher_focus >= primary_focus + gap)
        )
        negative = (
            true_negative
            & (teacher_predictions != focus)
            & (teacher_focus + gap <= primary_focus)
        )
        selected = positive | negative
        if bool(selected.any().item()):
            blend = min(1.0, max(0.0, float(hard_target_blend)))
            hard_focus = true_focus.to(dtype=teacher_focus.dtype)
            directional_targets = (
                teacher_focus * (1.0 - blend) + hard_focus * blend
            ).clamp(min=1e-6, max=1.0 - 1e-6)
            per_sample = F.binary_cross_entropy_with_logits(
                candidate_binary_logits[selected],
                directional_targets[selected],
                reduction="none",
            )
            weights = (teacher_focus - primary_focus).abs()[selected].clamp(min=1e-4)
            directional_loss = (
                (per_sample * weights).sum() / weights.sum().clamp(min=1e-12)
            ).to(dtype=candidate_logits.dtype)
        batch_size = max(1, int(candidate_logits.size(0)))
        stats.update(
            {
                "positive_fraction": float(positive.sum().detach().cpu().item()) / batch_size,
                "negative_fraction": float(negative.sum().detach().cpu().item()) / batch_size,
                "positive_count": float(positive.sum().detach().cpu().item()),
                "negative_count": float(negative.sum().detach().cpu().item()),
                "teacher_focus_probability": float(teacher_focus.mean().detach().cpu().item()),
            }
        )
    batch_size = max(1, int(candidate_logits.size(0)))
    stats.update(
        {
            "protect_positive_fraction": (
                float(protect_positive.sum().detach().cpu().item()) / batch_size
            ),
            "protect_negative_fraction": (
                float(protect_negative.sum().detach().cpu().item()) / batch_size
            ),
            "candidate_focus_probability": float(
                candidate_focus.mean().detach().cpu().item()
            ),
            "primary_focus_probability": float(primary_focus.mean().detach().cpu().item()),
        }
    )
    return auxiliary_ce, directional_loss, preservation_loss, stats


def _late_member_precision_rule_distillation_loss_from_features(
    *,
    features: Optional[Dict[str, Tensor]],
    teacher_logits: Optional[Tensor],
    hard_labels: Optional[Tensor],
    targets,
    candidate_weight: float,
    focus_class: int,
    focus_margin_offset: float,
    correct_boost: float,
    distance: str,
) -> Tuple[Tensor, Dict[str, float]]:
    fused_logits = (
        features.get("late_member_fused_logits")
        if isinstance(features, dict)
        else None
    )
    primary_logits = (
        features.get("late_member_primary_logits")
        if isinstance(features, dict)
        else None
    )
    if (
        not torch.is_tensor(fused_logits)
        or not torch.is_tensor(primary_logits)
        or not torch.is_tensor(teacher_logits)
        or fused_logits.ndim != 2
        or tuple(fused_logits.shape) != tuple(primary_logits.shape)
        or tuple(fused_logits.shape) != tuple(teacher_logits.shape)
    ):
        raise ValueError(
            "Late-member precision-rule distillation requires matching fused, "
            "primary, and teacher logits [B, C]."
        )
    num_classes = int(fused_logits.size(1))
    focus = int(focus_class)
    if not 0 <= focus < num_classes:
        raise ValueError(
            f"Late-member focus class {focus} is outside [0, {num_classes - 1}]."
        )
    member_weight = float(candidate_weight)
    if not 0.0 <= member_weight <= 1.0:
        raise ValueError("Late-member candidate weight must be in [0, 1].")
    offset = float(focus_margin_offset)
    if not 0.0 <= offset < 1.0:
        raise ValueError("Late-member focus margin offset must be in [0, 1).")
    boost = float(correct_boost)
    if boost < 0.0:
        raise ValueError("Late-member precision-rule correct boost must be >= 0.")
    distance_mode = str(distance).strip().lower()
    if distance_mode not in {"kl", "logit_l2"}:
        raise ValueError(
            "Late-member precision-rule distance must be 'kl' or 'logit_l2'."
        )

    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(
            device=fused_logits.device,
            dtype=torch.long,
        ).view(-1)
    else:
        target_indices = _classification_target_indices(targets, fused_logits)
    if target_indices is None or int(target_indices.numel()) != int(fused_logits.size(0)):
        raise ValueError(
            "Late-member precision-rule distillation requires one hard label per row."
        )

    primary_probabilities = F.softmax(primary_logits.detach().float(), dim=1)
    teacher_probabilities = F.softmax(teacher_logits.detach().float(), dim=1)
    rule_probabilities = (
        primary_probabilities * (1.0 - member_weight)
        + teacher_probabilities * member_weight
    )
    if offset > 0.0:
        rule_probabilities = rule_probabilities.clone()
        rule_probabilities[:, focus] = (
            rule_probabilities[:, focus] - offset
        ).clamp_min(1e-8)
    rule_probabilities = rule_probabilities.clamp_min(1e-8)
    rule_probabilities = rule_probabilities / rule_probabilities.sum(
        dim=1,
        keepdim=True,
    ).clamp_min(1e-8)

    student_log_probabilities = F.log_softmax(fused_logits.float(), dim=1)
    target_log_probabilities = rule_probabilities.log()
    if distance_mode == "kl":
        per_sample_distance = F.kl_div(
            student_log_probabilities,
            rule_probabilities,
            reduction="none",
        ).sum(dim=1)
    else:
        per_sample_distance = 0.5 * (
            student_log_probabilities - target_log_probabilities
        ).pow(2).sum(dim=1)
    primary_predictions = primary_probabilities.argmax(dim=1)
    primary_correct = primary_predictions.eq(target_indices)
    weights = 1.0 + boost * primary_correct.to(dtype=per_sample_distance.dtype)
    loss = (per_sample_distance * weights).sum() / weights.sum().clamp_min(1e-8)

    student_probabilities = student_log_probabilities.exp().detach()
    rule_predictions = rule_probabilities.argmax(dim=1)
    batch_size = max(1, int(fused_logits.size(0)))
    stats = {
        "precision_rule_dense_fraction": 1.0,
        "precision_rule_primary_correct_fraction": float(
            primary_correct.sum().detach().cpu().item()
        )
        / batch_size,
        "precision_rule_primary_disagreement_fraction": float(
            rule_predictions.ne(primary_predictions).sum().detach().cpu().item()
        )
        / batch_size,
        "precision_rule_target_focus_probability": float(
            rule_probabilities[:, focus].mean().detach().cpu().item()
        ),
        "precision_rule_student_focus_probability": float(
            student_probabilities[:, focus].mean().cpu().item()
        ),
        "precision_rule_mean_absolute_probability_error": float(
            (student_probabilities - rule_probabilities)
            .abs()
            .mean()
            .detach()
            .cpu()
            .item()
        ),
        "precision_rule_logit_rmse": float(
            (student_log_probabilities.detach() - target_log_probabilities)
            .pow(2)
            .mean()
            .sqrt()
            .cpu()
            .item()
        ),
    }
    return loss.to(dtype=fused_logits.dtype), stats


def _teacher_pairwise_margin_loss_from_features(
    *,
    model: nn.Module,
    features: Dict[str, Tensor],
    teacher_probabilities: Optional[Tensor],
    hard_labels: Optional[Tensor],
    targets,
    teacher_mass_threshold: float,
    error_power: float,
    hard_target_blend: float,
    require_agreement: bool,
) -> Tuple[Tensor, float, Tensor, Tensor]:
    pairwise_logits = features.get("pairwise_margin_logits")
    pairs = getattr(model, "pairwise_margin_pairs", [])
    reference = next((value for value in features.values() if torch.is_tensor(value)), None)
    if reference is None:
        reference = teacher_probabilities if torch.is_tensor(teacher_probabilities) else None
    if reference is None:
        reference = hard_labels if torch.is_tensor(hard_labels) else None
    if reference is None:
        reference = torch.tensor(0.0)
    zero = reference.sum() * 0.0
    if (
        teacher_probabilities is None
        or not torch.is_tensor(teacher_probabilities)
        or not torch.is_tensor(pairwise_logits)
        or pairwise_logits.ndim != 2
        or not pairs
    ):
        return zero, 0.0, zero.detach(), zero.detach()
    if teacher_probabilities.ndim != 2 or teacher_probabilities.size(0) != pairwise_logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    num_classes = int(teacher_probabilities.size(1))
    if hard_labels is not None and torch.is_tensor(hard_labels):
        target_indices = hard_labels.to(device=pairwise_logits.device, dtype=torch.long).view(-1)
    else:
        target_indices = _classification_target_indices(targets, teacher_probabilities)
    if target_indices is None or target_indices.numel() != pairwise_logits.size(0):
        return zero, 0.0, zero.detach(), zero.detach()

    teacher_probs = teacher_probabilities.to(
        device=pairwise_logits.device,
        dtype=torch.float32,
    ).clamp(min=0.0)
    teacher_probs = teacher_probs / teacher_probs.sum(dim=1, keepdim=True).clamp(min=1e-12)
    teacher_confidence, teacher_predictions = teacher_probs.max(dim=1)
    mass_threshold = float(max(0.0, teacher_mass_threshold))
    blend = min(1.0, max(0.0, float(hard_target_blend)))
    losses: List[Tensor] = []
    valid_masks: List[Tensor] = []
    teacher_targets: List[Tensor] = []
    student_probabilities: List[Tensor] = []

    for pair_index, pair in enumerate(pairs):
        if pair_index >= int(pairwise_logits.size(1)):
            break
        left_class, right_class = [int(value) for value in pair]
        if right_class < 0 or right_class >= num_classes:
            continue
        logits = pairwise_logits[:, pair_index].float()
        student_pair_probability = torch.sigmoid(logits).clamp(min=1e-6, max=1.0 - 1e-6)

        if left_class < 0:
            teacher_target = teacher_probs[:, right_class].detach().clamp(min=1e-6, max=1.0 - 1e-6)
            valid = (target_indices >= 0) & (target_indices < num_classes)
            hard_binary_targets = (target_indices == right_class).to(
                device=pairwise_logits.device,
                dtype=teacher_target.dtype,
            )
            teacher_pair_mass = torch.ones_like(teacher_target)
        else:
            if left_class >= num_classes:
                continue
            teacher_pair_mass = (teacher_probs[:, left_class] + teacher_probs[:, right_class]).clamp(min=1e-12)
            teacher_target = (
                teacher_probs[:, right_class] / teacher_pair_mass
            ).detach().clamp(min=1e-6, max=1.0 - 1e-6)
            valid = (target_indices == left_class) | (target_indices == right_class)
            if mass_threshold > 0.0:
                valid = valid & (teacher_pair_mass >= mass_threshold)
            hard_binary_targets = (target_indices == right_class).to(
                device=pairwise_logits.device,
                dtype=teacher_target.dtype,
            )

        if bool(require_agreement):
            valid = valid & (teacher_predictions == target_indices)
        if not bool(valid.any().item()):
            continue

        if blend > 0.0:
            teacher_target = (
                teacher_target * (1.0 - blend)
                + hard_binary_targets.detach() * blend
            ).clamp(min=1e-6, max=1.0 - 1e-6)
        per_sample = F.binary_cross_entropy_with_logits(
            logits[valid],
            teacher_target[valid],
            reduction="none",
        )
        weights = teacher_confidence[valid].detach().clamp(min=1e-6)
        if left_class >= 0:
            weights = weights * teacher_pair_mass[valid].detach().clamp(min=1e-6)
        if float(error_power) > 0.0:
            error_weights = (
                (student_pair_probability[valid].detach() - teacher_target[valid])
                .abs()
                .pow(float(error_power))
                .clamp(min=1e-6)
            )
            weights = weights * error_weights
        losses.append((per_sample * weights).sum() / weights.sum().clamp(min=1e-12))
        valid_masks.append(valid)
        teacher_targets.append(teacher_target.detach())
        student_probabilities.append(student_pair_probability.detach())

    if not losses:
        return zero, 0.0, zero.detach(), zero.detach()
    stacked_valid = torch.stack([mask.float() for mask in valid_masks], dim=1)
    stacked_teacher = torch.stack(teacher_targets, dim=1)
    stacked_student = torch.stack(student_probabilities, dim=1)
    valid_count = stacked_valid.sum().clamp(min=1.0)
    teacher_mean = (stacked_teacher * stacked_valid).sum() / valid_count
    student_mean = (stacked_student * stacked_valid).sum() / valid_count
    valid_fraction = float(stacked_valid.mean().detach().cpu().item())
    return (
        torch.stack(losses).mean().to(dtype=pairwise_logits.dtype),
        valid_fraction,
        student_mean.to(dtype=pairwise_logits.dtype),
        teacher_mean.to(dtype=pairwise_logits.dtype),
    )


def _stack_image_masks_from_targets(targets) -> Optional[Tensor]:
    if isinstance(targets, dict):
        image_mask = targets.get("image_mask")
        if torch.is_tensor(image_mask):
            return image_mask.to(dtype=torch.bool)
        return None
    if not _is_detection_targets(targets):
        return None
    masks = []
    for target in targets:
        image_mask = target.get("image_mask")
        if not torch.is_tensor(image_mask):
            return None
        masks.append(image_mask.to(dtype=torch.bool))
    if not masks:
        return None
    return torch.stack(masks, dim=0)


